/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20050315-3","meetingId":"h17-c-budget","date":"2005年3月15日","dateIso":"2005-03-15","committee":"予算特別委員会","time":"午前１０時０３分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件抜き出しています。","topics":[{"id":"topic-01","title":"◯三上委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","agenda":"◯三上委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"おはようあります。私は、２６１ページ、交通安全対策、２６９ページ、目黒線の整備についてお伺いをいたします。","respondent":"山口交通安全担当課長","answer":"今のところの予定ですが、構成員については、鉄道事業者、大型店舗、銀行、町会等を含めて、町会等については、駅の関連する部分、概ね１００ｍから１５０ｍの区域内の町会のほうにお願いしたいと考えております。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"武蔵小山は非常に特異といいますか、決して差別ではないんですが、土地的に特別な事情があります。それは何かといますと、武蔵小山駅周辺、線路をはさんで目黒区になります。もう片方は小山三丁目、四丁目になります。商店街ごとに放置自転車の悩みがありますが、そこら辺の商店街のところ、そこらの取扱いをどのようにされるのか、お伺いをしたいと思います。","respondent":"山口交通安全担当課長","answer":"事前には目黒区のほうに働きかけていきたいと思います。商店街についても、目黒区と協議しながら進めていきたいと考えています。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"商店街は、目黒区に相談することではなくて、私が申し上げているのは、品川区内にある小山三丁目、具体的に挙げますと、駅前通り商店街、武蔵小山、パルム、一番通り商栄会、武蔵小山西口商店街等々ありますが、そこら辺の声かけはどうなされるのかということでお伺いしております。","respondent":"山口交通安全担当課長","answer":"大変失礼しました。大型商店街はもちろんご協力をいただかないとなかなか進めない問題もありますので、大型商店街のほうにも積極的にご協力をお願いしたいと考えております。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"先ほど駅を中心に１００ｍから１５０ｍということでお話を伺いました。今整備をお願いしております補助３２０号線というのがありますけれども、自転車にも増してバイクが非常に多く置いてありますが、そこらのところは対策協議会はどのような位置を占められて議論をされるのか、お伺いをしたいと思います。","respondent":"山口交通安全担当課長","answer":"二輪車については、以前も委員会でお答えしましたが、撤去はもちろんのこと、警察署の取り締まりが効果的ですので、管轄の荏原警察署のほうに協議会を通じて積極的にお願いしてまいりたいと考えております。","id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"これは補助２６号線の歩道部分の横に置くことによって、歩道部分の人が歩くべきスペースを阻害している部分があります。それについて、近年非常に普及をしてきておりますスクーターについて対策はどのようにお考えになられるのか、５０ｃｃよりはかなり大きさも、長さも、幅もありますが、そこら辺の最近出てきたスクーターについてどのようにお考えになっていらっしゃいますか。","respondent":"山口交通安全担当課長","answer":"大型スクーターの駐車ということですが、武蔵小山駅の踏切のところに新しく駐車場ができていますので、大型スクーターの駐車場を設置、駐車場を管理運営される会社等に十分働きかけて、可能なのかどうか検討をしてまいりたいと考えております。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"平日、月曜日から金曜日までは役所も動いております。警察も動いておりますけれども、とりわけ土・日の対策ですけれども、土・日の対策について特に重点を入れているようなお考えは、行政の話の中でおありになるのであれば教えていただきたいと思います。","respondent":"山口交通安全担当課長","answer":"土曜日についても撤去作業は行っておりますが、委員ご指摘のとおり、今後とも土曜日、日曜日、交番等もありますので、荏原警察署に合わせて取締方の強化をお願いしたいと思います。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"繰り返しになりますけれども、武蔵小山駅前の放置自転車ならびにバイク、これは特に土・日が非常に多くなっている状態です。私道という部分で、民地ということで、行政は入りにくい部分がありますけれども、私がお伺いしたいのは、半ば公然と公の道のように使われている私道について、行政側はどのようにお考えになるか、ご見解をお願いしたいと思います。","respondent":"山口交通安全担当課長","answer":"放置自転車、バイク等、私道にあっても、一般の交通に供される場合は道路交通法でも違反駐車等を取り締まる場合がありますけれども、そのような状況があれば、付近の私道関係者の了解を得て、放置禁止区域に指定可能であれば、したいと、今のところ検討をしています。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"可能であればということで、可能である範囲を広げていただければと思いますが、小山三丁目、せっかく協議会を立ち上げていただいて、指定をしていただきました。次に２６９ページの緑道整備ですけれども、三ブロックの地域の方の協議会が平成１５年に約４回ぐらいにわたりまして協議会が行われましたけれども、その後の協議会の経過というのはどのようになっているのか、教えていただきたいと思います。","respondent":"岩田管理工事課長","answer":"ご質問の目蒲線上部の公園化に向けましては、平成１５年度に沿道の区民の方を対象にしまして、一般公募して、約３０名程度の方にお集まりいただきまして、三つのブロックに分けてワークショップを開催し、基本計画まで作成をいたしました。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"以降、平成１６年は開かれなかったのかを１点お伺いしたいのと、開かれた結果のほうは、地域の方への周知のほうはどのような状態になっているのか、お尋ねします。","respondent":"岩田管理工事課長","answer":"ワークショップにつきましては、基本計画は昨年の２月末ぐらいでまとまりましたので、その後つくり上げました基本計画につきましては、沿道の町会の回覧板を通じまして皆さんにご周知を願ったところです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"意見","question":"今まで鉄道が通っていたところが今度は人が通るようになって、目に触れるわけで、今までは、例えば窓だけでよかったのが、今度は窓だけでは済まなくなった部分があるというふうに感じるんですが、防犯を非常に懸念されるところですが、そこらの取扱いをどのようにされるのか、お尋ねいたします。","respondent":"岩田管理工事課長","answer":"そこで、特に面した方については直接の利害関係が発生してまいりますので、そういう方たちの意見を十分聞きながら、町会の意見も聞きながら、今度は具体的に築造可能な実施案をつくり上げていく予定になってあります。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"私もワークショップに出させていただきました。すばらしい緑道ができるように期待をしておりますので、防犯上、そしてなおかつ緑の多い、きれいな緑道ができることを望みまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"２７７ページ、都市景観形成事業、２８７ページ、木造住宅耐震診断支援事業、２点で行わせていただきます。都市景観です。第三次品川区長期基本計画でも盛り込まれ、品川区としていよいよ今年度、また来年度本格的に景観への取り組みが始まります。それで、これまでの本区におきましての景観に対する取り組みを知らせていただきたいと思います。","respondent":"藤田都市計画課長","answer":"これまでの品川区におけます都市景観の取り組みですけれども、委員のほうからもお話がございましたとおり、第三次品川区長期基本計画、実施計画の中で位置づけられ、これまで進めてきてあります。その中で景観ガイドプランの策定についても位置づけられてあります。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"これまで景観のいろいろな見方があると思いますが、例えば都市計画法でありますとか、用途地域でありますとか、さまざまな手法を使って、品川区以外の各自治体、景観条例等をつくりながら、景観に取り組んでおられるわけですけれども、こういう手法が品川区においてもある一定の効力を発揮していたと思うんですが、それでもなぜ今まで品川の景観行政がなかなか前進をしなかったのか。","respondent":"藤田都市計画課長","answer":"これまで品川区におきます景観に直接係わる者としては、長期計画、実施計画の中でうたわれている項目として実施できるところはやってきておりますけれども、具体的に品川区において条例等を定めてきたところではなかったということで。","id":"exchange-013"},{"speaker":"若林委員","kind":"意見","question":"最初の説明では、最初にガイドプランをいよいよつくろうという、そういう区の姿勢としての踏み込みがあって、その後にたまたま６月に景観法ができて、１２月の施行があったという、そういう時系列的なところを聞いて、品川区として一歩踏み込んだところで追い風として景観法が後からきて、それを有効に利用していこうというふうに理解をしております。","respondent":"藤田都市計画課長","answer":"品川区におきましては、そういった核となる施設というものが特にあるわけではありませんけれども、各地域においてそれぞれ地域において、エリアにおいて核となるような施設を持ってありますので、そうした施設を地域の中でどのように景観としてのまちづくりを進めていくか。","id":"exchange-014"},{"speaker":"若林委員","kind":"提案","question":"今都市計画課長のほうから核という言葉がありました。たしか昭和６２年からでしょうか、私どものほうで提案をして、品川百景というものがあります。","respondent":"藤田都市計画課長","answer":"ただ、地域の中で景観といった観点で展開していくためには、これから地域の皆さんとそれをどのように活用して、どのように生かしていくか、そういったことを具体的に今後検討していく必要があろうかなというふうに考えてあります。","id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"景観の問題はこれから１０年、２０年、また５０年という取り組みになると思いますが、ぜひご努力のほうよろしくお願いいたします。続きまして、耐震診断のほうです。昭和５６年５月末以前に建築確認を得て云々の木造戸建ての品川区における住宅数をお知らせ願います。それから、今年度初めて創設をされたわけですが、４０件で、現在何件まで申請がきているのか、お知らせを願いたいと思います。","respondent":"片田建築課長","answer":"住宅数ですけれども、私どもの調べの中で、かなり荒い数字ですが、平成１３年度の土地利用現況調査に基づきまして、建物の棟数、これは住宅以外の建物を含みますけれども、約６万棟強の棟数があるということで認識しています。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"そのうち今年度２件が改修を行っているということでもお聞きをしております。大ざっぱに聞きますが、これを例えば区としての耐震化の目標数値というのはどのように設定されているんでしょうか。２万棟強のうち何％を、最低限は何年のうちに耐震化を診断補強を含めてやらなければいけないなという判断が、今の時点でございましたら、お聞かせ願いたいと思います。","respondent":"片田建築課長","answer":"設計事務所のほうに対しても、二、三件の耐震改修についての実施設計といいましょうか、設計を行いたいといったような相談がきているというような話は聞いてあります。それの中で、来年度目標としても４０件と。","id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"国土交通省のほうでは９０％に達するように、あと１０年ぐらいを目処にという数値目標が出されたように伺っております。一つ問題なのは、診断から改修への、施行ガイドラインといいますか、一体化がどうしても必要ではないか。設計図ができても、施行する人の意思によって図面が幾らでも変わってしまうというような恐れがありますので、その点だけ今後の取り組みを確認させて下さい。","respondent":"片田建築課長","answer":"診断の中でも、マニュアルに沿った形で、どこを補強したらいいかといったような流れを含めて、ご相談者のほうには逆に区のほうから診断の中でご提案をしているというような状況です。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"最初に公園管理費について伺います。短い期間で枯れてしまうものなどの点検などは、委託の中の条件に入っているかどうかということを伺います。それから、しながわ区民公園に続きまして、区内の公園の一定規模以上のところをスポーツ施設なども含んでいたりして、徐々に管理委託していかれるんだというふうに思いますけれども、これの今後の考え方について伺います。","respondent":"松代道路公園課長","answer":"利用される方々のいろいろな窓口等の対応、また施設の管理、これまでも直営体制でも十分サービスは重点的にやってきたわけですけれども、それ以上に民間に移りましてサービスが向上したというような利用者からの声をいただいているところです。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"歩道橋の管理のことだけで追加しますが、夢さん橋と大森歩道橋は管理委託先は、エスカレーターの管理が中心のような会社なのか、その辺の中身についてちょっとだけ伺います。","respondent":"松代道路公園課長","answer":"歩道橋の管理は、機械本体の安全性をきちんと常に確保するという意味の整備、点検、また、その周辺の清掃、あそこはドーム型になっておりますので、窓をふいたり、日常気持ちよくご利用いただけるような管理内容で委託しているものです。","id":"exchange-020"},{"speaker":"川西委員","kind":"質問・要望","question":"次に移ります。２６９ページの細街路拡幅整備事業です。この中身をお答えいただきたいと思います。一つは、工作物移設等助成金、奨励金ということで、これは何なんでしょうかということです。そうしますと、最初の計画の緑道計画というのが２０年も３０年も前からあったんですが、それは断念して、あれは処分の対象になっていくのだろうかというふうなこともありますので、その辺を伺います。","respondent":"片田建築課長、岩田管理工事課長","answer":"細街路のご質問ですけれども、細街路自体については、建築課のほうで特に私道、公道を問わず、４２条の２項道路といったような形で指定されているものについて。このうち将来的にも区として公に使う必要が考えられないような水路につきましては、基本的には払い下げ処分を順次行っていくということで進めておりまして、具体的に毎年二、三路線ずつ売却予定の計画は持ってあります。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問・要望","question":"今の最後のご答弁ですが、まだ全然お話が区にないということで、これはお答えはいいです。小さい問題ですけれども、中身をご説明いただきたいのは、２８１ページの大崎駅周辺地区コーディネート業務委託、それから、御成橋散水事業再生水利用負担金、この中身についてご答弁を下さい。","respondent":"上野都市開発課長","answer":"散水に関する費用につきましては、これは御成橋から散水施設で放水いたしていますけれども、その使用料に要する費用です。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"建築物の解体に係わる問題ですけれども、平成１５年の決算特別委員会のときにこの問題のお聞かせを願いました。このときに、解体工事に関しては何らかの形で解体に関する説明会を開けるように検討をしているという答弁がありましたけれども、その検討の状況と、結果どうなっているのか、その辺をお聞かせ願いたいと思います。","respondent":"浜脇住環境整備課長","answer":"それにつきましては、課内の中で、他地区といいますか、よその自治体の状況を調査いたしまして、そういったものについては終わったのですが、最後の規模的なものをどうするかというのが決まっていないものですから、庁内論議が整っていないですので。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"平成１５年の決算特別委員会のときですけれども、その前の平成１４年の予算か決算特別委員会のときにも、鈴木ひろ子議員がこの問題について触れまして、ですから、もう２年以上の歳月が過ぎているわけですけれども、ぜひ急いでいただきたいという思いがあります。ですから、その辺の考え方というのをもう一度ご答弁願えればというふうに思います。","respondent":"浜脇住環境整備課長","answer":"私どものほうが考えているのは、工期であったり、搬入であったり、そういったことを中心に説明をするですので、こういった化学的なものも、本当に入れられるかということになりますと、もう少しこれは検討の余地があるのかなというふうに思ってあります。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"さっきも言いましたけれども、最もアスベストが使われた時代の建物が大量に解体をされるという時期にきているわけですから、これをどうやって建設業者、事業主に、住民被害が出ないような解体を義務付けるかというのは、絶対にこれは行政の責任分野であるというふうに思います。こうした状態を長期間放置しておくというわけにはいかないと思いますけれども、もう一度ご答弁をお願いします。","respondent":"片田建築課長","answer":"アスベストの問題ですけれども、委員ご指摘のとおり、アスベストについては主に耐熱性とか、耐火性がすぐれているために、昭和４０年から多く鉄骨の耐火被覆ということで、柱とか梁に吹きつけられて、耐火構造としてきたといったような経緯があります。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"ですから、床材などは歩くたびにこすれれば古くなっていけば飛散をする。品川区が解体に関する説明会をきちんと義務付けをして、これを住民の側から監視をするという体制づくりが緊急に必要ではないかというふうに思いますけれども、実際に今は庁内でまだ論議をする部分があるという話でしたけれども、２年近くかかっているわけですから、いつになったらこれが終わるのかということもお知らせを願います。","respondent":"金井環境課長、浜脇住環境整備課長","answer":"そういうことも含めまして、広報ですとかホームページも活用して、さらにそういう指導徹底を図るということは考えてあります。私どもは当初、建築紛争の最初の火種になるということで、ちょっと騒いでおったものですから、先ほどこういった化学的なことについては若干検討が薄かったわけですので、今後そこも勉強して、早急につくってまいりたいと考えています。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、決してそれは暴露量だけの問題ではなくて、実際にそれに反応するという体質を持っていれば十分にどんな状態でも発病していくというふうになると思います。届出義務であるということだけを強調されましたけれども、実際に解体工事があった際に、きっちり法規どおりに守られてこれが解体をされているか、ここを確認をするという体制づくりまで必要ではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"区としても非常に多額の出資をして、工事中は東急電鉄のああいうことで予算が一遍に３００億円、４００億円と増えた場面もありましたけれども、でき上がって、我々の期待も非常に大きかったんですけれども、経済的にどのぐらいの効果があったのかというのを、区として調査、あるいはつかんでいらっしゃるのか、区役所としては、地下を通ったので、地代が入って。","respondent":"藤田都市計画課長","answer":"りんかい線におきます区に与えた経済効果の観点ですけれども、りんかい線が開通したことによりまして、区のほうのメリットとしては、委員ご指摘がございましたとおり、区の願いであった交通ネットワークとしての観点でつながってきたということ。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"効果が出ていないなら、なぜなのかという、そこまで踏み込んでいって、それではこういう手を打っていけば、商店街に潤いが出てくるはずだということを検討する必要があるんだろう。それをしないというのは、ただ鉄道にお金を出して、利便性を追いかけるだけ、そういう行政ではあってならないと思います。その辺を少し聞かせていただきたいと思います。","respondent":"日下部産業振興課長","answer":"そういうような効果については確かに私どもは聞いておりますけれども、今委員ご指摘の、具体的に、ではそれをどうやってしっかりと把握をしていくのか、それも大事なところだというふうに思いますので、いろいろ把握の仕方は難しい面はありますけれども。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"モノレールまで一緒にしてしまうぐらいですから、そういう意味で、経済効果が品川区にどういうふうにもたらされたかというのは、きちんとつかんでいく努力はすべき、つかみにくいということと、しないで、わからないというのは違うと思いますよ。ですから、その辺をぜひお願いしたいんですけれども、続く話にも関係してくる。あの線がなぜ品川区に必要なのか、そういう議論をすべきだと思う。","respondent":"藤田都市計画課長","answer":"ただ、ここの短絡線の部分に限って申しますと、地先の方とのご理解は当然必要だというふうに考えてありますので、その十分な説明、あるいは話し合いはＪＲのほうに行ってほしいといったことの申し入れも行ってあります。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"意見","question":"まさに短絡線、短絡的に出てきたような気がしないでもない。なぜかというと、さっき言った、りんかい線が大崎に入っていくときに総合的に大崎の線を考えられたはずなんですよね。やっぱりこういうことがＪＲにとっては必要なんだというのを出してきてほしいと思いますし、品川区としては、さっき言った、品川区なりの行政としての鉄道に対する考え方をきちんと伝えて下さい。お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"２８７ページの木造住宅耐震診断事業と、２６９ページの細街路拡幅整備事業についてお伺いします。初めに、木造住宅耐震診断ですが、予定件数が４０件と、発生の予定が５件とプレス発表に出ていますが、この理由をご説明下さい。","respondent":"片田建築課長、阿部住宅課長","answer":"４０件の理由ですけれども、先ほどもちょっとお話しをさせていただきましたけれども、実は平成７年の阪神・淡路大震災以来、他区のほうとしてもいろいろな支援制度を策定してきたというような状況があります。あっ旋の５件ですけれども、４０件の中で耐震診断を受けた中での想定です。他区の状況を見ながら、５件を想定したです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"プレス発表で「中越地震に学ぶ」という項目から出ているんですけれども、中越地震で何を学んだか。それと、中越地震が起きた後に耐震の診断をする件数というのは増えたか、教えて下さい。","respondent":"片田建築課長","answer":"その前後で１０月２３日に中越地震があったわけですけれども、今年に入って２月４日には３４件ぐらい、３月８日には、先ほど申し上げましたけれども、４２件ということで、そういう意味で中越地震はかなり近いということもありましたでしょうし。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はその評価に疑問を持っているんです。それで、中越地震も起きました、家の倒壊ということが本当に危険なんだな、命に直結してしまうんだなということであるにもかかわらず、予算を組むときに、何で４０件ぐらいなのかな。だったら、区としてもっと皆さん、耐震診断をしませんかとやるべきだと思うんです。していますと。","respondent":"片田建築課長","answer":"先ほどもご説明をさせていただきましたように、他区の実績等を含めて４０件を出したといったような経過があります。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、細街路拡幅事業ですけれども、しなければいけない道路、品川区に物凄い距離があると思うんですが、現時点でどのぐらいの達成率をしているんでしょうか。","respondent":"片田建築課長","answer":"ただ、当初の昭和６３年度の当時に持ち上げた細街路の延長、これはかなりアバウトなところがありますけれども、区道、私道を含めて２７４kmといったような総延長がありますので、そういう意味では全体から見ると達成率はまだ十分ではないと考えていますけれども。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"私からは、２７７ページの都市景観ガイドプラン作成についてと、２７６ページの公園管理費、そして時間があれば、２６１ページの放置自転車対策で、こちらのほうは放置自転車に対する撤去費用、使用料などの収支のほうから伺っていきたいと思います。","respondent":"藤田都市計画課長","answer":"懇談会のほうから提言をお受けする予定になってありますので、その提言を受けた後に最終的なガイドプランの中身を確認していくといった作業がありますので、その後印刷、製本、そういったタイミングと合わせて。","id":"exchange-036"},{"speaker":"井上委員","kind":"意見","question":"このような中でプレス発表ではガイドラインを活用した啓発活動を行うというふうにありますけれども、これを具体的にどのように考えているかということと、また、同じ２７７ページの下のほうに、区民の自主的なまちづくりへの支援という項目があるんですが、これとは何か関係があるのかというところをお聞かせ下さい。","respondent":"藤田都市計画課長","answer":"その公募をするにあたりましては、皆さん景観法そのものがまだご理解いただいていない面もありますので、先ほどの公表等と併せてリーフレット、あるいはパンフレットも作成していきたいと考えていますので、その辺を活用しながら、通常ですと。","id":"exchange-037"},{"speaker":"井上委員","kind":"意見","question":"先ほどもおっしゃったように、まちづくりを知らないと、これもいくら地区計画をつくると言っても、わからないというところが住民のほとんどだと思うんですけれども、今回のガイドプランでは品川区が市街地整備基本構想と合わせて整合性を図って策定していくということだったと思うんですが、そういう意味では、この懇談会を広く公開しながら、市街地整備基本構想のほうも知っていただいたり。","respondent":"藤田都市計画課長","answer":"公開をすることで、意見を発表するのにあたって制約が出てしまうというようなことは、当初の目的にかなわないのかなというような、委員の皆さんのご意見もございまして、懇談会の中で仕切る中で公開はしないというような形になったものです。","id":"exchange-038"},{"speaker":"井上委員","kind":"意見","question":"今の状況で言いますと、公募された方たちは発言しようと思って、何回かの機会で私たちは訴えておりますけれども、制約をされるというような判断が今の情勢には合っていないんじゃないかということで、自分たちの意見をどう発言をしていこうかということで、積極的に公募の方もいらっしゃるでしょうし、区の団体として参加された方たちもそういう思いでいらっしゃるということを。","respondent":"榎本行財政改革担当課長","answer":"それぞれの附属機関で専門委員も含めて、公募委員も含めて集まっているわけですが、その中で審議会がやろうとしていることに対してどういうふうな取り組みをしていくか、その姿勢をきちんと決めた上で審議会を進めているというのが実情です。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"今回のガイドプランのほうですけれども、まちづくりをリーフレットやパンフレットで啓発をしていくということだったんですけれども、ぜひともそういうまちづくりに関心のある地区計画をつくろうという、そこまでいったレベルの方たちではなくて、地域の方がまちづくりを知りたいとか、自分のまちはどういうふうな方向を目指して変わっていくんだろうかというような方のために。","respondent":"藤田都市計画課長","answer":"そういった中では、それぞれの地域の中で、地域の皆さんが、こんなふうなまちづくりを進めていきたいといったような形でお話があるということになれば、具体的にどうすればいいのかといったような話があれば、私どものほうとしてはそういうご依頼を受ければ。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"具体的な相談という以前に、まちを知りたいという方たちにも積極的に出ていっていただけるような何らかの仕組みをぜひつくっていただきたいということを要望して、次にいきます。２７６ページの公園管理費ですけれども、公園に関して、今区民の方たち、たくさんのトラブルの相談とか、苦情とかがあると思うんですけれども、今一番問題になっているようなことがあれば、ご紹介をいただきたいと思います。","respondent":"松代道路公園課長","answer":"私どもは２１５カ所ほどの公園を管理しておりますので、地域によってそれぞれの問題点は変わってきておりますけれども、共通して言えますのは、先日もご指摘等がありました、犬の問題、猫の問題、鳩、そういったもの、また、あとは公園の利用にあたっての細々したこと。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"昨日も地域猫ということで質問が幾つか出ておりまして、野良猫の苦情もあるということですけれども、私も勘違いをしていたんですが、地域にいる野良猫のことを地域猫というのかなと思ったら、今地域猫活動ということで、地域猫の定義があるんですけれども、飼い主のいない野良猫のことではなくて、避妊去勢手術をして、地域住民の理解を得て、世話をして、管理できている猫のことを地域猫というという。","respondent":"松代道路公園課長","answer":"私どもも猫の問題いろいろと地域から苦情が出ております。今委員からもおっしゃいましたように、私ども地域猫というような認識ではなく、本当にホームレス猫といいますか、野良猫でございまして、今一番の問題は、そういった猫が増えているということが問題です。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"ホームレス猫というのもあながち造語ではなく、地域の方とか、今は全国のそういった活動をしている人たちの中では共通用語になっているのではないかと思うんですけれども、餌をあげるだけの人たちも中にはいて、困っているというのも一つなんですけれども、その中で、餌をあげながら、捕獲をして、自分たちはボランティアのバザーなどをしながら、自費で避妊や去勢をしている方たちが。","respondent":"松代道路公園課長","answer":"私どももなるほどそういう点では少し改良の余地があるかと思いますので、今後そういった形での改良等をしてまいりたいと考えているところです。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"基本的には道路公園課は現場のことであって、所管するところは健康課が猫の、今回飼い主のいない猫にも手術費用がついたということでは、道路公園課と健康課と関係する部署が一緒になって地域住民の方との意見交換の場の運動を持っていかれたらいいかと思いますけれども、その辺のお考えをお聞せいただきますでしょうか。","respondent":"松代道路公園課長","answer":"おっしゃるように、今までも保健所、また健康課と連携をしてやってまいりました。さらに、看板等一つとってみても、いろいろな点でこれからも連携をとって対応をしてまいりたいと考えています。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"私が計算したところによりますと、撤去するだけでなくて、維持費とか、委託とかするともう少し多くなるのではないかと思うんですが、３,９００万円ぐらいということでいいんでしょうか。","respondent":"山口交通安全担当課長","answer":"現在の見込額での計算ですので、ご了解をいただきたいと思います。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"費用はマイナスであるという、年々これに係わる費用がかかっていくということですけれども、自転車自体で考えますと、今自転車で通勤している方のホームページなどをいろいろ見ますと、健康づくりという意味での効用も明らかになっていて、強いて言えば、医療保険の軽減につながったり、脱車社会ということで。","respondent":"山口交通安全担当課長","answer":"関係者ばかりでなくて、利用者、確かに予定は大井町のほうも、これからできます武蔵小山も自転車利用者を入れて、ご意見を伺って、また、学識経験者もできれば予定をしています。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２７７ページの公園・児童遊園の維持管理費と、時間がありましたら、２６９ページの道路バリアフリー事業の側溝段差解消というこの辺をやらせていただきたいと思います。私は犬についてお聞きしたいと思います。現在の区の考え方として、公園・児童遊園の中に犬を入れるというのは禁止されていると思いますが、その辺の確認をさせていただきたいと思います。","respondent":"松代道路公園課長","answer":"先日もお答えしましたように、原則として禁止をしています。しかしながら、実際犬を連れて入られているという状況は、ほとんどの公園でそのような状況にあると認識しております。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問・要望","question":"非常にびっくりしたのが、無条件に入れていいという方は７％ですが、ある程度の条件を満たせばいいんじゃないかという方が６割近くいらっしゃるという中で、その辺の区の認識と、ご感想、また、あえてここで公園と犬というアンケートをやられたという、その辺の背景がありましたら、お知らせいただきたいと思います。","respondent":"松代道路公園課長","answer":"犬を公園でどういうふうにして受け入れていくかというようなことで、これまでもいろいろと検討をしてきたんですけれども、そういう中で、どう考えていらっしゃるのか、区民の方々にお聞きしたいということで、区政モニターの方にお聞きし、また、主要な公園で聞き取り調査をし。","id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"今のご答弁だと、前向きにというか、犬との共生ということをお考えになっていらっしゃるのかなというふうに受け止めさせていただいたんですが、区内で１人で犬を２頭、３頭と飼っていらっしゃる方もいると思うんですが、分かっている範囲で、野良犬は別にして、どれくらいの頭数を把握されていらっしゃるか、教えて下さい。","respondent":"松代道路公園課長","answer":"そういう状況でございまして、私どもの感じとしましては、従前からしまして３倍、４倍増えているような、元の数字がどのくらいというのも出ておりませんけれども、非常に増えているというような状況にあります。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"公園というのは犬だけではなくて、猫もそうですし、またお年寄りから、小さいお子さんから、疲れを癒すためにちょっと昼休みに立ち寄るサラリーマンの方とか、そういったたくさんの方々が来て憩いの場としているわけですが、中には、自分の意図と違うような使われ方がされている中で、そこで腹を立てて怒るのか、ただ、そういう中で自分の居場所を見つけて去って行く方もいますし。","respondent":"松代道路公園課長","answer":"私ども実は平成１７年度から飼い主の方の意識の向上のために、通常のマナー講習にちょっと変化を持たせまして、これはもちろん保健所と連携をしながらですけれども、指導ボランティア育成というような感じで、飼い主の方に基本的なマナーを知ってもらうんですが。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問・要望","question":"次に先ほどのバリアフリーのところでお聞きしたいと思います。側溝段差解消ということで、ちょっと関連になってしまって恐縮ですが、今、私道整備はある程度順調にやっていただいているんですが、例えば区道から私道に入るときの階段ですね、こういったところに対しての助成というのは今はなされていないかと思うんですが、その辺の理由がありましたら、教えていただきたいと思います。","respondent":"岩田管理工事課長","answer":"もちろん舗装、あるいは側溝の打ち替えは対象になりますけれども、現存する階段の補修、新たに設置する手すり等、こういったものも補助対象になってあります。","id":"exchange-051"},{"speaker":"武内委員","kind":"確認","question":"整備条例でそういう形でというのは確認させていただきました。ただ、バリアフリーということで、段差のきつい階段のバリアフリー化というか、段差解消という部分では対象になっていないんじゃないかと思うんですが、その辺のご認識をお知らせ下さい。","respondent":"岩田管理工事課長","answer":"既存の部分が階段になっていて、例えばそれを車椅子の方でも使えるようにスロープにするとなりますと、これは東京都の福祉のまちづくり条例でスロープ勾配を５％以下にしなさいという基準がありますので、それにするのは大変なことでございまして。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"以前、個別にご相談をさせていただいた件についてちょっと伺った感じなんですが、非常に特殊な例で、場所は言いませんけれども、私も現地に行ってみて、普通の段差でなくて、１０段以上あるような階段のところで、そこだけ離れ小島みたいな形になっている場所がありまして、そこの方からご相談をいただいて、当然自分たちで実費も少し払いながらというのはあるんですけれども。","respondent":"岩田管理工事課長","answer":"ご指摘のところは東大井のところの件だと思うんですけれども、基本的に私道におけるそういった施設なり、物というのは私有財産に属するものですので、私どもが補助をする根拠というのは、私道でも、２ｍ５０cm以上の幅員があって、通り抜けができるような。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この中の文章をちょっと読みますと、前文の最後のほうにあるんですけれども、「東京都と特別区はこの機械を捉えて東京を取り巻く社会経済状況等を踏まえ、首都東京を魅力と活力あふれる都市へと再生すべく区部における都市計画道路全体の新たな整備方針の策定に取り組むこととしました」とありますが、東京都と特別区という考え方の中で、品川区内は６路線がこの中で示されておりますが。","respondent":"藤田都市計画課長、片田建築課長","answer":"ただいまご質問の区部における都市計画道路の整備方針ですけれども、東京都と２３区合同で策定してきたものです。建築指導費のご質問の中のケーブルテレビの関係ですけれども、品川区全体の中でまだ視聴が困難だという箇所が地域ごと約１,３００世帯強ほどあるということで聞いてあります。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"都市計画道路のほうからですと、個別に区からも要望しているという中で、具体的な名前を出してしまうと、補助２８号線、青物横丁のところがこの中に含まれました。区としてケーブルテレビをどういうふうに捉えているか、ケーブルテレビそのものについての考え方を、部署が違うと思うんですが、もう一度お聞きしたいと思います。","respondent":"藤田都市計画課長、榎本行財政改革担当課長","answer":"そのときには整備方針のほうが平成２７年までに整備または完成をさせる路線というようなことでご理解を得たつもりでございましたけれども、また今委員ご指摘のとおり。区としてのＣＡＴＶの活用ですけれども、区民チャンネルの視聴可能世帯数が７割に近くなっているという中で、実際に地域メディアとしてのそういう活用を考えていくということで、さらにそれに双方向性を生かしたものもプラスして。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ケーブルテレビのほうですが、今言った、地域メディアですとか、双方向性ということで、これからの活用を考えていく場合に、区の現在の新しく建ってくる建物、多分区民住宅は入っていると思うんですが、例えば大崎地区ですとか、開発に伴った公団の部分、東品川、そういった新しい部分の建物にもケーブルテレビというのは入っているものですか、その辺答えが分かるかどうか、お聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"ＣＡＴＶはもともと難視聴対策ということで始まっておりますので、電波障害等の場合にはＣＡＴＶを使って、それぞれのところを解消してもらうと同時に、その建物についてもＣＡＴＶを入れていただくように協力を要請しています。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"お願いしているところ、例えば公団などはその影響が出たので公団は入っているというふうに判断をしていいのでしょうか。それを後で教えて下さい。先般業者と話したときに、ケーブルテレビが入るんですかと言ったら、「いや、考えていない」と言われました。新築のときだったら、その時点で建築のほうで付ければすべて入ってしまうと思うんですが、その辺についてのお考えをお聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"聞くところによりますと、かなりお金もかかるということで、建主のほうがそういったものはできないというのが現状というふうに聞いておりますので、強くは言ってございませんが、こういうものがあるということは口頭では伝えてあります。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうじゃなくて、今の答えは答えとして分かりますけれども、これからそこに住んでもらう人に対して、区としてそれでいいんですかと。考え方としては、住む人に伝えていく、双方向の問題と、地域メディアということで考えたときに、お金がかかるから付けてもらえないで済ませてしまっていいのかなというところを感じているんですが、この辺についてお答えをいただけないでしょうか。","respondent":"榎本行財政改革担当課長","answer":"公団についてはちょっと確認がとれないので、確認がとれてからということですけれども、そこに住んでいるなるべく多くの方に見ていただくという姿勢には変わりございません。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何回も繰り返しになってしまうんですけれども、中古のマンションだと、新規加入は１００万円ぐらいと出ていたかな。個別は個別に入るんでしょうけれども、建物に設置する自体というのはそんなものでなかったかなというのが、これは私は数字を今覚えていないんですけれども、ケーブルテレビの本の中にはそんなふうに出ていたような気もするんですが、その辺数字は分かりますでしょうか。","respondent":"中尾根企画部長","answer":"ＣＡＴＶ会社側での計画ですけれども、平成１６年度でいきますと、個別住宅の加入の予定が約２,０００、集合住宅が約４,０００、電波障害が７００ということで、年間６,７００ぐらいの加入目標の計画になっております。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"時間を使い過ぎてしまったんですが、放置自転車の関係ですけれども、さっきちょっとお金の面が出ましたけれども、今まで八潮と不動前に放置された自転車の処分について、どのようにしているのか、その点から教えて下さい。","respondent":"山口交通安全担当課長","answer":"撤去保管した自転車については、返還引き取りに来たものについてはもちろん渡しておりますが、残ったものについてはリサイクル、海外供与、それでも使えないとか、残ったものについては廃棄処分をしております。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"廃棄処分の件ですけれども、区のほうからお金を払って廃棄しているという部分をちょっとお聞きしました。その辺でいいのかなと。何か廃棄に払うというのは、オートバイも廃棄にかかっているということなんですけれども、廃棄の方法が考えられないかなということでお聞きいたします。","respondent":"山口交通安全担当課長","answer":"廃棄については、年間３５０万円程度廃棄の費用がかかっておりますが、新年度から売却を検討したいと思っていますので、併せて資源の有効活用、また、二輪車についても資源の有効活用ということで売却を検討課題とさせていただきたいと現在のところ考えております。","id":"exchange-061"},{"speaker":"本間委員","kind":"意見","question":"最初に、駅周辺放置自転車対策費ですが、これには放置防止指導啓発費、撤去返還委託費等が含まれています。そして新たに大井町駅駐輪場の誘導員を配置するというようなことが書かれております。そのような中で、誘導員の作業時間帯についてどのようになっているのか、これはまだ委託になっていないのでわかりませんが、土曜、日曜日も含めて、そして作業時間帯はどうなっているのか、簡単にお願いします。","respondent":"山口交通安全担当課長","answer":"作業時間帯については、午前７時から午前９時、午後３時から午後６時等、平均しますと、概ね午前中３時間、午後３時間等を予定しております。日にちについては、月２８日を計算しております。","id":"exchange-062"},{"speaker":"本間委員","kind":"質問","question":"午前中も質問の中に出ておりましたように、土曜日とか日曜日の部分での利用客が大変多いというような話も出ておりましたので、その辺が盲点にならないような形でお願いしたいというふうに思います。それと、撤去の件ですけれども、複数回撤去された人がどれだけいるとかというふうな部分を、実際にいるんだろうと思いますが、およそのことでお分かりでしょうか。分かったらお願いします。","respondent":"山口交通安全担当課長","answer":"先ほど大変申し訳ございません、日にちについてですが、土曜日、日曜日、２８日は、新年度から武蔵小山を強化する意味で２８日ですが、ほかのところは２０日を予定しております。土曜、日曜日は省きます。","id":"exchange-063"},{"speaker":"本間委員","kind":"質問・要望","question":"そういう近くから水が取れないものだろうか。深夜にわたる不始末とか、さまざまな犬、猫の部分とかをお話ししましたけれども、きちっと対応をしていくためには、身近にそういうような場所があってよろしいのではないかというふうに思っておりますから、一時的、便宜的なということでなくして、きちっとしていただけないかなという要望にとどめておきたいと思います。高潮護岸管理費に移ります。","respondent":"矢部下水道河川課長","answer":"高潮護岸の補修の件ですが、立会川の河口部の左岸、右岸合わせて約９０ｍですが、その部分で平常水位ですと水をかぶっているんですが、大潮のときに顔を表すような部分で、鋼管矢板がちょっと腐食しております。","id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"勝島運河に面している部分は、これは高潮護岸管理費の部分に入ろうかと思いますけれども、最近の状況を見ますと、花街道をはじめとしまして、近隣の商店街とか、あるいは小学校、町会、児童センター、高齢者クラブ等々がボランティアも含めてきちっと整備をされて、きれいな姿がこれからまた春、夏にかけて出てこようかと思いますが、その辺の部分との、品川区の対応ですか。","respondent":"松代道路公園課長","answer":"しながわ花街道のご質問ですけれども、平成１４年１０月ぐらいに発足しまして、第１回の花植えということで、今年３年目に入ってまいります。","id":"exchange-065"},{"speaker":"本間委員","kind":"質問","question":"管理の件についてお答えがちょっとわからなかったんですけれども、これから春にかけて、桜の木を植えておりますが、きれいに花が咲きます。その後ぐらいに毛虫の件とか、消毒の件が出てくると思います。それから、通常、１年を通じてでは、犬の糞の後始末とか、夏になると、今度は夜の花火の打ち上げ等々の後始末等々の部分が出てきます。この辺の部分につきましてはどのようにお考えでしょうか。","respondent":"松代道路公園課長","answer":"桜の剪定、また害虫等の駆除、そういったものを基本的に私どもがやってありますけれども、日常のあそこのところの通りの清掃等は地域の方々が花植え等を含めてやっていただいているです。糞とか、花火等の管理も私どもが責任を持ってやっているところです。","id":"exchange-066"},{"speaker":"本間委員","kind":"質問","question":"これから花街道が次から次へと新しいイベントを繰り出してくると思いますけれども、あそこの水辺を使う行事がありますね。この水辺を使う行事では、地元の水上の権利を有する屋形舟等を営業している方々との関係が非常に大事だろうと思いますけれども、この辺の許可といいますか、使い勝手という部分はどのように捉えているのかを教えて下さい。","respondent":"松代道路公園課長","answer":"そういう中で、勝島運河を使ったイベントが昨年来やられてございまして、そういった中には港湾局、また水上警察と協議をしまして、水上警察も港湾局のほうも比較的協力的でございまして、イベントが成功しているというふうに地域から聞いてあります。","id":"exchange-067"},{"speaker":"本間委員","kind":"質問","question":"新しい進出といいますか、区民に喜ばれるような部分が少しずつ出てきていることは大変うれしく思っています。しかし、これからの部分で地域の皆さんとのトラブルのないような形でご配慮をお願いしたいというふうに思います。それから、その関連ですが、立会川の護岸の緑化についてどのようにお考えでしょうか、お答えをお願いします。","respondent":"松代道路公園課長","answer":"そういったことの延長線上で地域の方とお話をしながら、皆さんにとって、地域にとって、管理も含めていいものがあるのか、話をしながら、緑化を進めていきたいと考えています。","id":"exchange-068"},{"speaker":"本間委員","kind":"提案","question":"再開発協議会が平成１５年８月ぐらいに立ち上がって、それ以降昨年の１２月に再開発準備組合の設立等々というふうに進んできておりますが、ここの部分につきましては、当初の目標としまして、都市計画の提案に向けて高度利用地区の変更、そして第一種市街地再開発事業の決定等々を骨子としたものを提案するというふうなことを、その総会でお話がなされてきておりましたが。","respondent":"上野都市開発課長","answer":"そこの審議会におきましてご審議の上、計画決定していただけましたならば、来年度組合設立、平成１８年度着工、平成２０年度竣工に目指して詳細の検討を進めていくという予定です。","id":"exchange-069"},{"speaker":"本間委員","kind":"質問・要望","question":"これが、ともすると補助１６３号線の拡幅のみに事業が進んで、一本橋の地区の再開発という部分が頓挫しないような形で、前々からお話をしているわけですが、今度の大井町西地区の部分と背中合わせといいますか、隣合わせになっている部分ですので、どうかその辺の部分も含めてこれから地域の皆さんの要望を取り込んだ形の中で。","respondent":"藤田都市計画課長","answer":"こちらの補助１６３号線のところにあります電線溝共同予備設計業務等につきましては、現在新たにつくる都市計画道路につきましては、すべて電線共同溝にしていくといったような形の国の方針が示されてあります。","id":"exchange-070"},{"speaker":"本間委員","kind":"質問","question":"そうしますと、同じ２６７ページのところに補助１８号線にもそのような部分が載っておりますけれども、まちの景観、将来のまちづくりの発展につながる部分として、電線の地中化ということを念頭に入れての予算計上、いわゆる設計委託だというふうに考えてよろしいでしょうか。","respondent":"藤田都市計画課長","answer":"委員ご指摘のとおり、都市計画道路を進めていく中で、景観にも配慮したまちづくりを進めていこうということで、こういった形で載せさせていただいているものです。","id":"exchange-071"},{"speaker":"本間委員","kind":"意見","question":"すでに話が立ち消えになっているかもわかりませんけれども、補助１６３号線の拡幅に伴って、従来のバス路線の変更について、どのようなお話が地域で出ていたのかについて分かる範囲でお聞かせ下さい。","respondent":"藤田都市計画課長","answer":"現在、補助１６３号線は用地買収等を進めてありますけれども、併せて東京都のほうの事業、補助２６号線のほうについても事業がどんどん進捗してきてあります。","id":"exchange-072"},{"speaker":"本間委員","kind":"質問","question":"補助２６号線の絡みもあってですが、これまで私たちは、一度出かかった話が、バス路線の変更についてのお話が立ち消えになったというふうに受け止めておりましたけれども、補助２６号線、補助１６３号線の進捗状況に合わせて東急電鉄と現在折衝中であるというふうなことでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"私は、２８７ページの耐震診断と改修工事について伺いたいと思います。午前中も質問がありまして、私は聞いておりまして、ちょっと心もとないなというふうに思いまして、質問をします。建物倒壊で最大４,４００人が死亡する。ほかの自治体を見るのではなくて、現実から見なければいけないと思うんですけれども、そういう目標を考えて、つくっていくというお考えはどうでしょうか。","respondent":"片田建築課長","answer":"その中でも、４０件の中で、今の状況では１件が改修を行いたいといったような状況も含めてきております。そんな中で、今後の状況を踏まえて、その辺は検討する課題だと私は考えてあります。","id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ目標を、国のほうもいろいろ検討を始めているようですので、実態に合わせた目標、計画にしていただきたい、このことを強く求めたいと思います。当時働き盛りで、ローンを組んで家を購入しても、すでに２４年経っていますと、当然定年になっている人が多いと思いますけれども、こういうところの方々にどういうふうに対応するのかというふうに思うんですけれども、そこのところの考え方はいかがでしょうか。","respondent":"片田建築課長","answer":"それと、高齢者の対応ですけれども、当初この事業を立ち上げたときから特定の高齢者、あるいは障害者ということも考えようによっては他区ではそういうことを検討しているところもありますけれども、品川区としては区全域を基本的には対象とした中で。","id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、そこのところの、実際に今必要とされている、昭和５６年以前の建物ですから、高齢者が多く住んでいるだろうと。私は、そこでそういう考えでやっていると思うんですよ。ですから、融資の制度はこれはこれで大事だと思うんですけれども、融資を受けられないだろうと思われる方々の対応というのを改めて求めたいと思うんですけれども、その考え方をもう一度お願いしたい。","respondent":"阿部住宅課長","answer":"もう１点、改修費用ですけれども、現在耐震診断を受けた方の平均が大体１５０万円ですので、今回の耐震改修についても一応１５０万円を想定しております。それを本人負担が０.９％の利率で貸し付けるという考えです。","id":"exchange-076"},{"speaker":"宮崎委員","kind":"質問・要望","question":"耐震診断を受けて改修という、この流れを否定しているわけではないんですよ。ですから、このことも併せて、目標もきちっと持つ、必要な補助制度もつくるということで、今の区の実態、区民の実態に合った耐震化を進めていただきたい、このことを強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"築舘委員","kind":"質問","question":"２６１ページの交通安全対策費と、２７６ページの公園管理費について質問をいたしたいと思います。交通安全対策費ということで、交通事故の負傷者、死亡者が年々減っているということで、大変いいことなんですけれども、高齢者の事故というか、歩行中の事故や、自転車や、乗車中の高齢者の事故が増えていると。","respondent":"山口交通安全担当課長","answer":"高齢者懇談会等の席に出かけていきまして、安全教育等も行っているところです。今後の対策については、どうしても限られた高齢者の方に偏りがちなので、少人数の出前型の安全教育をこれから警察と日程を調整しながらかみ合えば実施していきたいと考えております。","id":"exchange-078"},{"speaker":"築舘委員","kind":"質問","question":"シートベルトを着用していない人は、着用している人の１７.３倍も死亡率が高いというようなことも、品川区の交通事故と対策の本で言われておりますけれども、シートベルトをしている人は大分増えてきましたけれども、携帯電話も点数は減るぞということで、大分少なくはなっているんですけれども、その辺の警備をするのはなかなか大変だとは思うんですが。","respondent":"山口交通安全担当課長","answer":"本件につきましては、警察と協力して安全教育を行うとき併せて引き続き携帯電話の使用禁止等を呼びかけていきたいと考えています。","id":"exchange-079"},{"speaker":"築舘委員","kind":"意見","question":"自動車の駐車違反も、一時は凄くやっておりましたけれども、今もやっているのかもしれませんが、これから民間に委託されるというようなことも言われているんですけれども、その辺は今後どういうふうになるかということ。それから、区役所通りなど大井の交通安全協会の皆さんが月４回、駐車違反の人の車にシールを貼って、警告をしているということですが、その駐車違反対策をお願いします。","respondent":"山口交通安全担当課長","answer":"駐車違反の関係、民間委託というお話ですが、これも道路交通法改正で、来年の６月からの実施の予定です。あくまでも現場の駐車状況を写真等で証拠等を保全して、取り締まりについては、切符とか、そういう関係については警察官です。","id":"exchange-080"},{"speaker":"築舘委員","kind":"確認","question":"公園の管理委託、先ほど川西委員からも質問が出ておりましたけれども、しながわ区民公園の植栽などを民間委託をするということですけれども、それにおいて大井土木事務所に統合されるということですが、その辺の、今いるしながわ区民公園の皆さん方が大井土木事務所に移って、どういう形の仕事の内容をしていくのか。その辺をちょっと確認しておきます。","respondent":"松代道路公園課長","answer":"今後の管理等につきましては、現在３事務所にそれぞれ作業職１０名ほどがおりますけれども、行く行くはすべて民間委託で管理運営をしていくというような形にしていこうと考えているところです。","id":"exchange-081"},{"speaker":"築舘委員","kind":"質問・要望","question":"１００名から３０名にということで、またその後もどんどん減らしていくということで、行く行く民間委託にするということですので、凄い行政改革がされているということと、また、民間でのサービス向上を目指すということで、民間委託をすることによっても、また民間のしっかりと監視といいますか、質の選択といいますか、そういうのをしっかりしていただきたいなというふうに思います。","respondent":"松代道路公園課長","answer":"概ね午前中の２時間半から３時間でございましたけれども花植えをしまして、その前に区民の方が花植えをしておりましたので、区民の方と職員との花植えで、現在いい状態になっておりますし、これからもそういう形でいい管理をしていきたいと、このように考えているところです。","id":"exchange-082"},{"speaker":"築舘委員","kind":"意見","question":"そういう意味では、屋上緑化の問題も、今度北側の老朽化したフェンスも撤去して、屋上緑化を増やすということですけれども、その点どんな形にするのか。そして、８階の会議室の温度が２.５度下がったというような、ヒートアイランド現象に対する効果を屋上庭園で実験をしたというようなことですが、その点ご説明願います。","respondent":"鷹倉経理課長","answer":"床面につきましても、健康的なことが何か工夫できないかとか、あるいは視界がいいような形で工夫ができないか等の検討を今重ねているところです。","id":"exchange-083"},{"speaker":"嶋委員","kind":"質問・要望","question":"なぜかと言いますと、私は、思いやり信号をずっと要望をしてきたこともございまして、今品川区では青信号、延長信号と言って、そういう意味では、いろいろな箇所で大分思いやりの信号になってまいりましたが、今信号機のランプが５段階ぐらいになって、品川区の場合は点滅なんですが、１個ずつランプが消えていく、あとどのぐらいで赤になってしまうかという信号機が大分設置をされております。","respondent":"山口交通安全担当課長","answer":"鮫洲の関係につきましては、委員はじめ町会の皆さんの絶大なご協力によりまして、また、京浜急行の協力で一掃することができました。今後とも違法駐車、放置駐車をしないように巡回し、撤去に努めてまいりたいと思います。","id":"exchange-084"},{"speaker":"嶋委員","kind":"質問・要望","question":"青信号、延長信号は２１カ所に増えたということで大変うれしく思います。これはどういうふうにして管理を、ある程度来た方が満足して帰っていただけるような魚の数というものが、釣り堀という以上、魚がある程度、このスペースには何匹いるというのが基本にあると思うんですが、そこら辺のお考えをお聞かせいただきたいと思います。","respondent":"松代道路公園課長","answer":"委員のご指摘ですので、ちょっとその辺も少し調査をしてみたいと思いますが、楽しんで帰っていただけるようにしてまいりたいと思います。","id":"exchange-085"},{"speaker":"嶋委員","kind":"質問・要望","question":"区民の切ない楽しみといいますか、ぜひそこら辺をご配慮いただけたらと思います。それから、水処理施設の改修工事の５,８００万円の内訳をお聞かせいただきたいと思います。","respondent":"松代道路公園課長","answer":"それらをつくった当時からかなりの年数が経ってきておりまして、施設の老朽化に伴う改修です。","id":"exchange-086"},{"speaker":"嶋委員","kind":"質問","question":"そこには区民が歩けるような歩道みたいになっていくのか、私は凄く期待を大きくいたしまして、全然違うイメージがありまして、夏場はプールがありますけれども、有料でもいいから、温水プールにぜひしてもらいたい、また、そういうこともあって、この５,８００万円の中に入っているのかという希望で、お聞きをいたしました。もう一度今の埋め立てのことを詳しく教えていただけますか。","respondent":"松代道路公園課長","answer":"埋め立てをする際に、平和島側と立会川のほうに埋め立ての下にカルバートボックスというものを２本設けまして、平和島側の海水と立会川のほうの海水とカルバートボックスの中で交流するように、かつ平和島側の海水が比較的きれいですので、その水を取り入れて浄化して。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、品川区の葬祭場の設置に関する環境指導要綱のことについてお聞きをしたいと思います。品川区では桐ケ谷斎場をめぐる大きな運動を背景に、他区に先駆けてこの指導要綱が制定をされました。その後各地で葬祭場の建設をめぐる紛争が起こって、品川区のように要綱をぜひつくってほしいという住民からの運動や、議会からの要請があって、幾つかの区が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２８７ページです。このことが１点です。これは明確に事業主が要綱違反だというふうに思うんですけれども、そのところも区としても違反というふうに捉えているのかどうなのか、このことを１点お聞きしたいのと、なぜ確認申請を出すのは区長との協定書を締結するまで待ってほしいというふうに指導ができなかったのかという点についても教えていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"その要綱に基づきまして業者のほうは２回の説明会を行ったですので、私どもといたしましては、この要綱の内容について、業者は説明をしようと思った部分があるわけですけれども、住民とのちょっとしたトラブルがあって、なかなかそこに到達しなかったです。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは報告書を見ていただいて分かっていると思うんです。だから、そういうふうな事態の状況の中だということは、住民からも説明されていると思うんですけれども、引き続き６項目についてきちんと説明をしてほしいと、こういう指導をしていただきたいということが一つです。この視点で、区として住民がこれだけ求めているわけですから、毅然とした態度で指導をしていただきたいというふうに思っているんです。","respondent":"中谷まちづくり事業部長","answer":"区長が住民の方と２月１５日にお会いいたしまして、そのとき申しましたのは、説明会につきまして不足であれば、もう一度やらせるということで、もう一度やるように、区として努力すると、このようなご説明を、須藤委員も同席されておりましたが。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ住民の側に立って、この実態をぜひ見ていただいて、一つは、きちんとした説明会をこれからも、１回や２回で終わらせることなく、住民が求めるところで理解を得るように努めるというふうな立場で説明会を開いていただきたいということと、その説明会が開かれるまでは協定書は結ばないでいただきたい、こういう陳情が挙がっていますけれども、これに対してぜひ行っていただきたいというふうに思うんですが。","respondent":"中谷まちづくり事業部長","answer":"要綱の件ですが、業者のほうから言わせますと、すでに区に出して１０日以上過ぎても要綱の許可を出さない……。","id":"exchange-091"},{"speaker":"須藤委員","kind":"質問","question":"品川区が要綱をつくった理由を今部長が少ししゃべられて、時間がなかったので、そのことをご説明願いたいのと、それから、他の区で要綱をつくっていますけれども、品川区はそこと接道する部分が４ｍという数字を出していますが、他区ではどのくらいの広さで接道しているか、そのあたりを教えて下さい。","respondent":"中谷まちづくり事業部長","answer":"他区の要綱、先ほども鈴木ひろ子委員からお話があったとおり、これはすべて他区は品川区の要綱を見て作成したですが、一番違うところは、あとのものにつきましては、杉並区、足立区等の例を見ますと。","id":"exchange-092"},{"speaker":"須藤委員","kind":"質問","question":"そこが一番問題かなというふうに我々は思っています。接道部分が４ｍしかないということは、細街路の前で消防車が入るよという考え方でつくられた数字だと思うんですけれども、やはり６ｍぐらいないと車が２台すれちがったりするというとき、非常にきつさがあるよと。いかがでしょうか。","respondent":"中谷まちづくり事業部長","answer":"委員ご指摘の、前面道路につきまして６ｍですが、ちょっと補足しますと、品川区の道路につきましては、６ｍ以上ありますので、要綱を改正しても前面道路の幅だけですと、ちょっと規制は難しいかなと思いますが、今の要綱が４ｍになっているということでは。","id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問","question":"先に臨海高速鉄道のほうですけれども、これは簡単であります。大井町の地上部から地下まで約４分間かかるわけでありますので、地上部分で、例えば電車の発着時間とか、事故等の状況等をＰＲしたほうがいいのではないかということの質問をして、答弁をいただきましたので、その後の検討方とか、どういうふうな動きをしているかということをお聞かせ下さい。","respondent":"藤田都市計画課長","answer":"概ねＪＲのほうとは方向付けが一緒になってきたというふうに聞いてありますので、今後もＪＲ口、東急口とも案内表示を、平成１７年度のなるべく早いうちに設置ができるように、今後も強く要望をしてまいりたいというふうに考えてあります。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ならば、それをもっと利便性を向上していくという意味で、非常に安価な話であって、それから許可をどうこうするだけの話で、結果として多くの皆さんにつながっていくわけですから、できれば平成１７年度中に電光掲示板を付けていくとか、具体的な目に見える形での対応をぜひお願いしたいと思いますが、もう一つ答弁をいただきたいと思いますが、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"東京臨海高速鉄道の会社のほうとしては必要性を感じており、そういった方向で調整をするといった形で言ってあります。相手があることですので、そうした関係の中から、区のほうからも一日も早く設置ができるように要望をしてまいりたいというふうに考えてあります。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"確認","question":"水族館ですけれども、新しくできることはもちろんいいんですが、これからの考え方として、しながわ水族館にいかにお客を呼んでくるかということ、例えば教育施設の強み、それから行政が係わっている強み、さまざまな利点があるわけですけれども、まず、確認だけしたいのが、しながわ水族館をこれからどういうふうにしていこうかという大きな基本的な考え方をお聞かせ下さい。","respondent":"松代道路公園課長","answer":"水族館の今後の運営ということで、先般もちょっとご紹介しましたけれども、世論調査の結果等で区民がどのように考えていらっしゃるかというようなことで見ますと、当の水族館、約６割の方がご利用いただいているということを踏まえて、いろいろとご意見をいただきますけれども。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"提案","question":"二、三提案ですけれども、例えば教育施設の面からすれば、都内を含めて、近隣の幼稚園、小学校、そういうところへのこの水族館の売り込み、ＰＲをどうしているかということ。ですけれども、いずれ飽きられますから、そのことをよく考えていくと、いろいろな方法で経営の方法を考えていかないといけないと思うんですが、いかがでしょうか、ご見解をお聞かせ下さい。","respondent":"松代道路公園課長","answer":"当然それまでの間にバスの今後の運行形態のあり方、そういったものも検討していきたいというふうに考えておりますので、ご提案があった件も含めて、今後検討をしたいと思います。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この水族館ができた当時のことを思い返しますと、非常にたくさんの人が来られております。うれしいことに、この間行ったときにもたくさん来られておりました。ですから、こういう好調さをぜひ維持していただきたいということをお願いするんですが、大きな方向性を最後にまちづくり事業部長から、これからのしながわ水族館の考え方とか、将来構想をお聞かせいただきたいと思いますが、いかがでしょうか。","respondent":"中谷まちづくり事業部長","answer":"今後とも区民の皆さんから見えるまちづくり事業、こういうことを肝に銘じて進めていきたいというふうに考えておるところです。","id":"exchange-098"},{"speaker":"土井委員","kind":"質問","question":"補助１６３号線については、先ほど来話がありましたが、いわゆる一本橋地区を中心とした、そしてまた、補助２６号線との関連を含めた部分が今話題になっているわけですけれども、残りのところは進捗を含めてどのような方向になっているのかというところをお伺いをしたいというふうに思います。","respondent":"岩田管理工事課長、藤田都市計画課長","answer":"これはだれがやるかということですけれども、これは地方公共団体です品川区が品川区全域を行うということで、現在の計画では約５０年を費やして実施をしていこう。現在、事業中です補助１６３号線のほうが平成２０年度までの事業認可になってあります。その辺の進捗と合わせて、委員ご指摘の補助１６３号線のほうにつきましても事業を進めていきたいというふうに考えているところです。","id":"exchange-099"},{"speaker":"土井委員","kind":"質問・要望","question":"補助１６３号線は分かりました。それから、密集市街地整備促進事業と大きく関連をして、従前居住者用住宅管理費があるだろうというふうに思うものですから、密集市街地整備促進事業がどういう形で今進んでいて、どういう状況にあって、その中で従前居住者用住宅はどのように使われていて、どういう状況になっているのかということをちょっとお聞かせをいただきたいというふうに思います。","respondent":"矢部下水道河川課長、浜脇住環境整備課長","answer":"２番目の損害という話ですけれども、今回、設計変更ということで約１億２,０００万円減額補正をしております。荏原北地区は今年度で終わりますけれども、来年度は２地区の継続、あるいは将来の３地区の導入といったようなことを見据えまして、今後とも密集事業のために使っていこうというふうに考えてあります。","id":"exchange-100"},{"speaker":"土井委員","kind":"質問・要望","question":"建設工事ですから、ミリ単位の話をしようなんて思っていませんけれども、数ｍにわたって動いているようなお話だったので、今までいろいろ聞きましても、確かに埋設物がよくわからない部分というのはたくさんあるというのは分かりますけれども、これはあまりにもひどいというか、図面が直されていればどうということはなかった話ですから、そういうものも含めると。","respondent":"矢部下水道河川課長、浜脇住環境整備課長","answer":"下水道の幹線が、実際竣工図に比べると、大きいところでは４ｍ程度ずれておりまして、その辺の理由等は下水道局ともいろいろ話をしているんですが、ここの管が埋設されたのが昭和４０年代で、なおかつシールド工事でやっておりまして。従前居住者用住宅の活用ですけれども、既存地区として来年度は旗の台、中延、戸越一、二丁目というのがあります。それについては、予算書にあるとおり、建て替え等を積極的に進めたいというふうに考えてあります。","id":"exchange-101"},{"speaker":"土井委員","kind":"質問","question":"よく超音波でやると、どこに何があって、何か異質なものが入っているよとか、そういうのが調査できる技術もあるのではないかと思うんですけれども、その辺はないのか、あるのか、あるような気がするんですけれども、そういうものは相当お高くて、とてもということなのかどうかも含めて、これから場合によっては大きな工事のときで、怪しいときには調べざるを得ない部分があるんじゃないかなと。","respondent":"矢部下水道河川課長","answer":"基本的に埋設物の深さが浅い、１ｍとか１ｍ５０cm程度のところにつきましては、実際に掘さくをして、位置を確認するというのが基本です。超音波探知機とか、そういうのもあります。ですが、今回の下水管は土被りが５ｍ程度ありまして、今５ｍまで調べる技術はございません。","id":"exchange-102"},{"speaker":"中島委員","kind":"質問・要望","question":"２７１ページの私道舗装工事費ということで質問をします。水道工事とか、ガス工事で掘さくした後の舗装というのはどこが責任を持って、どのような連携があって、後の補修がされるのか、この点を１点お伺いしたいと思います。そういうことから、あのときはまだ緩和したばかりなのでということで、ご答弁をいただきましたが、再度ここで要望とともに、質問をします。","respondent":"松代道路公園課長、岩田管理工事課長","answer":"そういったときに極力予定がないところの企業でも、この際合わせて順番で改修をして下さいというような調整をしまして、順次企業者が水道、ガス、電気というような形で順番にしまして、工事をし終わった後、仮舗装をします。滝王子通りの避難道路の機能強化の検討経費ですけれども、滝王子通りが広域避難場所である大井競馬場および大井ふ頭への広域避難道路になっておりますけれども。","id":"exchange-103"},{"speaker":"中島委員","kind":"質問・要望","question":"これは要望にしておきます。そういった意味では、この計画が早く進むように願っております。温かいご配慮をされているということで、今お伺いしました。確かにそうだとは思います。先ほど武内委員からもいろいろなことがありましたけれども、そういった意味で、今後の高齢化社会の中で、もう一度これは要望しておきたいと思いますので、時間がありませんので、最後に要望して、これを終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２８０ページ、都市開発費でしょうか、武蔵小山駅東地区まちづくりの予算がどこに入っているのか教えていただきたいのと、２８５ページ、都心共同住宅供給事業、この点で伺います。都心共同住宅のところは、この事業の総事業費と、補助金額、補助率、そして今後この事業がどのように進んでいくのか、お教え下さい。","respondent":"浜脇住環境整備課長、上野都市開発課長","answer":"今の都心共同住宅に関するご質問ですけれども、都市計画的なこと、あるいは近隣との説明会等々がまだ終わってございませんので、最終的な図面がまだでき上がってございません。そういった中で今、額を確定できない状態におります。都市開発費と武蔵小山駅東地区の予算がどこに計上されているかですが、２８１ページ、２８３ページには該当はございません。２８５ページの事務用経費の中に、地元協議会のまちづくり補助金を１０万円計上しています。","id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"都心共同住宅のところは、まだ現在総体を把握していないということですけれども、現段階で推測して入っている金額なんですか。この五千某が何にあたるのかなというところをひとつ教えて下さい。","respondent":"浜脇住環境整備課長","answer":"これは低く見積もっているといいますか、そういった意味では、出来高でお支払いするものですから、先ほど言ったように、額が決まった後で、３月３１日にこれだけできますよと言ったときにお支払いをするという仕組みになってあります。","id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"基本的なことをお伺いしたいんですが、今回の都市計画３.１haの範囲の地権者の数と、言うなれば、権利がないといわれている借家人の方、それぞれ世帯と、３.１haでの同意率を教えて下さい。２点目は、整備地区計画にかかっている０.８haの部分の地権者数と、借家、借間人の方の世帯数と、ここの同意率をもう一度教えて下さい。","respondent":"上野都市開発課長、浜脇住環境整備課長","answer":"そのうち地区整備計画区域内につきましては１２０名の方がおられます。その方々の同意率が今のところ約８割となっています。世帯数につきましては、地区全体といたしまして９.１haにつきまして約五百数十世帯です。私どものほうにきています都心共同住宅供給事業の権利者数は３９名でございまして、アパートの数が６１、店舗数は１５というふうに聞いてあります。なお、同意率につきましては、１００％同意しているというふうに聞いてあります。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問","question":"安全なまちづくりを住民の総意でつくりたいという、こういった思いは皆さんは同じなので、この立場で質問をしていきたいんですが、まず最初に、整備地区、０.８haの中で約８割の方が同意をされている。この間１２月と１月に素案ができてからの説明会を２回していますけれども、ここに関して何割ぐらいの方が参加しているのかをお聞かせ下さい。","respondent":"上野都市開発課長","answer":"今回の都市計画につきましては、主に昨年１１月、１２月以降地元協議会におきまして精力的に合意形成を進めてきているところです。その合意形成の過程で都市計画素案を添付してこの整備計画区域内の地権者の方の同意を取得しているというふうに聞いてあります。","id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「とにかくあなたのところが最後だから、何とか同意をしてほしい」と、不動産屋とともに何回も来て、土下座をされて、渋々判を押したという方もいて、後で、６０ｍ、そんなに高い建物だったのかと、驚いて、ショックを受けたという話を何件からか聞いているんです。私はぜひ話し合いをこれからもきちんと指導していただきたいと思うんですが、この点いかがでしょうか。","respondent":"上野都市開発課長","answer":"計画の内容につきましては、都市計画に先立ちます街並み再生方針の地区の指定のときから区も含めて地元に将来像のご説明を含めてしています。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私のところにいらっしゃった方では、「私個人で言えば、うかつにも約２年ぐらい前にある人を介在して判を求められました。こういうところでは、凄く行き違いがあるし、１００％同意ですよというところで、そうですかとは、とても受け止められないなと思うのが１点です。この点またお答えいただきたい。","respondent":"浜脇住環境整備課長、上野都市開発課長","answer":"これは一般質問でもあったとおり、武蔵小山の密集市街地は老朽した店舗や住宅が多いわけですけれども、その共同化について地元の方々が自分の権利を持ち寄ってやるですのて。合意形成の点での追加のご質問ですけれども、今回の都市計画素案につきましては、先ほどの整備計画地区内の方々を対象といたしまして、地元協議会事務局から地区計画の素案を添付した上で、返送用封筒にて。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"合意形成に関してはすべて郵送で取扱っているということですか。どこにその郵便が届くのか、もう一回教えていただきたいと思います。土地の権利のない方については家主から説明をするということですが、私は、そこが問題だと思うんです。私は、都民というところは、広くそこに生活をする人、営業をする人すべてが含まれると思うんですが、その点はいかがでしょうか。","respondent":"上野都市開発課長","answer":"これは素案のしゃれた街並みづくり推進条例に基づく街並み再生地区を指定する段階から地元の方の要請に基づいて、区のほうに働きかけがあり、それに基づき調査、検討を進め、今の都市計画の段階に至っているものです。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"意見","question":"地元の要請というところですが、私はそこが問題だと思うんです。この地域はせいぜい１０階建て、補助２６号線沿いでも１４階建てなのに、どうして１９階建てなんて、おかしな話だと思います」ということと、目の前の方ですが、「集合住宅に住んでいるというところで、全く話が入ってこない」、地域の方が全く情報がないということを、区はどう捉えていらっしゃるか、お聞かせ下さい。","respondent":"上野都市開発課長","answer":"まちづくりを進めるにあたりましては、さまざまなご意見があろうかと思いますが、先ほどもございましたように、地元の方々の主体的な取り組みに基づいてこのまちづくりは進めてきているところですし、今回の都市計画法の手続きに基づいて粛々と手続きを進めているところです。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問","question":"私は、２８１ページ、街路照明費ならびに２７９ページ、公園管理費、これは運動施設ですね。街路照明費について、街路灯についてちょっと質問なんですけれども、例えば東京電力が何か事情で故障して送電できなくなった、そのときに、大概室内は、ビルなどは電源が落ちても非常灯がつきますよね。その辺街路灯は電源が全部東京電力から送られなかったら全く機能しないんでしょうか、その辺お聞かせ下さい。","respondent":"松代道路公園課長","answer":"基本的には東京電力からの送電が止まれば消えてしまいますけれども、一部ハイブリットもしくは、そういったときの防災用の照明というものを、これはまた公園のほうの設置段階ですけれども、そういったものを今設置しつつある状況にあります。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"そういうのを、例えば街路灯に１００ｍ間隔でもいいし、３００ｍ間隔でもいいんですけれども、そういうのは設置できないんでしょうか、それだけちょっとお答え下さい。","respondent":"岩田管理工事課長","answer":"先ほど道路公園課長がお答えしましたけれども、いわゆる非常電源装置といわれる、街路灯に適用するようなものというのはバッテリー程度しかないんですけれども、こういったものというのは、街路灯は大体２００Ｗから１５０Ｗの電球を使いますので。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"一応終わりますけれども、できれば何か工夫して、夜中に震災等もあるかもしれないので、ところどころそういうふうに、電源がおりたら自動的につくようなシステムをつくれるといいなと、要望します。外はお子さん連れ、またご年配の方が歩いているんですけれども、なぜ数十ｍにわたって両側は低いのか、その辺をお答え下さい。","respondent":"松代道路公園課長","answer":"管理上、ボールが出るですけれども、私どもの管理面からそれが頻繁に出て、ゲーム等に支障があるというようなことは、今のところ確認してございませんけれども、いかんせん、フェンス自体は縦方向の部分は非常に高いフェンスですけれども、今委員のご指摘のとおり。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"しながわ水族館、今回リニューアルで７億３,８００万円の費用を使うわけですけれども、これは水族館のみでしょうか。それでおそらく大勢の方がリピーターとして来ているんじゃないかと。でも、しながわ区民公園のほうは本当に見て、あそこにしばらく遊んでいても楽しい場所だと思うんですけれども、その辺、周りの植栽を含めて、リニューアルというか、替えるような方向性はあるんでしょうか。","respondent":"松代道路公園課長","answer":"ですから、私どもは植栽の管理というところに非常に力を入れておりまして、そういった点では勝島の海という、海の周りの松の手入れとか、そういったものについては普通の公園以上に手入れ等には重点を置いてやってありますし、ほかの施設は計画的に改修等をやりながら。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこはもちろん歩かれては困るんでしょうけれども、ちょっとそういうことも要望をします。せいぜいずれても１ｍぐらい、ですから、結局どんなところでも、どんな乗用車でも何でも死角というのは出ます。そうすると、かなり安全度というのはふくらむんじゃないかと思うんですけれども、その辺将来像と、ご見解、今の側道の混雑状況、危険だと思うんですが、ちょっとお聞かせ下さい。","respondent":"山口交通安全担当課長","answer":"委員ご指摘の横道の関係ですが、私も実査しまして、抜け道的な要素がありますので、この件につきましても、荏原警察署と相談しながら、取り締まり、交通整理等を含めて、今後とも継続して対応していきたいと考えています。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、２６７ページの都市計画道路に関連しましてお伺いをしたいと思います。市街地整備基本方針にもあるように、都市計画道路の早期着工といいますか、全体が整備されることが品川区全体の都市機能を増し、また、より住みやすいまちに近づくだろうと思っておりまして、それぞれの路線が早期完成をしていただくことを願う次第ですが、そういう立場に立ちながら、幾つかお伺いをしてまいりたいと思います。","respondent":"藤田都市計画課長","answer":"現在、平成１７年度には詳細の設計を行い、外築の築造のほうに入っていくというふうに聞いてあります。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと周辺を見ますと、放射２号線にも、これは具体的には明日のテーマではありましょうが、日野中学校の校庭がかかっていたり、あるいは荏原第一中学校の用地もかかってしまうのかなと思われますが、そういったように都市計画道路そのものの利便性といいますか、必要性は十分分かりますし、一方、それぞれ公園ですとか、学校の用地というものも非常に公共性の高い施設でございまして。","respondent":"藤田都市計画課長","answer":"学校用地等の関係ですけれども、都市計画道路がいつの段階で都市計画が引かれていたかといったようなことにも係わってきますので、一概には言えませんけれども、両者、広い観点の中ですみ分けをしながら、まちづくりを進めていくべきというふうに考えてあります。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"ご答弁いただきたい内容も先に触れていただきましたが、ちょっと前段に戻りまして、公共用地の考え方として、周辺の地区に、これは裁判でもう結果が出たのかどうかあれですが、林試の森公園に抜ける入口を用地取得する際に、小山台二丁目の地区で官舎のある脇に入口をつくる際に、国有地を使う、いわゆる公共のための道路なので、本来ですと、その場所を使うべきなのか、あるいは私有地を買い取って。","respondent":"中谷まちづくり事業部長","answer":"都市計画のときにかける場合については、戦前はともかく、戦後の民主主義社会におきましては、各公共事業者同士で話し合いを行い、都市計画をかけているです。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"当面の間ということでの前提があっての設置だですが、今予算特別委員会においての初日、また２日目も都市計画交付金の件でちょっと触れてまいりましたが、都市計画需要というものをどう見ていくかという考え方の中ですが、都市計画道路の中ではすでに完成しているものと、事業中のものと、未着手のものがあって、地権者、相手のあることなので、なかなか事が進まないという中において、とは言いながらも。","respondent":"中谷まちづくり事業部長","answer":"しかし、公園の少ない地域などについては、今委員がおっしゃいました、戸越のわかば児童遊園の地域のように、公園が少ない地域については、これは補助２８号線の用地にかかるところですが、先行取得をして、児童遊園用地として買収し。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう視点でぜひお願いをしたいと思います。財政的な部分で、いわゆる都市計画需要というものをいかに増やすかという視点の中で、今、認可があってからでないと先行取得はできないというお話でしたが、そういう手続きを経た上で、東京都に対する主張の中の考え方としてそういう手法をとるお考えがあるかどうか、財政的な面からの視点をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"そういう意味では、都市計画交付金の事業を積極的に展開する意味でも、先ほどまちづくり事業部長が申し上げたとおり、積極的な事業意欲と、それを支える財政制度の確立のために引き続き東京都と力強く折衝していきたいというふうに考えてあります。","id":"exchange-122"},{"speaker":"藤田委員","kind":"質問","question":"私からは３点お聞きいたします。第１点は、先ほど来出ております２７９ページのしながわ水族館運営費に関する質問、それから、２番目に２６５ページの道路、さまざま路面改修等もありますが、その辺に関する質問、もう１点が２７５ページの河川維持費について、堤防についてお伺いをしたいと思います。","respondent":"松代道路公園課長","answer":"そういった中で、今ご質問にありました、入館料ですけれども、当面、品川プリンスホテルとか、いろいろと今できておりますし、先般ご答弁したように、私どもの水族館の特性というのは、他館と比べて公共的な水族館でありますし。","id":"exchange-123"},{"speaker":"藤田委員","kind":"質問","question":"一つ一つ質問をしていきたいと思います。旭川の駅から車で約３０分ぐらい行きますと旭山動物園があるんですが、動物といっても、魚ももちろんおります。ですから、水族館をいろいろな形で今つくっていますけれども、そうした具体的な魅力のある園にすべきではないかなと私は思うんですけれども、その辺の職員の皆さんとどういう話し合いがこれから行われようとしているのか、お伺いしたいと思います。","respondent":"松代道路公園課長","answer":"旭山動物園の話が出ました。昨年の暮れ私もじかに行ってまいりました。今委員からのお話のとおり、いい意味で大変ショックを受けました。これまでの動物園、水族館的な部分もそうなんですけれども、単純にその生態を見せるというようなことにとどまっていた。","id":"exchange-124"},{"speaker":"藤田委員","kind":"質問・要望","question":"今しながわ水族館はこういうおもしろいことがありますよという、それをつくって、立派な看板じゃなくて、そういうものを区の施設にちょっと置いておくと、それで水族館と区民の皆さんがつながるのではないかと私は思うので、これは時間の関係で、要望しておきます。現在もあります。こうしたコミュニティ道路というのを今考えていらっしゃるのか、それをお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"旗の台地区で設置しました道路は、コミュニティゾーンという一つの区画をゾーン規制をしまして、そこの中では通常道路管理者の許可にならないようなさまざまな対策を打っております。ですから、他の地区であの道路と同じような構造の道路をつくるというのは現段階では不可能です。","id":"exchange-125"},{"speaker":"藤田委員","kind":"質問・要望","question":"後ほど写真を見ていただきたいと思うんですけれども、これは本当にスピードが出ないで、ガードレールもついていなくて、安全に車も慎重にいく、歩行者も車をそんなに意識しなくてもできるという、こういう方法もあるんですけれども、品川区としてこれからそういう、大阪市の取り組みですけれども、十分参考にして、ぜひともこれは取り組んでもらいたいということですが、お考えがあれば。","respondent":"岩田管理工事課長","answer":"貴重なご提案ですので、さまざまな面で検討の素材にしますけれども、植え込みを道路の部分につくるというのは、旗の台地区でも今後やっていく予定にしている方向です。","id":"exchange-126"},{"speaker":"藤田委員","kind":"質問・要望","question":"今の問題について論じていますと次の問題にいけませんが、これはほとんど反対が出ずに、普通の道路なんですよ。あのような出っこみ、へっこみがあるようなことではなくて、普通の道路にやっているわけなんですね。ぜひ検討をしていただきたい。これを何とかまちの一つの景観上もっとグレードアップしてもいいんじゃないかなと思うんですが、いかがでしょうか。","respondent":"松代道路公園課長","answer":"グレードアップというところでは、現在進めております目黒川でありますと、壁面緑化等をしておりますし、大崎地区では、道路と護岸の間に地域の方と花づくり、花壇等をつくりまして、歩く方、もしくは目黒川沿いに散策される方に潤いを持てるような形で今つくっているところです。","id":"exchange-127"},{"speaker":"藤田委員","kind":"質問・要望","question":"楽しい堤防づくりということで、地域の子どもたちの絵を、例えばずっと、努力している自治体あるんですね。これはなかなかいいなというふうに感じてきましたので、ぜひそういう楽しい堤防づくりに取り組んでいただきたい。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"西本委員","kind":"確認","question":"午前中に藤原委員が質問をしました２６９ページの細街路拡幅整備事業について確認をします。そうすると、約１９％ぐらいの達成率という計算になると思うんですが、これは区としてどのような評価をされているのでしょうか。これが始まって１７年になると思うんですが、それに対しての約１９％達成率をどんなふうに考えているか、まずお聞きしたいと思います。","respondent":"片田建築課長","answer":"そんな中で、私どものほうとして、先ほど申し上げましたように、５１kmということで、実質細街路に面する確認については、確認申請件数のうちの概ね３分の１ぐらいが、そういう狭い道路に面してきている中で、毎年２６０件前後の協議を行っているということではありますが。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"確かに多少でこぼこしてはいたんですけれども、そういうのも今ご高齢の方もいらっしゃって、自分たちも寄附をして、それを資金にして、違うところに移り住んでというようなこともありますので、そういう手法も、これとは限らなくても結構ですけれども、手法的にそういうものが利用できるのかどうか、また、ほかの方法としてとっていくことで、これを拡大、早期に達成することができるのかどうか。","respondent":"片田建築課長","answer":"委員ご視察の中野区の事例等々については、防災生活圏とか、密集関係の中の一つの事業としてそういう整備をしてきているということで認識しています。ただ、先ほどの細街路、４２条２項道路とか、法で指定してきているものといったものとは若干性格が違います。","id":"exchange-130"},{"speaker":"西本委員","kind":"意見","question":"次に２７６ページの都市計画総務費ですが、総務費という形で括られたというのは初めてだと思うんですが、その中にいろいろ項目がありますが、職員の給与費は別にしても、事業がここに幾つか入っておりますが、その経緯、どうして総務費という部分をつくってまとめられているのか、それの根拠、考え方をお知らせ下さい。","respondent":"市岡企画財政課長","answer":"単純に言えば、職員費をなるべくそれぞれの事業のところに位置づけてあげたいために、これをつくらないと款全体の一番冒頭のところに職員費がみんな入ってしまいますので、それぞれ各項の頭のところにこういうものを持ってきて、それにふさわしい、言ってみれば。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問","question":"ここに載っています新しい事業であります都市景観形成事業でありますとか、それから、下のほうにあります、区民の自主的なまちづくりへの支援というのはここに入ってきているんですが、景観のほうは新しい事業として全体に係わるということは理解がある程度できるんですが、自主的なまちづくりへの支援というのがここに入ってきたというのは何か理由があるのでしょうか。","respondent":"市岡企画財政課長","answer":"この自主的なまちづくりへの支援は、従来は都市開発費のところだけにありましたけれども、いろいろなまちづくり、いろいろな形態、いろいろな地区特性の中で、それぞれ区民の方が自主的な意欲で進めていく事業について支援をしていこうということですから。","id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"それとの関連性がどうなっていくのかな。まちづくりというふうに全体を括ったときに、どういう関連があって、どこが主体になって、下手するといろいろな事業がかぶっているような状況に、品川区内にあちこちにできるんじゃないかなというような、そういう雰囲気もあるんですが、考え方はどういうふうに考えていけばいいのでしょうか。","respondent":"市岡企画財政課長","answer":"それで、まちづくりのところですけれども、それぞれの事業、例えば市街地再開発事業のようなところであれば、これは再開発事業の補助金ですから、都市開発費のところへ位置づけるほうが分かりやすいと思うんですが、これはまだ卵の卵で。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"それはどういうふうな絡みになっていくのか。確かに都市景観はこれからどういうふうに動いていくのかというところでの事業ではあると思うんですが、今まで動いている、地域住民の発案とか、地域住民たちの手によってまちづくりをつくっていきましょうというところの絡みがどうなっていくのかなというところはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"現在、都市景観形成の絡みの中では、地区計画等と今の段階ではラップをしていませんけれども、いろいろな目的を持ちながらまちづくりを進めていく中で、一つのエッセンスが景観というような形で。","id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"そうしたときに、景観法のモデル地区になったときに、この地域は商店街があって、こういう特色をつくっていきたいから、建築の高さの制限をしてほしいというのを初めに決める状況ができるのかどうか、それによって８階建てとか建たないように規制がかけられるものとしてできるのかどうかというところはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"地域の中で皆さんで合意をして、こういった形でまちをつくっていこうといった形になることが大前提ですので、言うなれば、地域の方々が低いスカイラインを望むのか、あるいは一定程度の高さのスカイラインを望むのか、その辺のことがありますので。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"今建築基準がかなり緩やかになって、割と低いマンションがいっぱい建っているというところがあった場合に、こういう景観法を使うことによって、ある程度の住民の合意は必要になりますけれども、それを規制することができるという大きなメリットがあるというふうに認識してよろしいということになるんでしょうか。","respondent":"藤田都市計画課長","answer":"そうした中で、何を皆さんがよろしい景観と考えるかといったところが一番ネックになってくるのかなというふうに考えてあります。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に、２６７ページの都市計画道路整備事業ですが、これは今まで何人かの委員のほうからご質問を受けておりますので、私はちょっと確認だけをさせていただきたいんですが、もともと決定されたという道路計画はいつごろのものなのかなというところを、先ほど戦前、戦後という話があったんですが、今動いているものはいつごろで、それをどういうふうに今後変えられるのか、変えられないのか。","respondent":"藤田都市計画課長","answer":"そうした中で、現在大きな観点の道路交通網、ネットワークといった観点から、それぞれの路線が必要であるといったような形で事業を進めているところでございまして、それに基づいた、昨年３月にも優先整備路線をどこにするかといった形の発表をしたところです。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問","question":"今６１％ということは、１００％になるためにはあと５０年、６０年かかるということになるわけですね。これの見直しが５年後、１０年後という形で毎年されていると思うんですが、その見直しの中身というのは、例えば本当にこの道が必要なのかというところの議論はどの辺までいっているのでしょうか。","respondent":"藤田都市計画課長","answer":"今回見直しを行いましたのは、第３回目でございまして、概ね１０年単位で見直しをかけているところです。その中で、今回の見直しの中では、本当に都市計画道路として必要なのかどうかといった観点も含めながら検討をしています。","id":"exchange-138"},{"speaker":"西本委員","kind":"意見","question":"これも私たちは生きていないぐらいのときまでかかってしまうと思うんですが、ただ、地域住民の方たちに非常に影響のあるものですので、ぜひ時代に合わせた見直しをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"石田委員","kind":"質問・要望","question":"私は、２６１ページ、駅周辺等放置自転車対策と、先ほどちょっと話があったので、中高層の建築の開発指導の話の確認をしたいと思います。その後の発言の中で、ある一定程度の要綱の中で、事前の説明会みたいなものをやっていくというような、やっていくのか、やっていかないのかわからないけれども、そんなような発言があったので、もう一回説明をしていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"先ほどもございましたけれども、中高層を建てる際の建築紛争の一つの話題として、解体時の振動、騒音、ほこり、車両の通過、そういったものがございまして、それが年の中に十何件、そういう陳情といいますか、苦情といいますか、そういったことがあったわけですから。","id":"exchange-140"},{"speaker":"石田委員","kind":"意見","question":"それは建物がないわけですよ。ここら辺のものを事前にどうやるというのは非常に難しいところがあるし、行政側がそれをどういうふうに指導していくかというのは、指導することは構わないけれども、それが実効性があるかというと、私はあまりないところにそれを言うのもどうかと思うんだけれども、そこら辺の考えを聞かせて下さい。","respondent":"浜脇住環境整備課長","answer":"ですから駐車場等のものが本当に解体説明が必要かどうかというところは、検討はしていますけれども、一番は、この跡に中高層の建物が建つならば説明をしていただこうと、こういうストーリーでやっていきたいなと考えていますので、ただ単に壊して売るだけだったらば。","id":"exchange-141"},{"speaker":"石田委員","kind":"質問・要望","question":"今の部分も、壊して売るということもあるし、中高層を建てる場合のときという限定をするとなると、本当にその部分の限定だけでいいのかという話にも、逆には、全部やれという話になるかもしれないけれども、私はそういう限定の部分だけで考えていくというのは、あまりいいことではないなと考えていますので、これは答弁はいいです。そういう要望だけをしておきます。","respondent":"山口交通安全担当課長","answer":"ここで実務面をちょっと考えて、可能になったと想定した場合、現場で氏名、住所等に、いわゆる取り調べに応じれば、それは何の問題はないんですけれども、「いいですよ」と立ち去った場合、その自転車が防犯登録等があれば結構ですけれども、何もない場合、その自転車を特定。","id":"exchange-142"},{"speaker":"石田委員","kind":"確認","question":"これでいいのかどうかという確認と、今私が思っているのは、その際の負担金ということは、これは返還する人ですね。携帯電話もかけちゃだめだよ。意図的に剥がしているわけですから。これはやっぱりそこの部分で何らかの方策を打つことによって、抑止力が発生するならば、若干そういうふうに減っていくということもあるかもしれませんので、そこら辺の、登録証の部分と、その部分をお伺いをします。","respondent":"山口交通安全担当課長、中谷まちづくり事業部長","answer":"返還率が今のところ５４.１％ぐらいです。防犯登録を剥がした場合の特定の関係ですが、防犯登録をする場合は車体番号も一対になっておりますので、その特定をする場合は車体番号を追及すれば出てくるという形になっております。流通経路の問題などを全部やらないと、車と違って、高額のものではないので、なかなかそこらまで全部把握するのは難しいというようなこともあって、これは義務になり、区でも条例の中でこれは義務として定めているんですが。","id":"exchange-143"},{"speaker":"石田委員","kind":"質問・要望","question":"それを持っていくと、１年以内だったら半額で自転車が買えるわけです。それは盗んで剥がしたのかどうかわかりませんけれども、そういうところには、今言ったように、負担金の部分は道路交通法上無理だというなら、今度は違う部分の、犯罪の部分にもう一回手を入れるとか、そういう部分の検討というのはぜひしていただきたいと思うので、もう一回考えがあればお聞きしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"この中で取り上げて、そして大きなうねりとして法改正まで自転車法を持っていく。鉄道事業者の付置義務のほうがもっと自治体としては重要な問題ですから、そういう問題も含めまして、今後とも検討をしてまいります。","id":"exchange-144"},{"speaker":"沢田委員","kind":"意見","question":"２７６ページの都市計画費に関連しまして、中央環状品川線の現状についてお尋ねしたいと思います。着工の時期はいつごろを目指しているのか、それから事業費と、その負担割合はどうなっているのか、連絡会ができておりますけれども、住民合意はどこまで進んでいるのか、その３点についてまずお尋ねします。","respondent":"藤田都市計画課長","answer":"そのときにも意見交換をしておりますけれども、今後も私どものほうとしては引き続き行われるのかなというような認識です。事業費ですけれども、事業費のほうは、４,０００億円ということで、事業者のほうが負担する。","id":"exchange-145"},{"speaker":"沢田委員","kind":"意見","question":"最初に、今度いきなり２,０００億円東京都が負担するという案が出てきたんですね。今までは１２.５％ずつ国と東京都が折半にしていたのに、なぜ都民の税金２,０００億円も投入することになったのか、これは区に言ってもしようがないことなんですけれども、財政的にこのような高速道路に、本来公団がつくるべきなのに、東京都がその半分を出すというやり方にそもそも大きな問題がある。","respondent":"藤田都市計画課長","answer":"環境アセスメントの関係ですけれども、アセスメントは、まず法がありまして、条例があります。条例の中で環境影響評価をするための技術的な指針が定められてあります。そうした中でそれらの基準に基づいて評価をしているというふうに聞いてあります。","id":"exchange-146"},{"speaker":"沢田委員","kind":"質問","question":"毎回これだというわけではないですよ。今でも罹患率が高いのに、こんなのができたら住めなくなってしまうという、アセスメントの不十分さを追及しているのに対して、区のほうは正当に行っているというのでは、やっぱりこの問題の支援にならないんじゃないかというふうに思うんですが、区はアセスメントの問題についてどう思っていらっしゃるのでしょうか。","respondent":"藤田都市計画課長","answer":"大気汚染等に関しては、東京都のほうでは一応十分だというような説明はされてありますけれども、区のほうといたしましては、最新技術の換気設備を換気塔に設けてほしいといったようなことを併せて要望する中で、これまで進めてきているところです。","id":"exchange-147"},{"speaker":"沢田委員","kind":"質問","question":"私は訂正してほしいと思うんです。これは高等裁判所で覆って、今は最高裁判所にいっていますけれども、そういう問題があちこちに、交通量の予測など実態と違っているという問題がありますので、改めてアセスメントには問題がある、そこを突き詰めたいという立場をとってほしいと思うんですが、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"そうした形で適正な評価を受けて行われているものですけれども、私どものほうとしては、さらにもう一歩進めた環境対策をぜひとも東京都のほうに行ってほしいといった要望をしているものです。","id":"exchange-148"},{"speaker":"沢田委員","kind":"質問・要望","question":"こういう立派なありがたい意見を出しているならば、ぜひもう一歩踏み込んで、本当に科学的、疫学的にも、どんな影響が出るのか、はっきり説得力のある資料を出してほしいと、そういう立場を改めて東京都に働きかけてほしいと思いますし、さっき言ったように、公団が民営化して、いつになったらできるかわからないから、とりあえず２,０００億円都税を入れて進めちゃおうなんていう。","respondent":"金井環境課長","answer":"この手続きが終わらないと計画に入れないですので、最終的には都知事、あるいは環境大臣の意見等も踏まえて実施をするということになっておりますので、その手続きが今終了をしているわけですけれども、いずれにいたしましても、地域住民の声というものは。","id":"exchange-149"},{"speaker":"沢田委員","kind":"質問","question":"区長にお答え願えなかったんですが、署名に参加したのが３０町会です。３万２,０００名を超える署名というのは、品川区の人口の１割強です。それほどの人たちが不安を持っているんですから、先ほどまちづくり事業部長が、地域に出かけ、地域の声を生かす行政をすると、答弁をしましたけれども、それを生かしてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"三村委員","kind":"確認","question":"先ほど東京都のほうで行われた環境局での会議の話が出ておりましたけれども、そちらの議事録等はとられているのか、お聞きをしたいんです。品川区長が意見を上げて、ほかの区と、都民の意見を聞く会やなにかのすべての意見を総合して、東京都のほうで会議を開いて、その対応というか、意見を評価をする場があったかと思うんですけれども、そちらの会議の内容等を確認しているでしょうか。","respondent":"金井環境課長","answer":"環境影響評価の手続きの中で、地域住民の声、あるいは意見書の声というのは、環境影響評価書の中にきちんと示されてあります。それは私どもも把握しております。そのほか東京都では環境審議会といった中でも審議をされております。","id":"exchange-151"},{"speaker":"三村委員","kind":"質問・要望","question":"その審議会のほうを傍聴に行ったんですけれども、その中で、品川区長の意見は、ほかの区に比べて、地域住民の声を反映したすばらしいものだったと思うんですけれども、その委員会の中で再三指摘をされていたのが、今回のアセスメントというのはあまりにもひどい、ずさんなものだということが再三再四指摘されていたんですね。ちょっと確認をとって、その辺のところを把握していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"高星委員","kind":"質問・要望","question":"質問に入らせていただきます。先達ってうちの近所に放置自転車がありまして、それを警察にお伺いした。こういうことを聞いたので、その辺のところがどうなっているのかお聞かせいただきたいと思います。それから、３点目の五反田駅のまちづくりですけれども、２７６ページになるんでしょうか、都市計画の関係になるんでしょうか、区民の自主的なまちづくりの関係だというふうに思います。","respondent":"山口交通安全担当課長、上野都市開発課長","answer":"というのは、１０年間も保存すれば自転車も大分くたびれてくるだろうという感じで、１０年間という、警察のほうも物持ちがいいですから、そんなに早く片づけないで、若干の余裕をもって１０年以上１１年とか。特にＪＲと東急電鉄との取り合いにつきましては、構造上の取り合いもかなり古い構造体ですので、その辺の詳細もかなり時間がかかるというふうに聞いてありますので、その辺の調整を今じっくりやっているです。","id":"exchange-153"},{"speaker":"高星委員","kind":"質問・要望","question":"いろいろ理由もあるんだろうというふうに思いますけれども、そういうことがありますものですから、しかるべきところで、しかるべき区政協力委員会も含めて、お願いもするところがあるんだったら、きちんとお願いをしてやったほうが、品川区はこの期間は区を挙げて子どもたちだけでなく、高齢者のためにも一生懸命やっているんだという姿勢を見せていく必要があるんだろうというふうに思いますので。","respondent":"山口交通安全担当課長、上野都市開発課長","answer":"テントの関係、町会の交通整理の関係ですが、警察署のほうと協力して呼びかけて、できる限り交通配置等にご協力をいただけるように、可能かどうか警察署と相談しながら実施していきたいと思いますので、よろしくお願いいたします。バリアフリー化につきまして、五反田駅周辺の全体のまちづくりを考えて、バリアフリーを取り込んでもらいたい、そういう要望が出てあります。","id":"exchange-154"},{"speaker":"高星委員","kind":"質問","question":"自転車の関係ですけれども、先ほど私はちょっと先入観を持って３年間なんだというふうに思ったものだから、３年間過ぎたものについては、もう持ち主がわからないので、葉書も出していないんじゃないかなというふうに思っちゃったものですから、申し訳ないなというふうに思います。だから、程度のいい自転車も余るから売却するんだと。目黒川を環境資源として活用する協議会とか、こういったものができている。","respondent":"浜脇住環境整備課長、岩野まちづくり事業部次長","answer":"一部の方が相談には来ましたけれども、まちづくりの派遣はまだ行ってございません。五反田まちづくり協議会ということで、地元の町会長をはじめとして、今回のバリアフリーを契機として、五反田の将来のまちづくりを考えたいといったような形でもって、そのようなまちづくり協議会を形成したというようなことですので。","id":"exchange-155"},{"speaker":"高星委員","kind":"質問・要望","question":"いずれにしても、地元住民の要望の強いエレベーターですので、できるだけ親切丁寧にクリアしていっていただきたい。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目が、本来は２４３ページの４款の衛生費でお尋ねすべきかと思いますが、お許しいただきまして、２６７ページの道路新設改良費に関連をしてということで、環境にやさしい路面づくりについて、それから３点目が２６７ページの補助１６３号線の未整備区間と、大崎短絡線との関連についてお尋ねをしたいと思います。","respondent":"岩田管理工事課長","answer":"区からＪＲのほうに改善方要請をしてまいりましたところ、今般３月２９日と３１日の深夜にすりつけ工事を行うということになりました。","id":"exchange-157"},{"speaker":"堺委員","kind":"質問","question":"ようやく我々の願いが聞き届けられて改善されると、このように理解をしてよろしいんでしょうか。あそこもご存じのとおり、何回となく申し上げてきた中で、一遍に工事をやっていただければよかったのにもかかわらず、あそこの舗装材の木の踏切ですか、そこはやったけれども、その前後の道路の段差の部分は未改修でそのままになっていた。もう一回お願いいたします。","respondent":"岩田管理工事課長","answer":"そのとおりです。","id":"exchange-158"},{"speaker":"堺委員","kind":"質問・要望","question":"安心しました。２点目に移ります。先ほど申し上げました、環境にやさしい路面づくり、これは今回６００万円計上させれておりますけれども、この事業の目的、事業の内容についてお聞かせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"これはヒートアイランド現象ということで騒がれておりまして、こういう問題についても道路側から何らかの一助ができないかということで、特にアスファルトは夏場の一番暑いときには４０度を超えるような暑さになりますので。","id":"exchange-159"},{"speaker":"堺委員","kind":"質問","question":"今お答えがなかったんですが、調査検討をする場所が明示されておりますね、案として出ておりますが、どこですか。","respondent":"岩田管理工事課長","answer":"１日中朝から晩まで日があたるところで、障害物がないところで、一番実験に適当なところということで、今変更場所を検討しています。","id":"exchange-160"},{"speaker":"堺委員","kind":"質問・要望","question":"正門のところと、裏側、ちょうどいい場所ですから、それならば大原小学校の児童・生徒の環境教育の一環としても有効に活用していただきたい、このことを申し上げようと思ったんですが、場所が変わっちゃったので、このことは引っ込めますけれども、ぜひひとつ新しい場所を選定するにあたっても、ただ道路上につくるのではなくて、そのように関連して、連鎖的に環境教育としても使える、そういう視点も含めて。","respondent":"岩田管理工事課長","answer":"この成果をもちまして、できるだけ今後の路面改修のときにはこういった工法を取り入れながらやっていきたいと考えておりますので、その折には近隣の学校や、そういった教育活動にも使えるような形でやってまいりたいと思います。","id":"exchange-161"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひそういう視点でお取り組みをいただければと考えています。次に、補助１６３号線の未整備区間の件です。いずれも、今申し上げたところについては歩道が大変狭くなっておりますから、ぜひこの未整備区間の拡幅のときには、そういうところも十分考慮していただきたいということを申し上げて、いつごろこの未整備区間については着手するんですか、このことを前回お尋ねをさせていただきました。","respondent":"藤田都市計画課長","answer":"延長１km強ありますけれども、同じ補助１６３号線の中で今事業を行っている区間がありますので、その辺の進捗を見ないと事業認可も取得できないといったような形になりますので、委員お話のとおり。","id":"exchange-162"},{"speaker":"堺委員","kind":"質問・要望","question":"前後だけされているから、未整備区間についてはいつごろどう始まるか全く今はわからないんですよというふうに理解しなさいということですか。したがって、前後が終わった段階で直ちにスタートできるんですよというふうに、私は理解をしたいと思うんですが、その辺のところをもう一回教えていただきたいと思います。","respondent":"藤田都市計画課長","answer":"現在、事業認可を取得して事業を進めてありますので、同じ路線の中で２カ所の事業の進捗が終わりが見える段階でないと事業認可の取得ができませんので、そういった中でその辺の進捗を見る形での事業の進め方をしていきたいというふうに考えてあります。","id":"exchange-163"},{"speaker":"堺委員","kind":"意見","question":"特に今未整備区間は区役所の真ん前のところです。したがって、いつとは言いません、どうか適切な時期に予算計上をしていただいて、一本橋通り側のほうが完成した暁には未整備区間を直ちに工事を始めますよ、安心して下さい、こういうふうにおっしゃっていただければ、近隣住民の人は大変安心をするんですが、その辺はいかがでございましょうか。","respondent":"中谷まちづくり事業部長","answer":"補助１６３号線の未着手区間につきましての考え方ですが、先ほど都市計画課長も申しましたとおり、補助１６３号線の一本橋区間の整備がある程度目途が立ったのが見えた段階で次の着手を検討するですが、この考え方には二つあると思います。","id":"exchange-164"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひそういう方向で合意形成が図れる方向で、この未整備区間についても早期に着工して、完成するように、重ねて要望しておきたいと思います。そこで、やはり近隣住民の不安、心配な点を最新の技術を駆使して環境対策も含めてしっかりやっていきますと、そのように十分住民に説明するように、行政のほうからも強くＪＲ側に要請をしていただきたいと思うんですが、この点についてはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"その中では計画の見直し等について検討をしてほしいというような話がございました。区のほうでは、地域の皆さんに、ＪＲと十分な話し合いを行ってほしいと言ってあります。環境面でも最新の技術を駆使してほしいというお願いをしています。","id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"今申し上げましたように、その辺ぜひひとつお願いします。もう１点、さっき申し上げた補助１６３号線と短絡線との絡みで、補助１６３号線に支障は出ないのかどうか、その辺いかがでしょうか。","respondent":"藤田都市計画課長","answer":"現在高さの関係で若干影響があるかもしれないという話は聞いてあります。ただ、具体的な提示がないので、その辺については今後も協議をしていきたいというふうに考えてあります。","id":"exchange-166"},{"speaker":"原委員","kind":"質問・要望","question":"３点私のほうからお伺いをします。二つ目は、２６７ページの都市計画道路整備の補助１６３号線と補助２０５号線、補助１６３号線は一本橋のところで、昨日ちょっとお話を伺いましたら、店舗総数が７４件、事業を事業地外に移転した店舗は２３件、廃業した店舗が２１件、事業地内で移転をした店舗が１８件ということで、未契約が１２件残っているですので、今後の見通しについてはどうなっているのか。","respondent":"山口交通安全担当課長、藤田都市計画課長、岩田管理工事課長","answer":"もしくはシールで、安全講習をした場合、終了者等に対して免許証を、免許証はほかの区でもやっているんですが。その見通しですけれども、現在交渉を鋭意続けているところで、一つの目処として平成１７年度ということで考えてあります。ただ、地元は当時は商店街として地中化を行いたいというご要望がおありになったわけですけれども。先ほどご質問の取り締まりの関係ですが、各署等に確認をしましたところ、昨年１年間で警告書だけですが。","id":"exchange-167"},{"speaker":"原委員","kind":"質問・要望","question":"都市計画道路のほうですが、一本橋６０件、補助２０５号線１０件ということで、かなりハッパをかけてやっていらっしゃるようですけれども、地元の要望等々もいろいろあるようですので、その辺も勘案しながらやっていただきたいんですが、ちょっとここでは款が違うんですが、実はここは森下町会なんですね。そうすると、この辺の工事の度合いなんですが、どういう形を描いていらっしゃるのか。","respondent":"山口交通安全担当課長、藤田都市計画課長、矢部下水道河川課長","answer":"委員のご質問の内容ですが、幼児の自転車関係の同乗中の事故と思われますが、昨年品川区内で幼児、いわゆる６歳未満の事故の総件数が３５件でございました。事業が進んでいき、きれいなまちができ上がって、道路ができた段階では、大変な効果が期待されると考えていますので。平成１９年度末までには原っぱ公園まで到着しますので、あの地下が大体２０ｍぐらい深いところを入りますので。","id":"exchange-168"},{"speaker":"原委員","kind":"質問・要望","question":"１件や２件でないわけですから、片側が全部削られて、それも件数で言うと相当な件数で、多分調べていらっしゃらないと思うので、今度調べていただきたいなと思うんですが、何か対策を考えていただけないかなと思いますので、要望だけしておきます。それから、滝王子通りです。時期がずれるということもあるようです。安全対策のところだけひとつお願いいたします。","respondent":"山口交通安全担当課長","answer":"５０名中３５名の回答がございまして、ヘルメットをすでに使用している方は５名、今すぐにでもヘルメットを使用したいという人が５名、今すぐにも使用したいんですが、本音で、ちょっとお金がかかるということで、１４名ですが、この中でちょっと気になる回答で、買い物に行くが。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270732?Template=document&Id=848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":124266,"voices":394}},{"id":"h17-20050316-3","meetingId":"h17-c-budget","date":"2005年3月16日","dateIso":"2005-03-16","committee":"予算特別委員会","time":"午前１０時０５分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","topics":[{"id":"topic-01","title":"平成１７年度品川区一般会計予算","agenda":"平成１７年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は２９７ページ、小中一貫校、時間があれば３１１ページの学校改築推進経費の２点、お伺いをします。いよいよ１８年度より、小中一貫校が開校の運びになりました。皆さんのご苦労、まことに感謝申し上げますけれども、市民科が今度導入されるということで、まず市民科の導入に至った背景といいますか、教育的な背景、世の中の背景、ご説明をお願いします。","respondent":"中島指導課長","answer":"市民科は、これらの内容をより目的を達することができるようにするために、統合、発展させた教科として位置づけたものという形です。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問・要望","question":"私たちが小学校、中学校にさかのぼりまして受けた道徳の教育というのは、学科の中では倫理社会であり、また公民的分野であるという、学科という範囲の中で学んだわけですけれども、ここで言う市民科と、今私がお話しをいたしました公民的分野の公民、または倫理社会と違いがあろうかと思いますので、違いを教えていただきたいと思います。","respondent":"中島指導課長","answer":"道徳は一人ひとりの子どもたちの心の教育とも言われておりますけれども、その教科のねらいとはまた違った形で子どもたちに倫理観ですとか、正義感、また公平公正、こういったようなさまざまな価値を学ばせる内容になっておりますし、特別活動におきましては、子どもたちが自主的。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、子どもたちが学ぶ意欲をなくしてしまったのは、自分たちの学んだことが実学的に言えば生活に役に立たない、自分たちの身にとって何でなるかという位置関係が非常にあいまいなところなんですが、子どもたちに市民科という学問を、子どもたちの勉強という範囲に占める位置を教える方策をお持ちであれば教えていただきたいと思います。","respondent":"中島指導課長","answer":"こういった理念に基づきまして市民科の中では、子どもたちがさまざまな課題に気づく、そして教師は教えるべきところをきちんと教える。その中で、さまざまな資質を身につけていって、実践を日常的に行っていくと、こういったような体験的なプログラムを考えているところです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"今、課長は市民性とおっしゃいましたが、市民という言葉は市民権とか市民性とか市民意識、また共同の社会性、そういう意味合いで市民というものをとらえてよろしいでしょうか。","respondent":"中島指導課長","answer":"私ども市民性とは、今、委員のご指摘にもございましたけれども、社会集団の一員としての義務と責任を重んじて、主体的に社会に係わることができるような力をもって、自らも社会的に有為な存在として意識しながら生きていこうとする。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"地域の連帯意識が非常に薄れているということは、論じられて久しくなりますけれども、ぜひとも地域の連帯感の希薄さを補完すべく、この市民科が担えることを望みますと同時に、先生方のご苦労に関して感謝を申し上げます。次に、３１１ページの学校改築推進経費について、簡単にお尋ねをいたします。本年、小山小学校の改築計画があります。これに関して、現在までの進捗状況をお伺いいたします。","respondent":"市川庶務課長","answer":"小山小学校の改築に関しましては、今年度基本設計を策定するということで、昨年の７月から学校関係者、それから町会など地元関係者と検討会を組織いたしまして、これまで都合７回にわたって検討会を開催してまいりました。ただいま基本設計の最終調整をしている状況です。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"まとめの作業にあたりまして、意見を集約するわけですけれども、そこの点で特に留意して作業をされることがありましたら、１点お伺いします。","respondent":"市川庶務課長","answer":"何と言いましても、できるだけ短い工期で新しい校舎を完成させる。このことに、最大限配慮を払ってまいりたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひ、いい改築ができますように、よろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林委員","kind":"提案","question":"第一回定例会の冒頭でも、確か提案があったと思いますけれども、品川区の子どもたちの安心、安全のためにということで、８時から８時半、外に出て掃除をする。そういう意味で、これからの子どもたちが教育という部分で、これからの品川の教育がどういう方向に向かっていくのかなという、日頃の素朴な思いを言葉にして質問に入りたいというふうに思います。","respondent":"中島指導課長","answer":"委員ご指摘のように、今、さまざまな形で学力低下というキーワードが私どものほうにも入ってまいります。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"同じく学力低下につきまして、保護者、また地域の方々の学力低下に対する思い、感想というのは、教育委員会としてはどのように把握されていますでしょうか。","respondent":"中島指導課長","answer":"保護者の方々から私どもが直接意見をお伺いする場というのはなかなかないわけですけれども、例えば小中一貫教育の説明会をしていく中では、保護者の方のご意見をいただくような場面などがあります。教育委員会に直接お電話をいただくというようなケースもあります。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"もう１点、学力低下について、これは大人の側から見た言葉だと思うんですが、子どもの側から見れば、学ぶ力とか学ぼうとする力という置き替えができるかと思いますけれども、学力低下という言葉は大人の言葉かもしれませんけれども、教えられる側の子どもたちはこういうことをどのように子どもたちは感じているのか、あったら教えていただきたいと思います。","respondent":"中島指導課長","answer":"そういった状況の中で、話しを聞く機会があります。例えば、保護者の方からは、「この学校は子どもの学力を伸ばしてくれていると思うか」というようなアンケートの結果として、８０％を超える方々に「そう思う」「強くそう思う」というような答えをいただいております。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"２００２年から現在の学習指導要領になりまして、そのときも随分マスコミも含めて親御さんたちも学校も、当然いろんな大合唱というんでしょうかありました。こういう急激な転換に対して、先生たちの教育への情熱とか子どもたちの学ぶ意欲を阻害するというような見方があると思うんですけれども、品川区としては方向転換をしようという動きに対してどのような理解をされているんでしょうか。","respondent":"中島指導課長","answer":"これは今、ゆとり教育から学力重視への転換と言われておりますけれども、基礎学力を定着させるために私どもが取り組んできた方向と決して異なるものではないと、このように考えております。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"一つ、安心の言葉があったと思います。「私はちっぽけな人間です。そこで、子どもの生きる力の低下がすなわち学力低下につながっているんだという、広島県の一校長のお話ですけれども、私はなるほどなと思ったんですが、今、子どもたちも当然抱いているかもしれない無力感、それから生きる力の低下、それが学力低下につながっているんだというような分析に対して、どのようなご感想をお持ちでしょうか。","respondent":"中島指導課長","answer":"子どもたちがより積極的に主体的に物事に係われるようにするというのは、もちろんすべての教科でもそういうような指導はしていくわけですけれども、やはりもっとトータル的に、１年生から中学３年生まで、私どもで設けた９年生までが一連の流れの中で。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"最終的にいつも私たちの会派の主張として、学ぶ環境、学びの環境、最高の環境というのは先生、教師であるという、これは一般世間でも普通に言われることですけれども、先生たちが１対３０とか１対４０という少人数学級という部分もいろいろ言い方があるかもしれませんけれども、それは何人になるか現実問題あると思いますけれども、１対３０、１対４０の中で先生のお気持ちとしてぜひ１対１なんだと。","respondent":"中島指導課長","answer":"そういった中で、どのように一人ひとりを見ていけるかというあたり、これがもう何といっても教師の一番ベースにあたる部分ではないかなと思いますので、さまざまな指導形態を取り組む中で、一人ひとりを大切にした授業を目指してまいりたいと考えております。","id":"exchange-013"},{"speaker":"木下委員","kind":"質問","question":"２９４ページの教育指導費の部分と２９７ページの教育指導費の中の小中一貫教育、３００ページの学校管理費、この３点について質問をさせていただければと考えています。学習意欲の低さを改善するという意味合いで、今まで努力されてきた経緯ですとか、これからどういう形でやりたいのか、展望ですとかいろいろお聞かせ願えればと思います。","respondent":"中島指導課長","answer":"子どもたちの意欲の低下、またモチベーションがなかなか高まらない、こういったような状況をどのように解決していくかというのは、実は今回ゆとり教育云々というさまざまな発言を聞くまでもなく、既に学校におきましては。","id":"exchange-014"},{"speaker":"木下委員","kind":"質問","question":"２９７ページの小中一貫教育。これも報道で、２３区初で江東区が幼稚園、小中学校を一貫校ということで、構想づくりというのが載っていたんですけれども、小中学校だけではなくて幼稚園までということです。幼稚園、小中学校だけではなくて高校もあるわけですから、将来的に幼稚園ですとか高校を含めた形での一貫した成長過程に合わせて教育のお考えはあるのかどうなのか、お聞かせ願えますでしょうか。","respondent":"中島指導課長","answer":"今、本区では、小中一貫教育のカリキュラムを平成１８年４月から全校で移行に入っていきたいと、このように考えている状況です。は義務教育の小中一貫教育の実施、充実を図っていきたいと考えております。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"私のほうから２９３ページの安全管理に関することかと思いますが、議会の中でもいろいろ出されておりますけれども、寝屋川での事件との関係でお聞きしていきたいなと思います。私はこの問題というのは、二つの問題を提起したんだと思います。一つには、もちろん子どもの安全をどういうふうに守っていくのかという問題と、教職員の安全をどう守るのかという問題もあると思います。","respondent":"中島指導課長","answer":"また校内に外部の人が入ってきたときは、当然不審者というような言い方がありますけれども、来校者に対して基本的な態勢をつくっていく必要があるだろうと。その中では、例えばまず教員が対応するにしましても、主事が対応するにしましても、単独での対応はしない。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"地域に開かれた学校という中で、どうやって児童と教職員を守るのかというのは、大変難しい課題なんだと思います。先の事件で重傷を負った先生ですけれども、事件の前に職員会議でいろいろ危機管理の問題について、「犠牲者が出るまで警備員を置かないんですか」という発言をしていたというのが新聞に載っておりましたけれども、この直後の事件だそうです。","respondent":"市川庶務課長","answer":"防犯態勢のハード的なお尋ねですけれども、１６年度ですけれども、モニターカメラ付の電気錠、通用門への電気錠の設置を試験導入をして、既に数校で導入しています。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"通学路で子どもを見守っていた緑のおばさんもいなくなって、子どもを守る目が少なくなった」と、こういうような指摘がされているのと、同じように女性の教員が「職員室に５分といられない。玄関の受付の教師が立つように言われていても、とても無理です。防犯カメラをつけても見る人がいません」と、こういうコメントがあるんですが、こういう状況下にあるということでしょうか。","respondent":"市川庶務課長、中島指導課長","answer":"私ども今年度試験導入をしたと、先ほど申し上げましたけれども、当然何を試験したかというのは、運用実態を見たいがために試験導入したわけでございまして、その経過の中で、先ほど指導課長が申し上げましたが。それに係わって、ソフト面という形になっていきますけれども、教員そして学校自体が外部の緊急な対応に向けてどのようにあるべきかということで、すべての学校において。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"公式の調査を見ますと、文部科学省と国立教育政策研究所が中心になった調査だそうでありますけれども、教員の方は１日平均１１時間働いている。先ほど話が出ておりませんでしたけれども、警備員の配置というのは最大限進めるべき内容ではないかというふうに思いますけれども、この点でもう一度お願いいたします。","respondent":"中島指導課長、市川庶務課長","answer":"ただ、何もしないで、そこで見ているわけにはまいりません。こういった教員のその場の対応もそうですけれども、先ほどお話しいただいた１日の中で５時までトイレへ行かない。決して警備員の有効性を否定するものではございませんけれども、その前にまず学校が何をすべきなのか、何ができるのか、ここのところから始めさせていただきたいというふうに考えてあります。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"先ほど文部科学省と品川区の教員の声を紹介したわけですけれども、現場では圧倒的に人の面も足りないということが言われているわけです。この辺は、もう一度考えるべきではないかというふうに思います。これに沿って、やっぱり子どもたちの安全管理を含めて、もう一度この点からも考えていくべきではないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは教育総務費と学校教育費の中から質問をさせていただきたいと思います。一つずつ聞かせていただきたいと思います。ある学校で、明後日の卒業式で３クラス卒業して、今の状況だと５クラスの１年生が入ってくるような状況の学校が出てきたと思います。こういうときの改修というのは、例えば当年度でやるとすると、学校改修費の中で十分対応できるのかという点を、まず１点お聞きしたいと思います。","respondent":"谷田部学務課長","answer":"今、具体的な学校のお話が出ましたけれども、学校選択制を取っている以上、希望する子どもについては極力受け入れていこうということで、小学校について、中学校についてもやっているわけですけれども、学級数が増える見込みが立った段階で、新年度の４月にあわせて改修をし。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校の中で設備を整えてもらいたいという思いと、それからまた特別教室を変えたことによって教室がまたさらに不足していくような場合、例えば給食室の上に追加すれば教室がつくれるのではないかという雰囲気のところも聞いています。今後、増えてくることによって、そういう対応は考えられるのかどうか、その辺もお答えをいただきたいと思います。","respondent":"谷田部学務課長","answer":"私どもが今転用しているのは、かつて教室だったところを多目的に使っている部屋が普通教室に転用可能だという判断と、それから希望する子どもの数との関係の中で、さまざまに検討させていただいて、何学級まで受け入れ可能だということを推計して出しています。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺で、できる限り要望にうまくこたえていただきたいなという思いで、この部分は終わります。確かに、幼稚園、保育園から小学校に入ると、かなり急激な違いがあると思うんです。品川区として、既に検討はなさっているということは今までも出ておりますが、その中には区立保育園・幼稚園、小学校という考え方なのか、そこに私立幼稚園も入っているのかどうか、その辺をまずお聞きしたいと思います。","respondent":"中島指導課長","answer":"現在、検討会を進めてきているところですけれども、特に幼稚園・保育園のそれぞれの保育内容、そして小学校に入るまでをゴールといたしまして、極力そろえることができるようにしたいというような強い願いを持っております。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、そういう形を進めていっていただきたい。もちろん、当然やっていることは承知しています。この子どもが小学校に入ったら大変そうだなと思ったら、やっぱりそれは区立幼稚園と小学校だったので、既に連絡が取られていたというお話を伺いました。現状のお話しを伺いましたけれども、これから課題としてどういうふうに考えていくのか、その辺がございましたら教えていただきたいと思います。","respondent":"中島指導課長","answer":"幼稚園の場合には、教育要領に基づいて保育の内容等を実施しているわけですけれども、それと保育園等、また私学等で実施しております就学前の教育の内容、ここのところをどういう形で情報を共有し、また１年生に向けて共通の理念をとらえていくか。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、中高連携といっても、高校ですと品川区内だけではないから、その辺は難しいところがあると思うんですが、現在どのような連携を取っているのか、それから今後どのような考え方を持って、先ほど市民科の中に入れていくという部分、どのような考えか、もうちょっと細かく教えていただければと思います。","respondent":"中島指導課長","answer":"市民科におきましても、先ほど申し上げましたが将来志向の部分の中で、自分たちの将来をどのように考えるかという部分と、従来あった進路指導を合わせる形で、子どもたちの資質の育成に取り組んでいきたいなと考えているところです。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ぜひ、中学校から高校というのは、大変に大きな段がある部分だと思いますので、ことに義務教育から義務教育でなくなってしまう部分ですので、中学生にとっていい形で進めていただけるように、ぜひお願いしたいと思います。職員だと６５歳まで再任用という制度がある中で、先生方はどのように対応なさっている方が多いのか、その辺を教えてください。","respondent":"中島指導課長","answer":"学校の教員の退職後、６０歳で一応定年退職ですが、それ以前の退職も含めまして、その後再任用、再雇用の制度があります。ただ、再任用というのは、基本的に東京都の職員ですので、都立高校ですとか盲聾養護学校の教員を対象にしている状況があります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その方の個人的な話もあると思います。例えば、我々の中で話が出ていたんですけれども、学校の先生ではなくて塾へ行ってしまったほうが、東京都の職員から外れても、そういう方もいるという話を伺っております。何となく子どもに何かあるんじゃないかなということを、学校の先生はすぐに見つけられているのかどうか、そういう指導をしていらっしゃるのかということをお聞きしたいと思います。","respondent":"中島指導課長","answer":"体育ですとか、夏のプールですとか、そういったところでわかる場合もありますし、健診といった場面もあります。不登校の子どもたちにつきましては必ず家庭訪問をして、そこでの連絡を取って、そういった状況を教師が直接確認できるような体制を取るよう指導しています。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"万が一のようなことがないように、ぜひその辺のチェック体制をこれからも強めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"給食調理代行についてお伺いしますが、調理代行は平成１２年に保育園で始まって、１６年度には全園で調理代行になりましたが、その結果を得て、今度戸越台中学校、荏原第五中学校、台場小学校で始める予定ですが、保育園でやったことから、まず何を得たのか、どういう評価をしたのか、それとこの３校を新たに始める目的を教えてください。","respondent":"谷田部学務課長","answer":"１２年度から区立保育園での給食調理業務代行が導入され、全園で現在されてあります。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"課長のご答弁を伺っていますと、財政的にもよくて、質の向上にもなる、いいところばかりだと思うんですが、実はそう答弁されていても、怖い食材の大量購入、献立の簡素化になって、給食内容の低下が実は心配されるのではないでしょうか。","respondent":"谷田部学務課長","answer":"私ども調理代行につきましては、調理作業を行う区の職員から民間の調理代行会社にかわるだけと、いわゆるつくり手がかわるだけというようなご説明をこの間しています。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"法的に区の栄養職員が一般社員に指導はできないというふうに、私はある新聞に入っていたチラシを見て今質問をしているんですが、できないんでしょうか。","respondent":"谷田部学務課長","answer":"そのチラシの内容といいますか、法律の話になりますけれども、いわゆる調理業務代行というのは請負契約の一種でございまして、請負契約であるならば、学校と調理代行の職員との間に雇用関係はありませんので。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"答弁を伺いまして、逆にこのチラシ自体が法的に問題がありますよね。１人でも給食に怖い食材が入っていると思ったら、これはどうするんだろうなと思います。行政として、このチラシに対してどのような措置を取っていくのでしょうか。説明会を開くとか、そういうことではなくて法的といいますか、こんなものは放っておけばいいというのではなくて、ちゃんとやるべきことはやる。","respondent":"谷田部学務課長","answer":"始まった後、実際に児童・生徒が食べたり、また各学校では試食会を考えているですので、実際に食べていただいた結果、それがおいしかったという評価をいただければ、それはそれで調理代行を導入する目的は達せられたというふうに思ってあります。","id":"exchange-032"},{"speaker":"築舘委員","kind":"質問","question":"２９７ページの小学校における英語学習と、３０１ページのインターネット活用教育推進事業、それから３２３ページの図書館経費ということで質問をします。","respondent":"中島指導課長","answer":"委員のご指摘のように、これからの国際化の進展に伴って、国際社会で日本人としての自覚を持って主体的に生きていく子どもたちを育成するためには、中学校からの英語の学びを小学校段階から進めていくことが必要であるというねらいのもとに。","id":"exchange-033"},{"speaker":"築舘委員","kind":"質問","question":"昔、石原慎太郎が出たときは２３歳ということですけれども、それ以来、若者はどういうふうにしているのかということで、テレビでやっていたんです。私はインターネットができないほうですから、どんな情報が入っているかさっぱりわからない。その点、やはり学校できちんと教えていくところは必要じゃないかと思うんですが、そこの点の学校教育でのインターネットをお聞かせください。","respondent":"中島指導課長","answer":"教育委員会でも昨年の夏以降、こういった情報教育に係わるインターネットを利用する際でのさまざまな事例、対処法といった形での研修会を実施してきてあります。","id":"exchange-034"},{"speaker":"築舘委員","kind":"意見","question":"その辺、しっかりとお願いしたいと思います。次に、図書館経費ということで、今回窓口業務を民間委託を全館されるということですが、このことは行政改革ということで、かなり効率をよくしていこうということと、サービス向上を徹底させようということだと思うんですが、今の現状をお聞かせください。","respondent":"古里品川図書館長","answer":"今回の窓口等の業務委託ですが、今年度４館モデル的に実施いたしまして、その効果、そして区民サービスの向上につながるのかどうかということを検証いたしまして、その結果、所定の目的を達した業務委託の形態が実現できるというふうに判断をいたしまして。","id":"exchange-035"},{"speaker":"築舘委員","kind":"意見","question":"民間ももちろんいいわけですけれども、民間の会社がしっかりやっていただくようなことも頭に入れてお願いしたいということとそれから、学校図書館と普通の図書館がインターネットで結ばれて、いろんな情報がやり取りできるということですけれども、その辺はどういうふうに活用していくのかお聞かせください。","respondent":"古里品川図書館長","answer":"学校図書館用のコンピューターシステムと、私どもが運用しています公共図書館用のコンピューターシステムが相互に連携して動けるような開発をしていく予定です。","id":"exchange-036"},{"speaker":"築舘委員","kind":"意見","question":"子どもたちにとって、そういうことで活用できるということ。先ほど、芥川賞作家などは若い人たちが増えてきたということで、若い層が本に対する興味が戻ってきたのではないかという話もあるんですが、若い人たちが本を借りるということに関しての数が相当増えているのか、それから影響というのがどういうふうに出ているかというのを聞かせてください。","respondent":"古里品川図書館長","answer":"やはり、これは中学校時代からの読書習慣をいかにつくっていくかということで、学校図書館の整備との関係も出てくるかというふうに考えてあります。","id":"exchange-037"},{"speaker":"武内委員","kind":"質問","question":"私は４点、２９３ページの学校職員被服貸与費、２９５ページの小学校におけるカウンセリング事業、同じく２９５ページの子どもへの暴力防止対策（ＣＡＰ）事業、３０１ページの学校環境整備事業をお願いしたいと思います。初めに、２９３ページの学校職員被服貸与費ですけれども、どのような服を貸与されていらっしゃるか、また何人分ぐらい貸与されていて、１着どれぐらいの金額なのか教えてください。","respondent":"市川庶務課長","answer":"概略を申し上げますと、用務につきましては、用務の職員が１年を通して行うさまざまな職務に対応したいわゆる業務服に始まりまして、靴、長靴、防寒用上着等々です。給食調理につきましては、調理作業に伴います白衣、作業着、前掛け、給食帽、そういったものです。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問","question":"細かくありがとうあります。大体、貸与されている内容がわかりました。一応、貸与という形になっていますが、実際には１年間使われるのかどうかわからないんですが、毎年貸与という形で予算が盛り込まれているのか、何年ぐらいで変わるのか。実際に着てしまいますと、汚れてきたときには返却という形にならないかと思うんですけれども、その辺のところも教えてください。","respondent":"市川庶務課長","answer":"種別によって多少の違いはありますけれども、基本的には３年に一度の貸与期間ということで設定しています。貸与期間中の被服のクリーニング等については、基本的には本人が行うものと。やむを得ず棄損等をした場合には、随時の対応をしています。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、２９５ページの小学校におけるカウンセリング事業ということでお伺いしたいと思います。私も昨年の第２回定例会の一般質問で、小学校への適切な配置ということで要望してまいりましたので、非常にうれしく思いますが、大井地区に１校ということで、大井第一小学校というふうに聞いておりますけれども、その辺の事情と、なぜ大井第一小学校になったのか、この辺の経緯を教えてください。","respondent":"中島指導課長","answer":"この中で、旗台小学校だけではなくて、周辺の小学校にも行きまして取り組んでいるといったような状況の中で、さまざまな成果が見えてきている経過がございまして、２人目といたしまして大井地区にということで考えました。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"そうすると、大井第一小学校を中心に、ある程度大井地区の中学校を担当されるというか、そういう認識でいいのかどうか。これで荏原地区と大井地区に１校ずつ配置されましたけれども、まだ配置されていない地域もあると思うんですが、その辺の地域についての今後の配置の可能性というか、予定というか、その辺がありましたら教えてください。","respondent":"中島指導課長","answer":"今後どういう形でこれを拡大していくかということにつきましては、また今年度の実施状況、またさまざまなニーズ等を踏まえて、検討していきたいなと考えております。","id":"exchange-041"},{"speaker":"武内委員","kind":"確認","question":"続きまして、同じページの子どもの暴力防止対策（ＣＡＰ）事業ということで、これは１９７８年にオハイオ州でつくられたプログラムだというふうに聞いておりますけれども、ＣＡＰの主な内容と導入された背景、またこれは全小学校で実施されるのか、それから小学校３年生に実施するというふうに聞いておりますが、その辺の確認と、小学校３年生であるとすれば、なぜ小学校３年生なのか。","respondent":"中島指導課長","answer":"プログラムとしては３年生という形で一応位置づけてありますが、１８年度からの移行に関しましては、実施状況においては４年生での実施が出てくる可能性もあるかもしれません。最終的には、３年生での実施という体制を組んでいきたいと考えているところです。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"私どもも党として何回かＣＡＰを取り上げさせていただいた経緯もありまして、質問させていただいているんです。そうすると、小学校３年生というのは、１年生、２年生だとまだ理解というか、いろんな面で逆にロールプレイの中で受けとめ方に問題があるとか、そういうことがあるのかどうかということ。","respondent":"中島指導課長","answer":"私どもといたしましても、ＮＰＯとの連携の中で、実際に教員が研修を受け、そして、ともに子どもたちの指導にあたるという体制を、来年度組んでまいりたいと考えております。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、まだ具体的に決まっていらっしゃらないのかなというふうに受けとめましたけれども、もし決まっているのでしたら教えていただきたい。当然、これは子どもの実施の前にやって、しっかりその後のフォローもするということだと思うんですけれども、その辺のところの状況を教えていただきたい。先ほど課長からありましたけれども、児童虐待に関して早期発見というか防止ですね。","respondent":"上川内生涯学習課長、中島指導課長","answer":"保護者に対するＣＡＰの取り組みですが、ＰＴＡの活動支援事業の中で、家庭教育の委託学級という形で保護者の方にＣＡＰの体験をしていただきます。どこと連携を図るかというＮＰＯの相手ですが、現段階では決定してございません。それから、これが児童虐待等への対応の一助になるのではないかというご指摘ですけれども、その要素はかなりあるのではないかと思います。","id":"exchange-044"},{"speaker":"武内委員","kind":"意見","question":"最後に、学校環境整備事業ということで、モニター付電子錠が計上されていると聞いているんですが、先ほども委員からありまして、一応２４校分と聞いているんですが、先ほどのご答弁で、これですべての学校にモニター付電子錠が完備するということなんですが、そうすると今の段階で小学校１６校はついているという認識でいいのかどうか。","respondent":"市川庶務課長、中島指導課長","answer":"モニター付電子錠の関係ですけれども、現状は既に設置してある学校、それから現在改築中の学校、それからこれから近時に改築する学校、それらを含めて１５校とカウントしています。そこで、オートロックを解除したとしても、今度は来校者の方が校内に入ってくる状況がありますので、その時点までに先ほど申し上げましたような複数態勢を学校のほうでつくりまして対応するというふうに考えてありますので。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"私から、２９７ページの小中一貫教育について質問したいと思います。テレビ局のアナウンサーの方が合格者に対して「今、一番何をやりたいですか」と次々に質問するんです。テストに出るから嫌だけどしようがない」と。質問したいのは、こういう中学３年生の率直な思いに対して、小中一貫教育ではどんなふうにこたえていこうと思っているのか、大きな質問になりますけれども教えていただきたいと思います。","respondent":"中島指導課長","answer":"品川区の公立学校で目指す小中一貫教育で、何を求めていくかというご質問かと思います。ご承知のように、小中一貫教育を進める本区では、子どもたちの基礎学力の定着、そして豊かな人間性、社会性の育成、この二つを大きな柱として取り組んでいきたい。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は小中一貫教育の特徴について、２点指摘したいと思うんですけれども、これまでもたびたび取り上げてきましたが、まず上級学年の教育カリキュラムの前倒し、それに伴っての授業時間の増、なぜカリキュラムの前倒し、そして授業時間の増加が子どもにとって楽しいと思える、学ぶことが面白いと思える学校になるのかどうか、もう一度説明をいただきたいと思います。","respondent":"中島指導課長","answer":"これにつきましては、それぞれの教科、それぞれの考え方なりコンセプトを持って、そういった体制を組んでいるわけで、それをすべて今この時間で説明すると、あっという間に時間が終わってしまいますので、そういうわけにもまいりません。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"高校２年生の虚数という部分を中学校３年生でやるんですね。その結果、授業時間も当然増えるわけですから、小学校５年生から７時間目授業が始まるんですね。７時間目授業を行うためどうするかと、僕も見て驚いたんですけれども、昼休みの２０分間を掃除の時間に充てる。つまり、週に１回、昼休みがなくなってしまう。それについて、一言だけご答弁ください。","respondent":"中島指導課長","answer":"７時間目の部分につきましては、ユニットと申しまして、４５分の授業を１５分単位で組み直して、朝の時間に学習するとか、そういったような工夫を今後していくことを考えてあります。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問","question":"その３００字は、今の国語の教科書に入っているのかどうか伺いたいと思います。それと虚数の問題、私も改めて教科書会社が出した高校２年生の数学の参考資料を見たんですけれども、私自身も昔は習ったけれども覚えていないんですね。Ｉ二乗イコールマイナス１、これを中学校３年生に学ばせる教育的意義が一体どこにあるのかと思うんですけれども、いかがでしょうか。","respondent":"中島指導課長","answer":"Ｉというのがあるんだよということありきで、指導するわけではなく、子どもたちの発展的な学習の内容の中で、子どもたちが意欲を持って、関心を持って数学に取り組む一つの手法として、こういったＩという世界に触れていくというような内容を想定しているところでございまして。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"虚数の問題ですか、例えば率直に中学校の先生に聞いたんですけれども、高校の数学は高校に入ってから十分学べばいいことであって、中途半端に中学校３年生に教えると、かえって理解がこんごらがってしまうという、これが率直な現場の思いなんですね。","respondent":"中島指導課長","answer":"漢字についてでありますけれども、１,９４５字の常用漢字がすべての教科書に、すべて同じように出てきているわけではありません。本区で採用している教科書の中に出てきている漢字をベースにして、ここも学んでいくことは間違いございません。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"ＯＥＣＤの調査ですけれども、課長がおっしゃったように学んだ知識や技能が、実際の社会の中でどのように活用できるかどうかをはかった資料なんですね。実際、ＯＥＣＤの東京センターが今年の１月２７日に講演会をやっておりますけれども、区教育委員会のどなたか参加されたのかどうか伺いたいと思います。もちろん週休２日制です。品川区は、こういう教育を検証の対象にしないのでしょうか、教えてください。","respondent":"中島指導課長","answer":"数学的理解力は香港が１位になっておりますし、問題解決能力では韓国が１位になっている。それぞれの国のそれぞれの方針がある中で、日本はどうあるべきかということを、やはり考えていくのが重要ではないかなと、このように思っています。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのために毎週金曜日には時間割をつくらずに、１日中総合的な時間に充てていると伺いました。私はフィンランドの教育を改めて注目して、小中一貫教育とは大分かけ離れていますけれども、授業時間数も３分の２程度なんですね。最後に質問したいのが、フィンランドの教育のモデルになったものは何だったのか、これを教えていただきたいと思います。","respondent":"中島指導課長","answer":"フィンランドの文献を幾つか読ませていただきましたが、それについては残念ながら私のほうでは存じあげてございません。","id":"exchange-052"},{"speaker":"中塚委員","kind":"意見","question":"私も講演の全文がインターネットにあったので読んでみたんですけれども、改めて話を聞いて驚いたのは、フィンランドの教育の基礎をつくったのは日本の憲法であり、教育基本法であり、６０年代の日本の教育をフィンランドが基礎にして学んだそうです。私はＯＥＣＤ２００６年にまた行われますけれども、こうした結果を真摯に受けとめて研究をしていくべきではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"須藤委員","kind":"質問","question":"２９４ページの教育指導費に関連して、質問をします。先ほどもちょっと出ましたように、今日の新聞に一ツ橋の文芸教育振興会と日本青少年研究所が昨年の秋に日・中・米で３,０００人の高校生に調査をしたところ、日本の高校生は勉強が嫌い、消極的で自信がない、将来に悲観的で自分の国に誇りが持てないというのが出されているんですが、こういうことに関して何かお考えがありましたら教えてください。","respondent":"中島指導課長","answer":"それぞれの目的に応じて将来志向はあるものの、基本的にみずからが社会とどういう係わりを持っていくのか、みずからがどういう修養をしていかなければならないのか、こういった内容をきちんと押さえていくことが必要ではないかなと考えております。","id":"exchange-054"},{"speaker":"須藤委員","kind":"質問","question":"こういう社会の状況ですから。そういった中で、今教育委員会でいろいろと専門的教育をそこに植えつけながら、そして一般教養を図っていくというようなありようというふうに私はとらえているんですが、こういった今のまちの人に学ぶとか経済活動体験学習というのは、そういった意図があるかどうかお知らせください。","respondent":"中島指導課長","answer":"市民科におきましては、１年生から９年生に向けてさまざまな体験活動をそこに散りばめる中で、トータル的に子どもたちの学び、そして生活、そして社会性、人間性を高めていきたいと考えておりますので、この体験活動等の重要性は教育委員会も深く認識しています。","id":"exchange-055"},{"speaker":"須藤委員","kind":"質問","question":"というのは、今の少子化の中では、そうしたことがだんだん少ない状況になっている。ですから、高齢者施設と連携していろいろやったり、お年寄りと給食を食べたり、いろんなことを教育委員会ではおやりになっていますけれども、今度は保育とか小さな子どもと接触する場面をつくることはいかがでしょうか。","respondent":"中島指導課長","answer":"私どもがプランニングしております市民科におきましても、将来設計の部分で５・６・７年生を中心に、育児理解ということで幼稚園、保育園での体験というものを位置づけながら、子どもたちか普段接することが少ない小さい子どもたちとの接点を通して。","id":"exchange-056"},{"speaker":"須藤委員","kind":"質問","question":"アメリカでは子どもたちに正義のために言葉を発するとか、そのことについて行動するとか発言をするとかということがあるんですが、日本の子どもたちは和をもって尊しとすると、争いごとをしないよということで教育されてきているように思うんですが、今の教育で正義というのはどういうことを日本の教育委員会では考えていらっしゃるのでしょうか。","respondent":"中島指導課長","answer":"例えば、小学校１年生、２年生の段階では、良いことと悪いことの区別を、決まりを守ることから覚えさせたり、それから例えば途中で間違いがあっても、失敗があっても、それは正しいと思うことに向けて取り組めばいいんだよというようなことを書いたり。","id":"exchange-057"},{"speaker":"須藤委員","kind":"質問・要望","question":"ある人が戦前の日本の正義というのは、いわゆる勤勉である。それから、忠勇である、それから勇気、そういうことが戦前の正義であった。安全な社会、安全だというような。そうすると、安全というのをしっかり固めてしまうと、社会全体が非常に怠惰な状況になったり、嫉妬を求めたりというようなことになってくると思うんですけれども、その辺の考えはいかがでしょうか。","respondent":"中島指導課長","answer":"社会の中での正義というものを、どのように子どもたちが身につけていくかというのは、非常に難解な課題ではありますけれども、一貫教育の市民科を通しまして、子どもたちにぜひ私たちとしてはその育成を図ってまいりたいと考えているところです。","id":"exchange-058"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど話したように、今、教育改革が非常に進んできて、私ども地域はすぐ大田区のところなので、大田区の子どもたちも品川区の学校に入りたいというぐらいに、非常に今の教育改革が進んで、子どもたちが変わっているのを現場で見ていますので、ぜひとも頑張って素晴らしい教育を続けていただきたいとお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"井上委員","kind":"確認","question":"ＣＡＰの質問がされましたけれども、本来ＣＡＰというのは大人と子どもと決して一緒に受けないプログラムであって、先ほど先生が研修を受けて、先生が指導できればいいというような発言があったんですけれども、ここのところは大変重要なプログラムで、子どもの権利を、エンパワーメントを育てるというプログラムで、決して先生が研修を受けてできるようなものではないと思うんですが。","respondent":"中島指導課長","answer":"教員もＣＡＰに対する研修が必要だということで、ＮＰＯの力を借りて教員対象の研修も実施いたします。教員の理解を深めた上で、ＣＡＰの方にお出でいただいて、そこで実施するです。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"先生が受けることは当然あってほしいことだと思いますけれども、そこのところは先生が子どもたちに指導するということではないと思いますから、そのようにしていただきたいと思います。そうすると、学童保育クラブが廃止になるわけですが、今まで学童保育クラブに通っている養護学校の児童と私立・国立に通っている区内の児童は、その後どうなるのかということを確認させてください。","respondent":"富田教育改革担当課長","answer":"これまですまいるスクールは実施校との強い連携のもと実施してきておりますので、実施校以外の子どもの受け入れにあたりましては、小学校の校長会への十分な説明ですとか、そういったことを踏まえまして、平成１７年度４月当初よりといいますと新１年生の時期と重なりますので。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"今、養護学校の学童保育クラブに通っていた子どもたちが、すまいるスクールになって通えなくなっているという現状は、当初の目的からいえばおかしなことだと思うんですけれども、そこはちゃんと保障していかなければいけない問題だと思いますけれども、今後どのようにされるのでしょうか。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは先ほど申しましたように、実施校との強い連携のもとにやってきております。これまで実施校以外の子どもに利用いただくということは、学校としてあまりやってこなかった状況です。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"次は心障学級経費ですけれども、昨年の心障学級経費と今年の心障学級経費でいいますと、１,２４０万１,４００円ぐらい多くなっているんですけれども、この事業の内容で何か変わったところがあるのでしょうか。","respondent":"谷田部学務課長","answer":"介助を必要とする子どもの増に対応するため、介助員経費を組んだということ。それから、２点目の大きなところで言えば、特別支援教育検討委員会を来年度も引き続き実施するということで、今年度に比べまして実施回数、それから開催の仕方等を変えてあります。","id":"exchange-063"},{"speaker":"井上委員","kind":"意見","question":"今、特別支援教育検討委員会を継続してということだったんですけれども、今回の資料を見しますと、特別支援教育検討委員会のメンバーが１１名います。それから、特別支援教育コーディネーターの指名というものもありますけれども、特別支援教育コーディネーターというものを品川区はどういう役割で、どういう方を指名されようと思っているのかということをお願いします。","respondent":"谷田部学務課長","answer":"四つほど質問がございました。１点目の特別支援教育検討委員会のメンバーです。今年度、医療、保健、福祉、教育の分野から１７名の方に検討委員としてお入りいただきまして検討委員会を組織し、これまでさまざま検討してきてあります。","id":"exchange-064"},{"speaker":"井上委員","kind":"意見","question":"コーディネーターは、特別な支援が必要な児童・生徒の指導にあたる学校の窓口としての指名ということなんですけれども、校内委員会のほうも受け入れ体制を学校で取る必要があるので、それを組織していくというような答弁かと思うんですが、特別な教育が必要だと思われる児童や生徒の共通認識を図るというものが校内委員会だというものを。","respondent":"谷田部学務課長","answer":"ただ、私どもが考えていますのは、今まさに東京都はモデル事業としてそのような体制づくりをやっておりますが、それがなかなか機能しないという話も一部聞いてきてありますので、私どもは校内委員会でも何でも呼び方はいいんですが。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"始まったばかりで、これから検討をしながらということだと思うんです。今回、小中学校に１校ずつモデル校を選ぶということがありますが、ここの学校はもうお決まりなんでしょうか。","respondent":"谷田部学務課長","answer":"３月２日に最終の検討委員会の中で、今年度の検討結果をまとめるにあたっては、先ほど私も申し上げましたけれども、モデル校として指名するのではなくて、実際に手立てを必要とする学校に出向いて行く、呼ばれて行きましょうと。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちは一般質問でも言いましたけれども、学校調整会議において教育委員会と連携して学校と栄養士、そして調理事業者、保護者、児童、生徒の当事者が入った調整会議をしながら、生の声、現場の子どもたちの声を反映できる仕組みにしていただきたいということを要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は３００ページの学校管理費、２９４ページの教育指導費について、それから学校設備費についてお話しさせていただきたいと思います。産業もそんなに発展していない。そうすると、どうしても教育に頼らざるを得ない。その中で、やはり何でもそうですけれども、目標に向かって進む向上心も必要ではないかと思うんですけれども、その辺、教育委員会としての見解をお聞かせください。","respondent":"中島指導課長","answer":"今、ご指摘のありました目標に向かって進む、向上しようとする気持ちを子どもたちが持って物事に取り組むということは、非常に重要なことではないかと考えています。","id":"exchange-068"},{"speaker":"須貝委員","kind":"質問・要望","question":"でも、子どもを持つ親からすれば、何でもいいから早く安全な学校をつくってほしい。ここを施錠して本当に済むのかということになれば、親からすれば、親がお金を出しても警備員を置いてほしいとか、そういう切実な願いがあると思うんです。目に見えるものが大切ではないかなと思うんですけれども、その辺のご見解をお聞かせください。","respondent":"市川庶務課長","answer":"少なくとも、私どもはそういうことで対策を講じているつもりです。目に見えるものすべてが有効かといいますと、またそうでない面もあります。ただ、安全確保ということで、少なくとも実効性を出す対策を今後も講じてまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に間違いがあってはならないし、品川区の教育委員会がいろいろな新しい事業を立ち上げようとしていることが消される場合もありますので、本当にこのことに関しては誠心誠意頑張っていただきたいと思います。次に、学校施設建設費についてお伺いいたします。このたび、お話しを聞きましたら、最も大きいところで１０ｍもさらに道路からセットバックする。","respondent":"市川庶務課長","answer":"荏原第一中学校の校庭に関するご質問で、ご指摘の件は平成１２年に設置いたしました荏原一丁目まちづくり広場、これは密集市街地整備促進事業の関連で取得した約１,０００m2の土地です。それが荏原第一中学校の校庭とまさにつながってあります。","id":"exchange-070"},{"speaker":"須貝委員","kind":"質問・要望","question":"なおかつ一般の地域の人があそこを使っている姿、あそこにたむろしている姿というの逆になくて、荏原第一中学校と隣の住宅とそこの場所を通路に使っているパターンがすごく多いと思いますので、子どもたちの利益のために何とか守る努力をしていただけたらありがたいなと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"既に、小学校５年生を対象にしたスチューデント・シティが八潮南小学校で開設されておりますが、今度新たに中学校２年生を対象にして経済体験学習が城南中学校で始まるですが、内容的に、当然小学校を対象としたものと中学校を対象としたものは、レベル的には多分中学校のほうが上がっているのではないかと思いますが、内容について特に小学校との違いについて、まずお知らせをいただきたいと思います。","respondent":"中島指導課長","answer":"小学校のスチューデント・シティですが、これは八潮南小学校に仮想のまちをつくりまして、その中で子どもたちが買い物をする中で、それぞれのブースでのお店経営を学ぶという視点で、小学校５年生を対象として実施しているものです。本年度で２年度目が終わるという段階です。","id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"実践の中にも、疑似的なものと本当の社会での違いも発見しながら学んでいくということが、両者あるいは市民科の学習も含めて考えると、さまざまな形の相乗効果が出てくるのではないかという期待を持っているんですけれども、その辺のお考えをお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"例えば、中学校におきましては、現在職場体験ということで区内のさまざまな企業のところにお邪魔して、そこで体験をするようなメニューがあります。その中で実際の経理まで全部子どもたちが係われるかというと、そこの部分は十分に機能できない部分があるのではないかと考えます。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"その中で要望といいますか、小中一貫校の中においての市民科の学習というのは、連続して長期間にわたっての学習がなされるわけですが、一方実践面でのスチューデント・シティは小学校５年生だけ、またファイナンス・パークは中学校２年生だけ、とはいいながらもそれぞれ事前の学習も含めたり、実際の現場での学習も含めると、時間数はまあまああるのかなと思いますが。","respondent":"中島指導課長","answer":"中学校１年生の段階では、ＣＡＰＳという同じような体験のコンピューターによるプログラムなども導入してまいりたいと考えておりますので、一連の中で二つの体験学習がプログラムされているというふうにご理解いただければと考えております。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"逆に競争社会だからこそ、日本がここまで発展してきたものだというふうに思っております。スチューデント・シティの中でも、例えば一生懸命営業をすればこれだけの売り上げが上がるんだという、そういった疑似体験があってもいいのかなというふうに思うんですけれども、そういった視点からの考えをお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"中学校の経済体験学習でも、最終的に非常に裕福になる子どもも出てまいりますし、破産してしまうというような子どもも出てまいりますので、そういったようなさまざまな疑似体験がそこで実施できるものと考えています。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"仕組みができたら、今度は中身をさらに向上させるということで、また並行してさまざまご努力をいただいていると思いますが、教員の質の向上というのでしょうか、教師の先生方の質をいかに高めていくかということが大きな今後の問題ではないかなと思います。今はプラン２１ですから、仮に名前をつけるとプラン２２が仮にあるとするならば、その辺の考え方をお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"今後、地域との連携が、また役割分担がより叫ばれる中で、安全も含めまして地域とともに小学校と中学校の連携を考えることで、より学校と結びついた教育活動を展開していければなと、このように考えてあります。","id":"exchange-076"},{"speaker":"山村委員","kind":"質問・要望","question":"私からページ数がちょっとわからないので申し訳ないんですが、外国語指導助手の ＡＬＴのことに関してと、２９９ページの学校ＩＴ化推進費、時間がありましたら３０７ページの修学旅行費についてお伺いします。外国語指導助手のＡＬＴのことについてお伺いしますが、採用はどのような形を取られて採用されているのか教えていただきたいと思います。","respondent":"中島指導課長","answer":"こちらのほうは、委託という形で入札しています。","id":"exchange-077"},{"speaker":"山村委員","kind":"質問","question":"入札で研修が民間任せになるということで、それ自体は私にはわからないんですが、勤務態度が悪いような方がいらっしゃったことが品川区であるのかということと、まずジェットプログラム並みに質を維持されているのかということ。それと、１校１日分、大体幾らぐらいかかるのか教えてください。","respondent":"中島指導課長","answer":"それまで、若干苦情のようなものがございましたが、今年度につきましては、そういった苦情は教育委員会のほうに特に入ってきてございません。派遣の経費ですが、１日１人１万２,０００円です。","id":"exchange-078"},{"speaker":"山村委員","kind":"質問","question":"今まで寄せられた苦情等、何かありましたら教えていただければと思います。それと、１日１万２,０００円は、結構安いほうかと思うんですが、２３区の平均というわけではないですけれども、なぜここまで安くできたのかということを教えていただければと思います。","respondent":"中島指導課長","answer":"そういったものに比べますと、こちらの時間単価にすると、かなり低い額になっているのではないかと思いますが、それは派遣会社での対応という形になってあります。","id":"exchange-079"},{"speaker":"山村委員","kind":"意見","question":"価格を優先しすぎてもまずいような気がするんですが、その辺でもう一度、本当に質が保たれているのかどうか。","respondent":"中島指導課長","answer":"実際に本年度の実施の中では、学校とＡＬＴとのコミュニケーションがよく取れて、ＡＬＴを活用した授業が小学校において非常によく展開されているという話でありますので、授業の質につきましても、それなりのものが確保されていると、このように考えているところです。","id":"exchange-080"},{"speaker":"山村委員","kind":"質問","question":"そうすると、ジェットプログラム並みの質は維持されているというふうに理解させていただいていいのかということを確約していただくのと、採用の方法ですけれども、入札よりプロポーザル方式に変えたほうがいいのではないかと思うんですが、そこに関して教えていただければと思います。","respondent":"中島指導課長","answer":"ＡＬＴの採用につきましては、入札の仕様書段階でかなり厳しく条件をつけてありますので、そういった質は担保されているものと考えております。プロポーザル方式につきましては、委託内容また契約等々との関係でできないという形になっております。","id":"exchange-081"},{"speaker":"山村委員","kind":"意見","question":"他区ではプロポーザル方式で採用されている現状のほうが多いと思うんですが、なぜ品川区ではできないのか、もう一度説明していただければと思います。","respondent":"鷹倉経理課長","answer":"指導課長から話がありましたとおり、仕様書の中で一定のレベルを確保すると。それから、私どもも経理課サイドとして、一定の実績のあるところを選定しながら候補を指名していくですので、一定のレベルを保たれていると考えています。","id":"exchange-082"},{"speaker":"山村委員","kind":"質問","question":"私が質問をしたのは、プロポーザル方式になぜできないのかということを質問したので、必要ないと思われているなら必要ないんでしょうけれども、先ほどできないというふうに言われましたので。","respondent":"鷹倉経理課長","answer":"採用するに際して、プロポーザルをすることによって、一定の質が保たれるというような判断があれば、そういうことが選ばれるでしょうけれども、現在のところ、そういうことをしなくてもできるという判断があろうかと思います。","id":"exchange-083"},{"speaker":"山村委員","kind":"提案","question":"その割には、今まで苦情があったようなことをお聞きしたんですが、そういう意味では、当然価格優先にならざるを得ない部分があると思うんですけれども、研修体制とかそういうところまでちゃんと提案していく形で契約をされたほうがいいと私は思います。次の質問をします。学校ＩＴ化推進費で、全教員にパソコンを配備ということだそうですが、このパソコンはどういうことに使おうということなのか。","respondent":"中島指導課長","answer":"イントラですけれども、校内のイントラを設置することによりまして、その中での情報共有をグループウェア等を使って実施していく予定です。","id":"exchange-084"},{"speaker":"山村委員","kind":"質問","question":"そうすると、校内では情報共有していくということで、他校とは情報共有しないのかということ。それと、そのパソコン自体はインターネットにつながるのか、それとも情報漏洩の観点から、インターネットにはつなげないのか、その辺のことを教えていただければと思います。","respondent":"中島指導課長","answer":"これらのパソコンにつきましては、学校の中でのイントラとしてつないでいる状況です。そして、インターネットへの接続等も、今後検討していきたいと考えているところです。","id":"exchange-085"},{"speaker":"山村委員","kind":"質問","question":"そうすると、教員一人ひとりに割り当てられたパソコンに、当然生徒の個人情報が載ってくると思うんですが、その生徒の個人情報を学校にあるパソコンから出ていくということはあまり考えられないと思うんですが、先生のほうが例えばその生徒の個人情報、どこまで個人情報というか私にはわかりませんが、そういうものを自宅のパソコンに持ち帰ってやった場合。","respondent":"中島指導課長","answer":"基本的には、学校の中でのイントラの中で、情報の一元管理というような方法が考えられると思いますが、外へ持ち出さない、それから情報の管理をどのようにしていくかというあたり、それをまた来年度の検討委員会の中で具体的に詰めていきたいと考えているところです。","id":"exchange-086"},{"speaker":"山村委員","kind":"質問","question":"例えば、その小学校での児童の情報が６年間なら６年間あったとして、小中一貫だったら当然小中一貫校内で小学校から中学校に行くときでも、その情報は当然共有されるんだと思うんですが、例えば小中一貫でないところで品川区内の中学校に行った場合は、そういう情報は行くのか、それとも小学校は小学校の内部だけで止めておくのか教えていただければと思います。","respondent":"古里品川図書館長","answer":"学校ＩＴ化検討委員会のリーダーをやっています関係で、私のほうからお答えさせていただきたいと思います。委員が今おっしゃいますような、成績をデータ化してイントラの中に載せていくということは、まだ当面考えてございません。","id":"exchange-087"},{"speaker":"山村委員","kind":"質問","question":"修学旅行費のほうでお伺いしたいんですが、少し前にテレビを見ておりましたら、中学校の修学旅行で教員が父兄から集めた代金の中で、常習犯的にそのお金でお酒を飲んでいたというか、そういう不正使用がどこかの区であったらしく問題になっておりましたが、品川区ではそういうことはないのはわかっているんですが、その辺のことをお聞きしたいのと、業者が大体そういう場合は固定されていたそうであります。","respondent":"谷田部学務課長","answer":"１点目の先生の飲食の関係ですが、品川区の教員に限って、そういうことはないです。それから、２点目の業者の関係です。","id":"exchange-088"},{"speaker":"山村委員","kind":"質問","question":"当然、品川区ではこういうことがないというのはわかっておりながら質問をさせていただきました。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"３０５ページの学校図書館運営費と、３２３ページの図書館経費をお伺いします。学校図書館のネットワーク化、そして区立図書館のサポートについての中身と、特にだれが担当を行っていくのかというところ。それから、窓口運営業務委託のところで特に配置、週何日ぐらいいるのか、また同じ人が配置されるのか。それから、委託された方に直接指導できるかどうか、その辺を重点にお願いします。","respondent":"古里品川図書館長","answer":"それと、学校図書館における業務委託ですけれども、こちらにつきましては現在予定では週２日要員を配置いたしまして、運営をしていくということにしています。基本的には、その学校に行く委託のスタッフにつきましては、同じ人に行っていただくようにしております。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口業務委託のところは、週２日というご説明だったんですが、やはり図書館を回していくためには毎日配置をしていただきたいと考えています。学校図書館というのは、本当に学校の中身そのものを理解しないと、なかなかサポートができないというところでは、日数の問題と学校との連携について問題があると思うんですが、どのように改善をしていらっしゃるのでしょうか。","respondent":"古里品川図書館長","answer":"その件につきましては、先ほど申し上げましたけれども、年間の運営予定、月間の運営予定をあらかじめ校長、教頭、図書担当の先生を含めて、話し合いをさせていただきながら進めていくということにしています。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口業務の委託といえども、人が増えること。何と、朝から放課後まで子どもや教師がひっきりなしに図書室に集まって、１日の貸出冊数が４００冊にも及んでいるそうです。全校の子どもが６８１人に対して６０％の子どもが本を借りている。ぜひそういった面では、以前からずっと要望しているんですが、品川区でもぜひ専任の司書教諭とか司書を配置していただきたいんですが、いかがでしょうか。","respondent":"中島指導課長","answer":"もちろん、校内の中でも図書担当の教諭はいるわけですので、そういった教諭が中心となって図書委員会、図書のボランティア、また一貫教育の中で実施する読書指導の時間、こういったようなものを活用しながら。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中身もというところでは、ぜひ司書教諭の専任を実現していただきたい。再度、求めます。もう１点、図書館の問題ですけれども、この間、窓口業務の委託が４館から全館に広がっていますが、委託業務をどこまで広げていくのか、そのお考えと、図書館法に基づく公立図書館のどこを直営として守っていくと考えているのか。もう１点、区民の声をどこで受けとめていくのか、３点お伺いいたします。","respondent":"古里品川図書館長、中島指導課長","answer":"今後、委託の範囲を拡大するのかということにつきましては、現在今年のモデル実施、それから来年の内容については全く変わってございませんので、当面この形で進めていきながら。１２学級以上の学校に配置される司書教諭は兼務という形ですけれども、新しい学校につきましては情報センターという形で図書館、そして調べ学習ができるパソコンも有したメディアセンターの機能を重視した形で。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口業務のところですけれども、委託になった最大の問題点、私はレファレンスの問題だと思うんです。ぜひ、窓口のレファレンスの強化と専門性を高める努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"確認","question":"約５,２００万円、予算上ではかかりますけれども、これで研修だけで終わらせることではないと、当然私たちは思っておりますので、確認したいのが、配付するパソコンの中に教材開発に係わるソフトが入っているかということ。それから、その活用をどうするかということ。これに伴うデータ管理とか、それからパソコン自体の盗難対策をどう考えていくのでしょうかということをお聞かせください。","respondent":"中島指導課長、古里品川図書館長","answer":"もちろん、私どももそれに伴いまして、来年度スキルアップ研修ですとか情報モラル、個人情報等のセキュリティの研修ですとか、授業での活用の内容、場合によってはｅランニング。そのことに最大限配慮をして、来年度に十分検討していきながら、委員おっしゃるような高度な教材開発ができるような状況も、当然ステージとして考えてあります。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、そのハード整備を、今小中一貫校の建築が始まっておりますし、これから学校改築が始まっていくわけですよね。それから、教員も品川区にいる間は品川区の職員であるはずですから、このパソコンをできれば庁内とつなげて、出退勤管理とか、今本庁や出先の職員にカードで管理をやっていただいています。最後の部分は、できれば別のセクションから答弁をいただきたいんですが、いかがでしょうか。","respondent":"中島指導課長、市川庶務課長","answer":"こういったような展開も、私どもの検討の中で想定しています。実際に、新しく改築される学校等におきましては、各教室にそういった設備を整えているところです。教職員の出退勤を含んだ勤怠管理に将来的に活用してはですけれども、この件についてはこれまでも私どものほうから申し上げてきているところですけれども、環境が整い次第、実施する方向で検討しています。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"確認","question":"午後４時ぐらいです。初めて、受付で「どういうご用ですか」と、声をかけられた現状がありました。言いたいのは、各学校の教員、それからＰＴＡ、警察の方も入って、安全対策委員会のようなものを立ち上げて、具体的に子どもたちの安全をその委員会みずからが、この学校の安全はこうしたらいいということを考えていく仕組みをつくってみてはいかがでしょうかということをお聞かせください。","respondent":"市川庶務課長、中島指導課長","answer":"そこで、学校自身がどのような装置をどのように付けて、どういうふうに使ったら防犯対策の効果を上げるのか、これはぜひ学校の関係者、教員は当然ですけれども、保護者も含めて検討した上で工事の手続に入っていく。学校における家庭、地域、また関係諸機関との連絡、協力のもとでの安全確保についてですけれども、学校安全対策委員会ということで、それぞれの小中学校が学期に１回ないしは年間２回というようなところを目安に。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"意見","question":"それぞれありがとうあります。それから、これからの将来像ですけれども、児童に配布する近隣セキュリティシステムの子機があります。それから、各学校単位の安全管理の仕組みの中で、それをマニュアル化して、それぞれの学校の地域特性に合わせて安全管理対策を十分に確保するべきと思いますが、いかがでしょか、答弁をお聞かせください。","respondent":"市川庶務課長","answer":"２点目の学校単位でのマニュアルづくりをはじめ、学校の地域特性等に応じた今後の対応策については、そのような趣旨でこれからも進めてまいりたいと思います。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"意見","question":"安全対策というのは、いろんな角度からいろいろ考えていくべきだと思います。それはハード、ソフト両方あるかもしれません。ただ、近隣セキュリティシステムの導入に合わせて、ハード整備を十分考えるわけでありますので、ぜひともいろんな角度からご検討をしていただきますようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"嶋委員","kind":"質問","question":"初めに、教育指導費の中ですが、いよいよ１８日に中学校の卒業式を晴れて迎えることになりますが、受験真っ最中ですけれども、合格発表当日の学校の対応についてお伺いいたします。","respondent":"中島指導課長","answer":"都立高等学校等の合格発表ですけれども、子どもたちが受験した学校に行きまして、合格発表を見て学校に戻ってきて報告をすると、そういうような形式を大体どこの学校でも取っているかと考えております。","id":"exchange-100"},{"speaker":"嶋委員","kind":"確認","question":"午前中発表の場合と、午後発表とかばらばらになっておりますが、そういう部分の学校の対応が私はいかがなものかなということがございましたので、ちょっとお聞きをさせていただきました。合格合否どちらか、一つの試練ですけれども、いいことも悪いことも報告を受けてほしいという、私の今までの認識でありましたが、それが基本でよろしいでしょうか、確認をしたいと思います。","respondent":"中島指導課長","answer":"一つの受験合格というのも、進路指導の一コマですので、学校で教員がさまざまな子どもたちの実態に応じて励ます、または喜ぶ、指導すべきところであると考えております。","id":"exchange-101"},{"speaker":"嶋委員","kind":"質問","question":"私は、最近発行された元校長先生の本を読んだ後だったんです。だから君が落ちたことによって、また少し親子の時間が取れるね」という父の励ましのそういう本を読んだばかりだったものですから、ちょっと、今回の対応が、「報告は明日でいいから」というのは、とても残念だったので、その辺の事情がよくわからないのでお聞きしたんですが、もしご見解があったらお聞きしたいと思います。","respondent":"中島指導課長","answer":"そういった形で今後進路指導、まだ今後の自分の将来が決まっていない状況のある子どもたちも若干いると思いますので、学校のほうには指導してまいりたいと考えています。","id":"exchange-102"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、そうしていただきたいと思います。金曜日の場合は、土日挟んだら３日後に先生に報告するということになってしまいますので、ぜひこういうことが二度とないようにご配慮をしていただきたいと考えていますので、よろしくお願いいたします。近隣近接の幼稚園の子どもたちが、そこで食育を学んで楽しく食事をしていくということもあります。それが拡大できていけるのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"幼稚園での学校給食を利用した目的は、小学校との交流という観点だというふうに思ってあります。特に小学校と併設の幼稚園では、小学校との連携ということで、小学校のほうに出向きまして、小学校の給食を食べるような行事に取り組んでいる園もあります。","id":"exchange-103"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、これを進めていただきたいと思います。今、学校給食を近くの幼稚園に持っていくのは衛生上、好ましくないというお話が出たので、ちょっと予定していなかったことなんですが質問させていただきたいと思います。これは衛生上ということになると、ちょっと違うのかなと。もちろん衛生上は気をつけなければいけないことですが、やっているところがあるので、もう１回お聞きしたいと思います。","respondent":"谷田部学務課長","answer":"家庭で持ち込んだ弁当とは違うので、その辺の配慮は私どもしなければならないです。","id":"exchange-104"},{"speaker":"嶋委員","kind":"提案","question":"わかりました。いろんな意味で、民間委託していく部分がありますので、いろんなケースがあると思いますので、また何かのときに提案させていただきたいと考えています。学校給食のことでもう一つ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"嶋委員","kind":"質問","question":"ＰＴＡ地域健全育成運営協議会のことについてお伺いいたします。そういう意味では、本当に皆さんが地元の子どもたちを見守ってくださっているだけでも、私はすごく感動してお礼を言ってまいりましたけれども、こういうものはほかの地域ではどのように進められているのかお聞きしたいと思います。","respondent":"上川内生涯学習課長","answer":"家庭教育支援ということで、中学校１８校のＰＴＡに私どものほうから委託事業としてやっていただいているものですが、年に大体２回から３回やっていただいているところで、だんだん数が増えてきまして、今３回実施しているところが１４校、２回が４校です。","id":"exchange-106"},{"speaker":"嶋委員","kind":"質問・要望","question":"時間の関係で、先に進めします。それから、幼児から中学生向けの本の紹介パンフレット作成など、啓発事業を実施するとありますが、これもどういう角度でこういうものを選んでいかれるのかお聞きしたいと思います。やっているところは、本当に５００冊蔵書があります。そういう意味では、やっていないところの５００冊、やっていないところは、これに対してどのような反応があるのかお聞きしたいと思います。","respondent":"古里品川図書館長","answer":"あわせて同日、４月２３日は各図書館においてもお話し会等を実施したり、それからブックフェアをやったりという形で進めていきたいと思っています。対象年齢につきましては、子どもですので、幼児から小学生、中学生の低学年ぐらいまでを対象にして実施したいと思っています。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"３点ほど質問したいと思います。午前中、藤原委員の質問の中で、給食調理代行について質問した件で、ちょっと確認をさせていただきたいと思います。それから、２９７ページのすまいるスクール、３０３ページのほうに入るのでしょうか、心障学級のほうに入るのか入る場所がわからないんですが、介助員についてお聞きしたいと思います。その趣旨に対して、区としての考え方ですね。","respondent":"谷田部学務課長","answer":"先ほど来、この個別の問題について、どういう対応を取るのかというような趣旨の質問です。午前中、私は４月以降、適切に調理代行は行われるということで、ある程度の不安等が払拭できればというような趣旨の答弁をさせていただきました。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"それをもとに、小中学校の給食も安全でおいしい給食を提供して、なおかつ中身をよくしていきましょうという趣旨のもとで拡大をしていくわけですから、その意気込みといいますか考え方を、きちんと子どもたち、それから親たちに周知徹底するように、ぜひ努力をして強い態度で示していただきたいというふうに思っています。次に行きます。共同的な対応ができているかどうかを確認したいと思います。","respondent":"富田教育改革担当課長","answer":"ただいま保護者会が年２回の２回目をすまいるスクール実施校でちょうど行っているところですけれども、大きな不安の声もなく順調に４月を迎える準備を着々と進めているところです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"移行時期で、今年は２年目に入り、かなりいろいろと対応していただいているなという感じはいたします。先ほど井上委員からもありましたが、養護学校に入っている子どもたちの対応、それからどうしても学校の中で対処仕切れないという部分があろうかと思うんですが、障害のある子どもたちに対する対応については、今後どういうふうにしていかれようとするのか、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"養護学校の子どもなど、現在すまいるスクールを利用されていない子どもについても、すまいるスクールをというご質問かと思いますけれども、先ほど申し上げましたように、当面は学童保育クラブを利用している方については、児童課での事業の利用をですけれども。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな子どもがいらっしゃると思うんです。そういう意味では、横のつながりを十分取っていただいて、児童課はいろんな意味で事業展開していく形になっていきますし、共同しながらどういうふうに放課後を過ごさせていくのかというところで、進めていっていただきたいと思いますが、児童課長がいらっしゃったので、ぜひご答弁をよろしくお願いします。","respondent":"辻田児童課長","answer":"放課後児童健全育成事業をすまいるスクールに移行していく中で、だんだん学童保育クラブが閉鎖されていくという状況の中で、一つ障害を持っている方への対応ということが、今児童センター改革の検討の中で、具体的に今後どうするかということを詰めております。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、いろんな子どもたちと係われるような、そういう対応を含めて、これからいろいろ検討していただきたいというふうに思います。ここは款別が違うんですけれども、センター機能をどういうふうに持っていったらいいのか、総合的に考えていかなければいけないというふうに考えるわけですが、その辺はどのようにお考えになりますでしょうか。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは、実は他の全児童事業と比べましても、非常に参加が多いというのがありまして、すまいるスクールが放課後のすべてを担うことが望ましいと思っている状況でもございませんし、それでは今の実態はどうなのかということを。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"そうなっていくと、子どもたちの実態がどうなのかというところを踏まえた上で、それぞれの政策、事業展開であるべきだと思いますので、全区的にとは言いません。近隣セキュリティの地域の方へのアプローチにしても、すまいるスクールがある程度協力体制が取れるという可能性もありますので、その辺の動向についていかがでしょうか。","respondent":"富田教育改革担当課長","answer":"そういった意味では、保護者とのコミュニケーション、連絡協議会も課題であることは十分認識しておりますけれども、そういったことも含めて、保護者の方にも、もう少し関心を持ってもらい係わっていただけるような形というものを、今後とも追及してまいりたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"中心は自分の子どもですから、ある程度関心を持っていただくような問いかけも必要ですし、いろんな関係をぜひつくっていただきたいと思います。次に、介助員についてお伺いいたしますが、介助員の制度、それから先ほど１,０００万円の予算枠があるということなんですが、報酬がどうなっているのか、それから介助員の仕組みがどうなっているのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"１,０００万円の枠ではなくて、今年度に比べて１７年度は１,０００万円増額したです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"介助員を申請するのは、校長先生の判断で申請されると思うんです。具体的な介助員をお願いするのはだれなのか、その人を探すのはだれなのか、それはどうなっているのでしょうか。","respondent":"谷田部学務課長","answer":"介助員を探すのは、学校のほうで介助員の方を探していただくということでお願いしています。ただ、なかなか見つからないというような場合については、教育委員会のほうでわかる範囲で手伝いするというような内容になってあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"もう少し、数字的なところを聞きたいんですが、クラスの中で学習障害の子どもたちも結構いるということで、問題になっているんですが、介助員を必要としている数の推移は、ここ数年間どういうふうな動向があるのでしょうか。先ほど、１,０００万円増額したということになっているんですが、この増額というのは増えているから増やしているということなのか、その辺の推移はどうなっているのでしょうか。","respondent":"谷田部学務課長","answer":"私のほうでは、１４年度からの３カ年の資料がありますけれども、心障学級につきましては、入っていらっしゃる子どもの重度の関係で多少変動しますので、通常学級で説明したほうがわかりやすいので、通常学級のほうで説明いたします。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すまいるスクールのことで、関連でお伺いしたいんですけれども、学童保育クラブからすまいるスクールに、大きな問題もなくスムーズに移行しているというお話しがありましたけれども、学童保育クラブに通っていた子どもがすまいるスクールになって通えないという状況はないのかどうなのか、その点についてお答えいただきたいと思います。","respondent":"富田教育改革担当課長","answer":"そういったケースにつきましては、個別にさまざまな状況があろうかと思いますので、一律の問題ということではなくて、個別に担当指導員が相談を受けて、対応についてご相談に乗っていくというような対応をさせていただいているところであります。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何人ぐらいの子どもがすまいるスクールに移行したことによって通えない状況になっているのか、数字がわかったら教えていただけないでしょうか。","respondent":"富田教育改革担当課長","answer":"通えないような状況になったという報告は受けておりません。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区では働く親たちの大きな不安になっている」ということで、品川区の状況も紹介されております。そういうところでは、そういう状況をつかんでいないのか、そしてしっかりとここでは７,７００名から５,０００名に激減したという数字も出ているんですけれども、ぜひ実態をつかむ調査を品川区としてもやるべきだと思うんですけれども、その点についてはどうでしょうか。","respondent":"富田教育改革担当課長","answer":"ただいま、学童保育クラブではきちっと配慮して見ていられたのが、すまいるスクールに来たらそういうことがなくなったので来られなくなったかのようなご質問がございましたけれども、３１校ですまいるスクールを実施しておりますけれども。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わくわくプラザのほうでも、こういう形でしっかりと数字に表れているということで調査をしています。品川区としても、こういう形でしっかりと調査をして、通えていない実態がないというのであれば、その実態を明らかにするためにも、ぜひ調査をしていただきたいというふうに要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"石田委員","kind":"提案","question":"私は３０９ページからの小中一貫校校舎改築について、時間があれば１０分で済んで、２９５ページの教職員研修をちょっとやりたいと思います。再確認をさせていただきたいんですが、台場小学校、荏原第五中学校をスタートといたしまして、伊藤中学校、原小学校までずっと校舎改築を進めてきていると思いますが、このときに予算を提出する際に、教育委員会である一定度の判断をして、それで提案をしていく。","respondent":"市川庶務課長","answer":"１７年度予算につきまして、教育委員会の考えはどうだったのかですけれども、今申し上げた実施計画の審議の段階で、当然のことながら幾つか調整がされるわけですけれども、基本的に教育委員会のほうから申し上げたところについては。","id":"exchange-121"},{"speaker":"石田委員","kind":"確認","question":"そこなんですよね。小中一貫校はもう１点、後で答弁してほしいですが、計画的にある程度いくという我々理解をしておりまして、２校話しが出てきて、そのときに当初４にいくのか５にいくのかという話もありましたが、計画的にというのはどういう計画なのかなと。その裏には公園があり、都営住宅があった。これを一体的に考えるか、あの敷地をどういうふうに考えるか。","respondent":"市川庶務課長、中尾根企画部長","answer":"そういう意味で、これまで耐震診断を実施する中で、小山小学校の改築という新しい事業が出てまいりました。耐震診断を今回予算計上させていただいていますけれども、１７年度にもまだ数校残ってあります。したがいまして、基本的な考え方があって、それに対してその実現に向けてどういうふうにすれば実現できるのか、どうしたら一番いいのか、こういう選択をしていく場は全体の中ですけれども、基本的には。","id":"exchange-122"},{"speaker":"石田委員","kind":"質問","question":"これはお願いをしておきます。もっと事前に、周りを全体を見て、こういう形でこういう案もあるのではないかというのを、最初に手をつけるというのか、それが都市整備なのかどこなのかちょっとわからないけれども、そういう部分と連携をして、全体の周りの状況を把握しながらやっていくという部署があってもいいと思うんだけれども、それに対する考えがあったら教えてください。","respondent":"中尾根企画部長","answer":"それをいつどのように決定していくのか、それから住民の方々もいろんな意見を持っているわけですから、それらについての決定ということについては、十分慎重に進めさせていただきたいということで協議をしているわけで、手順といたしましては。","id":"exchange-123"},{"speaker":"石田委員","kind":"質問","question":"ぜひ、よろしくお願いします。ある中学校の先生が何かいろいろあったみたいで、それで変わった。次の年、隣の中学校に行ったんだよね。そうすると、その先生も非常にかわいそうだなと思ったところがあって、もし品川区から品川区に変わるなら、隣の中学校だとやっぱり先生も不幸だし、子どもも不幸だし、親も不幸だから、もうちょっと遠いところへうまく配置はできないのかなというのをお聞きしたい。","respondent":"中島指導課長","answer":"その具申に基づいて、教育委員会として全体の構想を都教育委員会に内申をするという形になっております。その段階で、今委員のご趣旨の状況は、それぞれの学校の状況を見ながら、総合的に判断できる部分ではないかと考えています。","id":"exchange-124"},{"speaker":"石田委員","kind":"意見","question":"流れはわかっていますし、各学校の先生も頑張っていらっしゃるのは非常にわかっているんだけれども、そういうことがあると、せっかく頑張っているのに要らないところで話だけが大きくなってしまうので、最終的には都にちゃんと言って、区で採用ができるようにしてもらうまで頑張ってもらいたいけれども、今そういう状況であるならば、ちょっとそういう配慮をぜひしていただければなと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"沢田委員","kind":"質問・要望","question":"３０７ページの学校給食費の問題について質問をします。それぞれについてお尋ねしたいと思います。財政効率の問題なんですが、今度の予算に小学校で２,０２７万円、中学校２校で４,００６万円の委託経費を計上しておりますけれども、先日の文教委員会では、委託することによって２４.５％の経費削減になるという数字を示されました。この根拠について、述べていただきたいと思います。","respondent":"谷田部学務課長","answer":"平均的年収をそれぞれ掛けまして給与費が全体で幾ら、それに伴いまして私どもこの予算でご覧いただければ大体１校当たり２,０００万円程度の委託経費でできるというふうに踏んですので、５８校を全校委託した場合の経費と、それから現在の配置している職員の人件費を比較すれば。","id":"exchange-126"},{"speaker":"沢田委員","kind":"質問・要望","question":"正規職員を民間委託してもいるわけですから、何で８５０円出てくるんだ。１,１００ 万円としてもいいかもしれない。その点では、今日は出ないでしょうけれども、長期にわたって民間委託した場合と直営でやった場合にどうなるのかということを、別途文教委員会なりしかるべきところに出していただきたいということを、まず述べておきたいと思います。だって、トイレが必要ならつくればいいじゃないですか。","respondent":"谷田部学務課長","answer":"昭和６０年当時の文部省体育局長名の学校給食業務の運営の合理化について、改めて再度確認して学校給食の効率化に努めろというような指示がありましたので、私どもこのような国の動き、それから高いコスト体質の学校給食を民間に調理委託するというものです。","id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"杉並区の裁判でも、その問題が争われて、裁判所はそのことを認めました。そこで、安全面では民間のほうが優位だと言いましたけれども、それならばある事業者は、中学校の委託予定会社ですけれども、最近ＳＲＳＶ（ノロウイルス）の感染事故を起こしたことはご承知でしょうか。ちょっと、そのことを示してほしいと思います。","respondent":"谷田部学務課長","answer":"私ども、当初戸越台中学校、荏原第五中学校で予定していたある事業者は、社会福祉施設関係での食中毒の件があったということで聞いてあります。その食中毒事件があってすぐ、私どものほうに参りまして、事情の説明と４月からの契約は辞退したいというふうに自主的に申されました。","id":"exchange-128"},{"speaker":"沢田委員","kind":"質問・要望","question":"民間には問題がないし、それは事実を蓄積していると、安全衛生面でも。ずっと優れていると言ってきたけれども、あっという間に１０日ぐらい経ったら、この事故ですよね。私はこの業者に決めるときに、業者がこれまで出してきた営業停止や食中毒をどれだけ調べたか、ちょっと述べていただきたいと思います。","respondent":"谷田部学務課長","answer":"学校給食事業本部ではなくて、社会福祉施設関係のところでそのような事故があったということで、会社としては非常に申し訳ないということで、私どものほうにたまたま４月からの給食調理の業務を請け負うにあたっては、自主的に辞退したいです。","id":"exchange-129"},{"speaker":"沢田委員","kind":"質問","question":"例えば、今年の２月１３日に彦根市の民間企業の研修所で、やはりノロウイルスの集団中毒を断定したと毎日新聞に報じられました。３日間の営業停止です。そこに委託しようとするのは、安全の点検をどのようにしたんでしょうか。例えば、業者選定をするときに、今までのこうした状況を調べたんでしょうか、どうでしょうか。","respondent":"谷田部学務課長","answer":"事業者は自主的に辞退されましたので、これ以上事業者のことは私も控えしますけれども、事業者そのものは全国で２,１７７店、営業展開しているという、それだけの規模を持っているところです。","id":"exchange-130"},{"speaker":"沢田委員","kind":"質問","question":"その点については、至らなかったというべきですよ。私自身が民間出身ですよ。なぜ、民間でこういう事態が出てくるのかということに問題があるんです。この事業者では調理補助員の募集は時給７５０円ですよ。もし、そういうふうに言うのであるならば、民間企業並みの保障をしたらどうですか。その上で、親御さんの意見も聞いて、今後どうするかということを決めるべきだと思いますが、いかがでしょうか。","respondent":"古川教育次長","answer":"私どもは先ほどから申し上げておりますとおり、公立学校における調理業務代行を今後とも推進していく立場ですけれども、このようなことからまた新たな課題なり、新たな教訓を学びながら進めていきたいと、このように考えてあります。","id":"exchange-131"},{"speaker":"塚本委員","kind":"質問","question":"これは公教育の問題ではありません。その大きな仕分け、やっていいこととやっていけないこと、どうしても教育というと自分たちが責任者だ、これもやらなければいけない、あれもやらなければいけないというような考えのもとで、どうにか今までと違ったしつけの仕方をしようということになってきやしないかと思うので、この辺をまず伺いたいと思います。","respondent":"中島指導課長","answer":"その辺で、お互いに役割を改めて認識して、より充実した取り組みにしていけるよう、１８年度からの移行に取り組んでいきたいと考えているところです。","id":"exchange-132"},{"speaker":"塚本委員","kind":"質問","question":"もとは親でしょう。ですから、そこのところに関しては、こういう問題があって、私たちはこの部分だけを担いますからこうします。社会に対しても、ここが問題なんだからこうしてほしいということを、どういうふうに言うか、教育委員会が言うか、何を言うか、また別ですけれども、そういうことを全体像がわかっていながら、自分たちはこの役割を負うんだという覚悟があるかということを聞いているんです。","respondent":"中島指導課長","answer":"今後、各学校が家庭、地域に対して、この市民科の考え方なり、それぞれの役割、そして協力体制について説明をし、実施していく、そういうことが不可欠になってくるものと考えています。","id":"exchange-133"},{"speaker":"塚本委員","kind":"質問・要望","question":"政治もそうです。答えていただきたいと思いますけれども。それから、もう１点、総合学習、学級活動、道徳、こういうようなものを一つにまとめて学科にしようということなんですけれども、道徳というのは子どもにとってお説教の時間だ、総合学習は何だかしまりのないところだったというような感想をみんな持っています。その考え方が教える側にはっきりできているんですか、そっちのほうが問題ですね。","respondent":"中島指導課長","answer":"学校でできる範囲、また内容的に今後またより充実させていく部分というのは多々あろうかと思いますが、市民科だけですべてが完結すると、このように考えているわけでもございません。全教育活動の中で実施、充実していくのは、もちろんそのとおりです。","id":"exchange-134"},{"speaker":"塚本委員","kind":"質問・要望","question":"私の言いたかったのは、前段、社会全体の大きな歪みがここに来て、こういうくくりをすると子どもに大変圧力がかかりますよ、それでいいんですか、視点が違ってやしませんかということを聞いているんですから、お偉い人のお答えを聞きたいと思います。その表れが食を通じての文化の伝承だというふうに、私は思っておりますので、それも含めてお答えをいただければありがたいと思います。","respondent":"若月教育長","answer":"それぞれのご家庭のお父さん、お母さん、こういうことをやっていますから、その方針に沿って、もう１回家庭教育を考えてみてください。社会のいろんな団体で子どもたちを育ててくださる方はいっぱいいらっしゃいます。そういう方々にも、そういうメッセージを送っていきたい。","id":"exchange-135"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは３００ページ以降にあります学校教育費に関連する大きいのか小さいのかわからないんですけれども、その辺のところでお伺いをしたいと思っています。学校管理費に入れるのかどうかもわかりませんので、幼稚園費との関連も含めてお伺いをしたいと思います。だから、この辺をどうするのか、どう考えるのかということを、まずお伺いをしたいと思います。逆の意味で、今の教員は何人いらっしゃるんですか。","respondent":"市岡企画財政課長、中島指導課長","answer":"ただし、じゃ全く我々そういう問題に対して無頓着かということになりますと、決してそうではありませんし、例えば今政策評価に関する外部評価委員会等で、本来の教育のコストというのは。これまで学校における情報教育の推進という立場から、まず子どもたちが授業で使うコンピューター、情報教育のリテラシーをどのように身につけさせていくかという視点での取り組みが進められておりました。","id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"いわゆる国の三位一体の改革等々の問題というやつはあります。ほかのところは総コストになっているんですから。ここだけが総コストになっていないんですから。と同時に、それは先ほどの中でも、どうも品川の先生は都の先生みたいな話も出てきていたので、これは絶対間違いですから訂正しておいてくださいよ。品川にいる先生はみんな品川の先生で、みんな品川の教育をやるために頑張っているんですから。","respondent":"中島指導課長","answer":"この職員証をそれぞれが学校で明示する中で、区の職員であるという認識をつくっていきたいとも考えてあります。ただ、都のほうで任用されている教員という状況はありますので、私どもが服務上の管理監督はいたしますけれども、最終的な任用等に係わって都との関連が出てくる。","id":"exchange-137"},{"speaker":"土井委員","kind":"質問・要望","question":"この辺はいろいろありますけれども、その辺をきちんと管理と実態運用はここでやっているんだという自覚と、品川の先生だ、品川の職員なんだという自覚を教育委員会自身が持っていただいて、そしてまた実際の人も持っていただけるようにしていっていただきたいという思いで申し上げたところであります。何かありましたら、お聞かせくだい。","respondent":"古川教育次長","answer":"予算書の性質上、この中に入ることが極めて厳しいのはわかりますけれども、１,０００名を超える都・県費職員が区職員であったならば、どれだけの経費がそこに投入されているかということについて、私どもも常日頃からとらえて区の教育全体を管理しておりますし。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問・要望","question":"今のお話のように、総コストの考え方も含めて出ているいろいろ議論もされていることですので、ぜひそれがわかるようにしていただきたいということで、お願いを申し上げておきたいというふうに思いますし、また学校ＩＴ化の問題等については、ぜひこれから急速に進めるわけですから、先生方の自己研鑽だけでよろしいということにならないはずですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"堺委員","kind":"質問・要望","question":"３点目が３０３ページにあります校舎等耐震経費、それから３１５ページにあります幼稚園等耐震補強工事、それから３２１ページの文化センターの経費が出ておりますがそれに関連をしてということでお尋ねをします。最初に、適応指導教室運営費に関連をしまして、現在の不登校の実態について教えていただきたいのと、それから適応指導教室の現在の状況につきましてお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"マイスクール八潮、こちらは適応指導教室に参加している子どもの数ですけれども、これ年度の中で入室したり退室したりしている状況がありますが、現在２４名の子どもたちがここに通っているという実態があります。","id":"exchange-140"},{"speaker":"堺委員","kind":"質問・要望","question":"今現在小学生が２９名、中学生が８７名ですか、いろんな事情等でそういう状態になってしまったのかと思います。当日、関係者が相当多く参加したというふうに一部に報道をされております。長期化させないためにも周囲がしっかりと連携し、初期対応を誤らないよう取り組んでいただきたい」、こういうような指摘も当日にされているんですが、その辺についてもご見解をお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"これも委員ご指摘のとおり、大変重要な視点と考えて、実際に連絡会等を実施しています。","id":"exchange-141"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひ、不登校の子どもに対しても、関係機関とよく連携を取りながら、一人ひとり大事な子どもですので、対応をしていっていただきたい、このことをお願いしておきます。それから、さっき申し上げた３２１ページの文化センター経費で、今回大規模改修等施設整備費約 ３,８００万円計上されておりますが、これはどこでどのような工事をされるのか、あわせてお尋ねをしておきます。","respondent":"市川庶務課長、上川内生涯学習課長","answer":"したがいまして、来年度は小中学校７校、それから耐震補強の必要な幼稚園１園を除いた数が、これから工事をする小中学校または幼稚園の数ということでご理解いただければと思います。文化センターの工事ですが、主なものですと五反田文センターでバルコニーの改修工事、荏原文化センターではプールの消毒装置、旗の台文化センターではスポーツ室の屋上の防水工事、大きなものではそういうところです。","id":"exchange-142"},{"speaker":"堺委員","kind":"質問","question":"そうしますと、耐震診断は３カ年の計画を立ててやりました。今度は、その中から必要なのは補強工事ですね。大事なのは補強工事なんです。それから、小中学校では３２校ですから、あと２５校補強工事が必要なところが残っていますね。これはそれぞれあと何年かけて工事をやるんですか、それは計画ができているのかどうか。それはいかがでしょうか。","respondent":"市川庶務課長","answer":"幼稚園につきましては、実施いたしました８園のうち２園については、補強の必要なしという診断結果です。小中学校につきましては、校舎の棟が何棟かございまして、結果的には耐震診断をやったところすべて何らかの補強工事を行うということになってあります。","id":"exchange-143"},{"speaker":"堺委員","kind":"質問","question":"要するに予測しがたい怪物とでもいいましょうか、起きないのが一番いいわけでありますが。極端に言ってしまいますと、３カ年かけないで、今年度中に全部終わらせるんだ、そのぐらいの意気込みの対応していかないと、いつ起きるかわからないというのが地震ですから、その辺の見解を予算もありましょうから、予算担当の方も含めまして、ちょっとご見解をお願いしたいんですが、いかがでございましょうか。","respondent":"市川庶務課長","answer":"耐震補強工事を行うときには、そういった諸工事とうまくタイミングを合わせて実施したいということが一つ。それと、一遍に工事をやりますと、１年中学校が工事づけになってしまって、教育活動に支障を来してしまうという現実もあります。","id":"exchange-144"},{"speaker":"堺委員","kind":"質問","question":"わかりました。そういうことをおっしゃるだろうなと思っておりました。よくわかります。わかるんですが、いつ起きるかわからないのが地震ですから、速やかにという、この前提でよくとらえていただければと考えています。３点目、教員の関係です。もし、そちらのほうに書類がありましたら、要するに品川区の教員の年代別の構成がどうなっているか、教えていただけますか。","respondent":"中島指導課長","answer":"中学校におきましては、４０代前半と４０段後半に大きな山があって、あとはそこから次第に少なくなっているというような状況にあります。全体といたしましては、４０代後半のところがピークとなる形で推移しているという状況があります。","id":"exchange-145"},{"speaker":"堺委員","kind":"意見","question":"このようなことが指摘されております。ここでつかんでいるのは、今年ですと６０歳の定年を迎えた教員が約７,７００人、これから順次増えていくという中で、品川区では４０代後半がピークであるとありましたけれども、今まで大量採用されてきた方が逆に大量の定年退職になってきますから、その辺の対応について十分検討されているだろうと思うんですが、その辺についてお願いします。","respondent":"中島指導課長","answer":"これは本区だけの問題ではなくて、全都的な問題でもありますので、都とも連携を図りながら質のよい教員の確保に努めてまいりたいと考えています。","id":"exchange-146"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひ、新たに採用するときは、質のいい教員を採用していただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"原委員","kind":"質問","question":"一番最後です。お疲れさまでございました。私のほうからは、何にあたるんでしょうか、２９４ページなのか２９７ページなのか、教育指導費か小中一貫につながることになるのか、要するに教育改革についてちょっとお伺いをします。いまだに、まとまりのつかない中での質問になってしまうんですが、このゆとりと学力というところについて、教育委員会はどういうふうにお考えをお持ちなのでしょうか。","respondent":"中島指導課長","answer":"ゆとり教育と言われるところですけれども、完全な週５日制に移行される中で、これまで学習指導要領で示されていた内容を３割減らす、授業日数が２割減っていく中で、それより多く内容を減らすことによって。","id":"exchange-148"},{"speaker":"原委員","kind":"質問","question":"ゆとりということは、結局、余裕を持って時間を取って、そこの中からじゃ何が出てくるかということを図っていたわけです。結局、このゆとりというのは何もしないことではない。例えば、心のゆとりとか時間のゆとりとか、何でもできる時間をつくっていくわけです。そうすると、品川区の中において、学力は小中一貫の中でどういうお考えが基本になって進めようとしていらっしゃるのか、お伺いさせてください。","respondent":"中島指導課長","answer":"もちろん、それはすべて子どもに返っていくということで、私たちも全力で取り組まなければならないと考えているわけですが、子どもたちの小中一貫教育の中で培っていきたい学力とは、基礎的な学力の定着の部分と個性伸長、この二つを大きな柱と考えています。","id":"exchange-149"},{"speaker":"原委員","kind":"質問・要望","question":"まさに、そのとおりだと思います。先ほど、市民科というのが出てきました。私も代表質問の中で市民科についてお伺いをさせていただきましたけれども、先ほど塚本委員からも話しがありましたけれども、もっとこれをしっかりしたものにするには何を考えていらっしゃるのか、ちょっとお伺いさせていただきたいと思います。","respondent":"中島指導課長","answer":"特に、単元としてつくっていく中には、今まで各学校が取り組んできた地域連携ですとか、ゲストティーチャーを呼んで総合的な学習の時間のノウハウがそこでも生かせるような形で、それぞれの学校の年間計画を立てていくように。","id":"exchange-150"},{"speaker":"原委員","kind":"質問・要望","question":"基本的には、市民科の中には、人間としての心とか思いがしっかり入り込んでいなければいけないかと思うんです。先ほどの塚本委員の質問の中にも、そういったところを含めて、これから教育委員会が１８年度に向かって、もっと精査していただいて、しっかりやっていただきたいというところを、教育長、最後にお話しをしていただければありがたいと思います。","respondent":"若月教育長","answer":"あのときの世相はどうだったんでしょうか。そして、私たち大人はあの風潮に対して、果たして私は教師としてどういう対応と主張ができたでしょうか。非常に反省をするところがあります。あの当時は、勉強することがあたかも悪いことのように指摘された。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270732?Template=document&Id=850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":122101,"voices":341}},{"id":"h17-20050318-11","meetingId":"h17-cm03","date":"2005年3月18日","dateIso":"2005-03-18","committee":"自治制度特別委員会","time":"午後２時０３分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","topics":[{"id":"topic-01","title":"附帯決議（案）","agenda":"附帯決議（案）","exchanges":[{"speaker":"南委員","kind":"意見","question":"大した修正じゃないんですけれども、１番の３行目の左端から、「実現が急務である」となっているんです、そしてまた別な文になっています。ここのところを、句点を打たずにつなげたらどうかなと思っているんです。個々には、言葉の表現だとかはありますけれども、基本的にはいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"今のお話ですけれども、これは人事の問題と厚生の問題が入ってくるので、厚生のほうは、この前いろいろお話を聞いて、ああだこうだと入り組んで、組織のあり方や肥大化防止についてというような表現を、あえて厚生のほうとして入れてきたと思うんです。ですから、そこはまた分けておかないと、つなげちゃうと、何が何だかわからなくなっちゃうという流れ方になるんじゃないかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"高星委員","kind":"意見","question":"私も、文言とか何かというんだったら、全くないわけではないわけですよ、言いたいこともあるけれども、うちの会派からも副委員長を出しているし、この間、ものすごく精力的に検討されたということを聞いていますけれども、私もそうだと思います。この調整の件に幾ら時間をかけているんだ。そうでなくて、ぐずぐず言うんだったら、私だってほかのところでまた言いたいところはあるから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"藤田委員","kind":"提案","question":"正副委員長がまとめられた文面でいいと思います。要するに意味合いがまた違うんですよね、上の文章と下の文章で、一つは人事行政の実現ということと、もう一つは組織の肥大化ということで分かれているんじゃないかと考えていますので、提案のとおりでいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"今の文章のことは、それでいいと思うんですが、正副委員長でいろいろまとめられたことでありますので、あまり異議を申し上げるわけでも何でもないんですが、ただ、その審議をもう一度お聞かせいただきたいのは、３番目、この協議会の事務について、「各特別区が直接処理する方向で、解散を含めて検討するべきである」と。その辺のところを、ちょっとお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本田委員","kind":"意見","question":"自治権確立という大きな観点から言えば、非常に重要な指摘ではありますので、その辺、ぎくしゃくしないような配慮をしながら、こういう文章をつくった、表現をしたということであれば、正副委員長のところで、それぞれ違ったお立場の正副委員長が、これをされというのであれば、それは了解します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須藤委員","kind":"意見","question":"今、皆さん、これでいいと言っているんだから、若干の文言整理も何もないと思うんです。直されちゃったら、逆に我々がおかしくなっちゃう。今、皆さん、これで結構ですというご意見なんで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"多分、私のさっきの発言に対しての発言だと思うんですけれども、さっきもちょっと申し上げましたけれども、基本的には賛成です。さっき、発言したのは、変更が可能であれば、そういうふうに変えてもらいたいということですから、皆さんがこれでよしということであれば、私たちは別に否定するものではありませんし、一緒に賛成もしていきたいと思っていますので、ぜひ、誤解なきようによろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612109?Template=document&Id=5564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":5170,"voices":20}},{"id":"h17-20050322-3","meetingId":"h17-c-budget","date":"2005年3月22日","dateIso":"2005-03-22","committee":"予算特別委員会","time":"午前１０時０４分～午後９時０４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を140件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"おはようあります。自民党品川区議団を代表いたしまして、総括質疑を行います。林宏委員と２人でやります。どうぞよろしくお願いいたします。財政調整をめぐる未完の都区制度改革についてお伺いをいたします。主要５課題、都から提出された大都市事務の内容と主張の違いが多数あると思いますが、改めてお知らせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"それらを含めて、東京都には区側の分析では１兆２,０００億円という都の提示に対して６,７００億円程度、これが区として認められる都が行う大都市事務の内容である。これから検討するものも含めても８,４００億円弱が最大のところである、こういう反論を行いました。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"法人住民税というのは、都税でなくて上がっていると、そういう答弁がそっと出てくるわけでして、これはこのまま協議をしていても平行線で、平成１２年のころと同じことになってしまうんじゃないかなと思いますが、こういう答弁が今あって、それを受けて、今現在どのようにお考えになっているか、そのお考え方、感想等をお聞かせ願いたいと思います。","respondent":"高橋区長","answer":"この内容の問題を申し上げますと、いろいろと論議がありますけれども、東京都が２３区の問題に対して、どれだけ真剣に取り組んでいるか、これが私は一番重要ではないかと考えています。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"非常に今のところが大切なところだと考えています。もう一段そこでお聞きをしたいのは、今、都議会も第１回定例会が終わろうとしております。ここら辺の議論を、今言いましたさまざまな５課題の落としどころの部分の解決策の中で、そういう議論が出てきたときに、そこら辺の幅広い議論まで入りこんでやろうとされているのか、いないのか、そこら辺の３つの点をお聞かせ願いたいと思います。","respondent":"高橋区長","answer":"１つは、先ほど申し上げました水平調整を区ができるかできないか。東京都がそれを放すか放さないか。私はこれが一番大きな問題じゃないかなというふうに思っております。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"もう一段、最後にこの部分ではまだ見えないところもありますからお聞きをしたい。今おっしゃった６,７１３億円と最大で約８,３８０億円だというのを提出された。これが例えば今言ったポイントというかパーセントのもので５２をどうしていくか。こういう形の中でいくと、その相差の部分の１０％部分ぐらいは、都にそのままお墨つきを与えてしまうことにもなりかねないわけですよ。","respondent":"高橋区長","answer":"ただし、先ほど申し上げました水平調整の問題、金額を詰めるよりか私は難しいんじゃないかなという思いがしているわけですけれども、これもやはりかち取らなければ、ほんとうの財政調整、また２３区のほんとうの独立は私はないかと。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"今おっしゃったように５月までで任期が終わりだ、副会長という立場でありますから、ぜひそれまでに道筋をつけていただいて、その後は、そういう役職は外れるわけでありますから、品川区長として品川区の代表として、がんがん区長会で言っていただいて、この問題は、水平調整の部分でも結構でありますが、これはしっかりその部分の議論をしていただきませんと。","respondent":"山田区民生活事業部長","answer":"特に自分のまちは自分たちで守るということをスローガンにいたしまして、町会や自治会、消防団などの皆さんの連携のもとに地区防災訓練の充実、また災害要援護者へのワークショップ等、体験を通じてリアルな対応力を身につけていただくというところで実施をしています。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"今のお話の中で、いろいろなさまざまな先進の大地震の学ぶべき教訓として、これはもう地震防災力という中では、１つは被害抑止力であるよと。そこをどういうふうにとらえていくかという観点から質問をしていきますが、その対策として今耐震診断、耐震改修を行っている。ここら辺の部分は何が原因で、どのような形で進んでいないかと思われているかというところを教えていただきたい。","respondent":"中谷まちづくり事業部長","answer":"いずれにいたしましても、区では来年度耐震助成につきましての融資あっせんを行うということを予定しておりますので、このＰＲを今後行っていく予定ですが、この中で、今年耐震診断をされた方についてもアンケート調査を実施して、ここら辺について区としての分析を行い、そして。","id":"exchange-006"},{"speaker":"石田委員","kind":"意見","question":"そのお考えはわかります。だけれども、今の既存不適格住宅の耐震化は、１つの命や文化財など代替えのきかないものを守るには、ハード対策しかないということでこれが行われているんだと私は思っております。そういう意味合いの中の部分の考え方というのかな、先ほどの感じはわかったけれども、今みたいな自助を誘発する考え方、そこら辺のところを突っ込んで、もう一段お考えがあれば、お聞かせ願いたい。","respondent":"中谷まちづくり事業部長","answer":"そういう意味では、今年度の耐震診断から来年度の融資あっせんに結びつけて、そしてこれを誘発として、区民の皆さんの意識づけ、動機づけを行い、そして他の例えば密集事業ですとか防災生活圏の事業ですとか、これは再開発等もそうですが。","id":"exchange-007"},{"speaker":"石田委員","kind":"提案","question":"指導をする。耐震改修を実施した人、これは区が認定するわけですから、この実施した人を対象に、例えば共済制度とか行政によるインセンティブ制度、こういうものを創設するべきだろうと私は思っております。財源はどうするか。ああいう安易なリフォームを抑制することにもなりますし、こういうことはしっかり訴えていくべきだと私は思っておりますが、そこら辺の点についてのお考えをお聞かせください。","respondent":"中谷まちづくり事業部長","answer":"あるいは全都的なレベルとして受けとめていただく、そういうことが肝要で、いわゆる役割分担を的確に行っていくということがこの事業の推進に役立つものというふうに認識しております。","id":"exchange-008"},{"speaker":"石田委員","kind":"意見","question":"先ほどの都区制度でも言いました。だから、その保証枠でも例えば５０億円ぐらい積めば一歩前に出られるなという試算もしました。そのために言っているわけであります。そこの部分を都だ、区だ、国だ、そこでやっているからといって、じゃあ時間をずっとこういうふうに待っているということがいいことなのかというところを言っているわけでありまして、その点についてのお考えをもう１回お聞かせ願いたい。","respondent":"中谷まちづくり事業部長、高橋区長","answer":"そういう意味では、品川区から発信できるところについてはきちんと発信するということで来年度の耐震改修の融資あっせんにつきましても、区としては。そうすると、区の問題としてこれをどこまでやっていけるか、それはこれからの検討に値するものではないかと考えています。参考までに、今地震保険はかなり掛け金が高いわりに保証が少ないわけです。","id":"exchange-009"},{"speaker":"石田委員","kind":"意見","question":"今のお話、突破口のお話をします。これは、我々、私議員として自戒も込めてお話をしたいと思いますが、こういうふうに話せるということは、私自身も地震防災対策に直接関与できる立場にあった者として、努力して、励んで、結果として社会を守ることができたのか。ここは非常に自分の部分もありますが、これを言っていいのかどうかわかりませんが、政治家は票を持つ生き残った人に最大限気を使う。","respondent":"高橋区長","answer":"先ほど申し上げましたように、この問題につきまして早急に検討に入らさせていただきたいと考えています。その検討の結果、また議会のほうにご報告させていただきたいと思います。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"例えば区民保養所の顧客管理、区立の小中学校、幼稚園、保育園などの名簿、あるいは特別養護老人ホーム、グループホーム等高齢者サービスの利用者の名簿、あるいはスポーツ協会を通じての利用者団体等の名簿、それから区民住宅等、家賃収納のため受納者、請け負っている業者が管理している名簿、始まりましたコンビニでの収納のときの納付伝票というんですか、そういうもの等々。","respondent":"山田区民生活事業部長、古川教育次長、新美福祉高齢事業部長、小沼児童保健事業部長、中谷まちづくり事業部長","answer":"私のほうから区民保養所とコンビニ収納に関しましてご説明します。特に電子ベースの管理というのは非常に難しい側面がございまして。ホームヘルプ等あるいはグループホーム等を運営している民間事業者につきましては。これは、保育室の前で自主記入していただきまして、一定期間経過後、シュレッダー処理、基本的にはそういう形で対応しています。あるいは電子データにつきましてはパスワードを二重にしまして、そして担当者以外の閲覧を禁止しておりますし。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"どうしても明日の朝までにはやらなきゃいけないというと、自宅へ持ち帰るという可能性もあるわけで、そのときによくニュースなんかで答案用紙を電車に忘れたとか、そういうようなことも時々聞くわけですけれども、そういうところまでの指導徹底もしていかなきゃいけないというふうに思いますし、あるいは名簿管理ですから、名簿が渡された人は、どこでどういうふうに使うかわからないという部分がある。","respondent":"中尾根企画部長","answer":"ただ、今まではそういったことがややもするとノーチェックになっていてルーズになっていたという部分がありますが、今後は要するに高度情報化の社会の中で、今までのデータというのは紙に見えるデータでしたけれども、目に見えない中での取り引きされる。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"区の職員の人に徹底する部分は非常に伝わりやすいんですけれども、それの外側ということになるとなかなか難しい、その辺もどういう方法があるのか検討を加えていただきたい。いわゆる名簿を売っているようなことでありまして、公開しなければいけない法の精神というのを一度お聞きしたいと思っていましたので、この際、お聞かせください。","respondent":"中尾根企画部長、山田区民生活事業部長","answer":"純粋な民間の場合は、今回の個人情報保護法そのものについては４月から全面実施されるわけですけれども、データを５,０００以上件数を持つことについては、品川区と言ってみれば同じように責務を負わされて罰則も適用される。特に４情報については個人の秘密に属する事項を含まれていないという解釈のもとに実施がされているというところです。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"聞いている意味が違うんですよ。今、個人情報はしっかり守らなきゃいけないというふうになってきたのに、なぜ行政として持っている個人情報、基本的な情報ですよね。住所・氏名・生年月日。それを見せなければいけないという逆の法になっているわけで、その精神は何ですかというふうにお聞きしたんで、その辺を、ちょっと一問一答みたいになりますけれども、もう一度お願いします。","respondent":"山田区民生活事業部長","answer":"いわゆる４情報、住所・氏名・生年月日・性別に関しては、国の見解では、これは確かに個人の情報ではあるけれども、秘密に属さないというところでの解釈のもとに。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、一般的な名簿はそんなようなものじゃないですか。ただ、１つお聞きしておきたいのは、平成１７年度の予算から消えた緊急地域雇用対策費というもの、これは区の全額の補助金でやっていたんですけれども、６年間続けてきたのかなというふうに記憶しておりますけれども、評価はどういうふうにされていたのか、単に財源が来たからやったということでは済まされないのかなと。","respondent":"山田区民生活事業部長、中尾根企画部長","answer":"は保健所等の病歴などが入っているデータとしてあるというときには、いわゆる秘密が含まれているというふうな解釈のもとに名簿というような意味合いと変わってくるかというふうに考えてあります。１次、２次の継続になりました。この６年間のトータルとしまして、品川区では全部で３８事業ですね、３８の事業に当てはめておりまして、延べ人数としては約２,５００人雇用しております。全部新規です。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"確かに２,５００人ということで効果も出たというふうに私たちも認識を持っていますけれども、品川区では事務事業評価をしているわけですけれども、これについては、事務事業評価という点ではされていないんでしょうか。１年こっきりだからもういいやという、あるいは短期のお金が来るからいいやということになるのかどうか。","respondent":"中尾根企画部長","answer":"事業の継続のほうを先ですけれども、これまでの事業の中で、毎年度予算査定等の中で、この適用している事業についての評価を行い、継続すべきかどうかということを一つ一つの事業についてずっと行ってまいりました。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"提案","question":"１つ提案なんですけれども、昔、政府がやった都道府県ごと、市町村ごとに１億円を出して何でも好きなことをやりなさいというようなのもあったし、千代田区では各町会あてに１,０００万円出してプランを立ててくださいという、この緊急地域雇用対策をちょっともじって、品川版で各事業部あるいは課に例えば金額は１億円なのか５,０００万円なのかわかりませんけれども、プランを出してみなさい。","respondent":"中尾根企画部長、山田区民生活事業部長","answer":"今後については、この事業そのものがなくなりますので、また新しい方策なりそういうものを精神はそのまま継続しながら方法を考えていきたい、このように考えてあります。いわゆる新製品、新技術の助成の企業に関しては発表会ということで、年１回ではありますけれども、ちょっと前にはものづくり自慢大会という名称でやってございましたけれども、そんなふうな発表会なども自主的に実施をしています。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"提案","question":"そこで１つ提案なんですけれども、各地で行われている全国規模のもありますし、市町村といいますか、市、区で行われている産業見本市というのがあります。品川区へ人が来るという意味も含め、あるいは商取引の活発化あるいは情報交換というようなことも含めて産業見本市というようなこともお考えいただければと思いますけれども、見通しを聞かせてください。いきなりでは難しいかと思います。","respondent":"山田区民生活事業部長","answer":"基本的には、それぞれの企業の皆さん方の自立性と、またそうしたものをやっていこうという機運がなければ、これはなかなか成功しないものですので、これから関係の機関の皆さん方のご意見もいただきながら、実現が可能かどうか研究してまいりたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"意見","question":"そんなところで、電気の問題、ガスの問題、水道の問題、さまざま家庭でも数字をつかみやすいということから品川版京都議定書、１年間の努力目標でここまで皆さん協力をして品川区らしい京都議定書推進の一端を担いましょうというようなことを進めていただいて、できればその目標を達成した人には今騒がれている環境税導入ではなくて、環境減税というようなものを品川区で打ち出せればと思いますけれども。","respondent":"岩崎環境清掃事業部長","answer":"地域版のＣＯ２を初めとする温暖化ガスを削減する、そういう地域計画というようなものは、これから多分義務づけられてくるんではないかというふうに考えております。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それからもう一つは生涯学習ということを確認をしていきたいと思いますけれども、建築費用が今、７校、８校進んでいるわけですけれども、どのぐらいかかっているのか、それで、その費用の中身なんですけれども、もちろん国から来たお金もあるでしょうし、将来に向けての起債を発行した部分、それから一般財源で負担している部分、その辺の細かいところまでお知らせをいただきたいと思います。","respondent":"古川教育次長","answer":"こういう中で、８校のそれぞれの必要性を勘案しながら、教育委員会としましても財政上の問題をクリアしながら、それぞれ必要な改築を進めている、こういうところです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"大変な金額で、これで終わりじゃないんですね。これから始まるわけです。品川区は５８校小中合わせてあるわけですけれども、すべての学校がこれは年次的といいますか、時系的といいますか、年数が来れば建てかえなければいけないということで、これから１０年、１５年あるいは２０年というスパンでこの金額が出ていかねばならない、使っていかなければならない。どうぞ財源の見通しについて聞かせてください。","respondent":"市岡企画財政課長","answer":"それで、今基金は１２５億円ありまして、数年先までは、これは実施計画は３年単位ですが、もう少し先まで私どもはきちんと財政計画上の裏打ちをしております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"生涯学習ということで伺います。品川区の教育委員会事務局の組織ですけれども、生涯学習課というのがあるんですけれども、教育長、次長、庶務課、学務課、指導課、生涯学習課、図書館とありますけれども、生涯学習課と学校教育というかかわりを教えてください。","respondent":"古川教育次長","answer":"今回、学校図書館あるいは区立図書館というものを連携しながら、さらなる子どもの学習のための仕組みづくりをしようとしていますけれども、教育委員会における新たな１つの挑戦というふうに私自身は考えてあります。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"生涯学習の考え方なんですけれども、人間、人の一生の中で、保育園、幼稚園、それから義務教育の６年、３年の小中学校、それから高校、大学、それから社会へ出てからのリカレント、あるいは品川でやっているシルバー大学、さまざまなところで学んでいくことによって生きがいを見つけるという、あるいは小中学校の場合は生きる力をつけてということになっているわけですけれども、教育委員会。","respondent":"若月教育長","answer":"そういった意味で、これからの生涯学習といったようなものは、学校教育の充実を含めて、それをさらに充実させるということは国を挙げての課題であると、教育委員会といたしましても認識をしています。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"誤解を生じると困りますけれども、学校教育はやはり一番重要な課題とは思います。教育委員会にとって。ぜひ生涯学習ということを力を入れていっていただければありがたいと思います。金曜日に行われた中学校の卒業式で高橋区長の祝辞をお聞きしました。ぜひ職員の方々、この中学生のメッセージを職員という立場でお受けとめいただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"質疑に移ります。この法律は、国および地方公共団体の責務として、発達障害の早期発見や支援などについて必要な措置を講じるよう定められておりますが、この発達障害という言葉、区民の方にとってはなかなかなじみのない聞きなれない言葉ではないかというふうに思いますので、そもそもこの発達障害とはどういうものなのかということについて、まずお伺いをしたいと思います。","respondent":"新美福祉高齢事業部長","answer":"このたびの法律制定の背景につきましては、発達障害者を取り巻く現状が挙げられるかと思います。第１に、発達障害は人口に占める割合は高いにもかかわらず、法制度もなく制度の谷間になっており、従来の施策では十分な対応がなされていないということが１つです。","id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"そこで、具体的な支援について次にお尋ねをしたいと思います。初めに、発達障害の早期発見についての取り組みですが、発達障害は早期発見、早期療育が非常に重要だというふうに言われておりますが、その理由について、お伺いをしたいと思います。","respondent":"新美福祉高齢事業部長","answer":"幼児期から適切な対応があれば、障害が個性レベルにどとまりまして能力を発揮することも可能となるというふうに２次障害の深刻化を防ぐことができるという点が重要な理由というふうに認識をしております。","id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"今ご答弁いただきましたとおり、早期に発見できた場合には、非常に中には治る方もいらっしゃる、そうした中で発見がおくれますと、今ご指摘いただいた２次的な問題、親の無理解による虐待とか、またいじめや不登校、非行、こうしたものに発展するおそれがあるということで、早期発見、早期療育が大事である、このように理解をいたしましたが、そこで早期発見のための。","respondent":"伊藤品川区保健センター所長","answer":"就学時の健診を初めといたしまして、学校保健法に基づく健診を実施しておりますが、その場面でも学校医が発達障害を疑うような場合には、適切に小児神経科医などと連携をしてといいますか、そちらのほうにおつなげをしてというふうなことを行っております。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"今後早期発見をさらにしていく上での取り組みについてはどのようにお考えになっているのか、あわせてお伺いしたいと思います。","respondent":"伊藤品川区保健センター所長","answer":"今後、早期発見に向けてどのように取り組むかということですけれども、発達障害児の多くは親御さんが子育ての最中で、なかなか育てにくいお子さんだという印象をお持ちのことが多いですし、それから、幼稚園ですとか保育園ですとかに入られますと。","id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"今、３歳児健診の後にも対応していきたいというお話もありましたけれども、いずれにしても、この全国で２００名ぐらいしか実際にこの正式に発達障害を診断できるお医者さんというのはいないというふうにも聞いておりますけれども、ぜひそうした中で取り組みを強めていただきたいと思いますが、ところで専門家によりますと、３歳くらいの、先ほどあった３歳児健診ぐらいの低年齢では。","respondent":"伊藤品川区保健センター所長","answer":"それで、５歳児健診が有効であるということが、有効性が確立されたらどうするかというふうなご質問ですけれども、５歳児健診の有効性、それから発見をした後の訓練の手法、この辺が確立をされましたらば、療養支援体制を組み立てながら、構築しながらということではありますが。","id":"exchange-029"},{"speaker":"武内委員","kind":"確認","question":"今の段階で、まだなかなか有効性というのは確認されていないと考えていますが、ぜひそうした先駆的に取り組んでいる自治体の情報も積極的に取り入れていただいて、効果的な早期発見に向けての健診体制をお願いしたいと思います。そうした意味で、この親への理解もどのようにしていくのか、お考えをお伺いしたいと思います。","respondent":"伊藤品川区保健センター所長","answer":"区の職員への研修等ということですけれども、確かにおっしゃられますように、区の職員がこの障害に対しての正しい認識を持つということは大変に欠かせないと考えています。","id":"exchange-030"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひお願いしたいと思いますが、世田谷に自閉症・発達障害者支援センター、トスカというのがあるそうですが、これは東京都で１つなんですけれども、区市町村からの個別の研修の要望にも対応しているということで、また平成１７年度からこの法の施行によって保健師など関係者に専門的な研修も計画していると聞いておりますので、ぜひその辺のところを大いに活用していただければと思います。","respondent":"伊藤品川区保健センター所長","answer":"東京都の自閉症・発達障害者支援センターについてのご質問ですけれども、世田谷区の、平成１５年の１月に発足をいたしまして４人の職員で取り組んでおられるということですけれども、既にかなりマンパワー的にといいますか、きつい状況があるというふうに伺っておりますので。","id":"exchange-031"},{"speaker":"武内委員","kind":"質問・要望","question":"ちょっと国の発達障害者支援体制整備事業、これに対してのご答弁がなかったので、後であればお願いしたいのと、それから次には、特別支援教育ですね、これとの連携についてお尋ねをいたしたいと思いますが、文部科学省がモデル実施していまして、特別支援教育については我が党の同僚議員も何度かご質問、ご要望してまいりましたが、本区における特別支援教育の現状の取り組み。","respondent":"伊藤品川区保健センター所長、古川教育次長","answer":"漏らしましたので、発達障害者支援体制整備事業との関連ですけれども、これは都道府県とか指定都市に発達障害の検討委員会を設置するということ、それから障害保健福祉圏域において支援の体制整備をモデル的に実施するということで。来年度に向けての１つのこれからの取り組みですけれども、この検討委員会のもとに巡回相談チームを編成いたしまして、いわゆる通常の学級に在籍されるＬＤ、ＡＤＨＤ。","id":"exchange-032"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひスムーズな連携を所管が違ってくると思いますので、お願いしたいと思います。東京都に対しても就労支援体制の整備を積極的に働きかけていただきたいと思いますが、それぞれあわせてご所見をお伺いします。","respondent":"新美福祉高齢事業部長","answer":"就労支援についてのお尋ねですが、今回の発達障害者支援法の成立、施行を踏まえまして、学校教育、あるいはハローワーク等と連携を図りつつ、どのような支援ができるか、対応を十分検討していく必要があると考えております。","id":"exchange-033"},{"speaker":"武内委員","kind":"質問・要望","question":"区では今後、区民に対してどのような意識の啓発をお考えなのか、お伺いをいたします。あわせて民間団体への支援につきましては、昨年の第３回定例会での同僚議員の一般質問の際にもご要望させていただきましたが、改めまして、こうした民間の自主グループに対して積極的な連携を図りつつ、ニーズに応じた適切な支援を要望いたしますが、ご所見をお伺いいたします。","respondent":"新美福祉高齢事業部長","answer":"お尋ねの発達障害につきましての正しい理解の促進は、今後進めていく支援体制の整備に当たって不可欠の課題というふうに認識しております。今後、児童保健事業部あるいは教育委員会等関係部門と十分協議をいたしまして、適切な区民啓発に取り組んでまいりたいと存じます。","id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、先日ＮＨＫで３０分の特番で発達障害をやっておりまして、その中の親御さんの言葉が非常に印象に残っております。次の質問に移らします。子どもの目線からの安全対策について、お伺いをいたします。ぜひこのような死角をなくすために、子どもの目線を意識しながらこれからも安全対策に取り組んでいただきたいというふうに思いますが、このことについて、まずご所見をお伺いしたいと思います。","respondent":"古川教育次長","answer":"子どもそして保護者、さまざまな方々のご意見等をいただきながら、まずは子どもが生活する場である、学ぶ場である、こういう観点から学校における安全対策を今までも考えてきておりますし、これからもそういう視点で取り組んでまいりたい、このように考えております。","id":"exchange-035"},{"speaker":"武内委員","kind":"質問・要望","question":"今取り上げました子どもの目線というのは、子どもだけでなく、子どもに象徴されるような社会的に弱い立場の方々、例えば高齢者や障害者など、こうした方々の目線にも通じると考えております。どうかそうした方々と同じ目線、同じ立場に立って、今後ともさまざまな施策を行っていただきたい、このように要望しますが、改めましていかがでございましょうか。","respondent":"古川教育次長","answer":"それぞれ相手の立場に立って施策を組み立て、そして展開していく、これは基本であろう、こういうふうに考えております。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"昨今子どもを巻き込んださまざまな事件が起きておりますが、特に寝屋川市の事件は非常に衝撃をもたらしまして、勇敢な教職員のおかげで生徒の直接的な被害がなかったことは救いであったと思いますが、改めて子どもと学校の安全対策について適切な見直しが必要ではないかというふうに感じておりますが、このことについてのご所見をお伺いしたいのと、また先日寝屋川市の事件の後に。","respondent":"古川教育次長","answer":"これは各学校での実情を踏まえた施錠のとり方、それと来場者に対する声かけ、これは当然のことでありますけれども、今回のように卒業生という中での極めて特定な事件とは思いますけれども、見知らぬ方との応対については必ず複数での対応を心がける。","id":"exchange-037"},{"speaker":"武内委員","kind":"提案","question":"私ども公明党も党を挙げてこれまでさまざまな視点から子どもの安全対策について人的配備も含めたいろいろな提案をしてまいりました。その結果、平成１７年度の文部科学省の予算には、地域ぐるみの学校安全体制整備推進事業が盛り込まれておりますが、実施をする予定と聞いておりますが、この事業の内容について簡単にお知らせください。","respondent":"古川教育次長","answer":"これらのことをモデル地域を指定しながら、実践的な取り組みにつなげていく。こういうことを通しながら学校安全ボランティアを安全かつ効果的に活用し、学校安全の体制の整備を推進する、これが文部科学省が平成１７年度に予定している事業の概要です。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"非常にいい事業だと思うんですが、都道府県、政令指定都市ということなんですが、その中で、このスクールガード、それからスクールガードリーダーですね、これの派遣の見通し、この辺のところがもしわかればお教えいただきたいのと、先ほど今出なかったんですが、モデル地域を指定して実施をするというふうにも聞いているので、そのモデル地域に手を挙げることができるのかどうか。","respondent":"古川教育次長","answer":"したがいまして、スクールガードあるいはスクールガードリーダーというものの派遣の見通しでありますとか、さらには東京都下でどういう形でこの事業の推進を東京都自体が考え、それに対して区市町村がどのように手を挙げていくのか、これにつきましては。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"ぜひ積極的に手を挙げてもらえればと思います。ところで、現在本区では通学路の安全のために４２カ所で交通指導の委託を実施しておりますが、どのような内容なのかというのと、また事務事業評価でＣとなっている、この辺の理由についてお伺いをいたします。","respondent":"古川教育次長","answer":"この見直しにつきましては、交通指導あるいは交通安全そのものの必要性がかわったわけではございませんけれども、委託している中での一定の指導員の資質の確保でありますとか、あるいはこの業務内容について目的での効果がどの辺にあるのか、こういった観点から。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問・要望","question":"検討の中で、これらの方々を先ほどのスクールガードと同じような位置づけで校門の前で警備やまた学校内の巡回、これらを含めた安全対策への活用も視野に入れて検討すべきというふうに要望しますが、理事者のご所見をお伺いいたします。","respondent":"古川教育次長","answer":"これは品川区が現在抱えております各学校における実態をとらえ、そして利用されている児童・生徒は当然でありますけれども、保護者、地域の方々のご意見等を踏まえながら、さらなる検討をしていく必要があるだろう、このように考えてあります。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"先日、代表質問で、我が党の三上議員のほうからもスクールガードについては要望させていただきましたが、私たち公明党も今年の２月に児童等の安全確保のためのスクールガードの配置を盛り込んだ安心、安全のまちづくりを求める署名、これは地域の方々の協力において実施をいたしまして、大勢の方の思いを要望書として２月２８日には東京都知事とまた高橋区長にもお届けをさせていただきました。","respondent":"古川教育次長","answer":"私ども教育委員会、そして学校がまずは一体となり、さらには保護者、地域の方々の協力をいただきながら、学校における安全、安心の環境づくりをこれからも一層推進していきたい、このように考えてあります。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問・要望","question":"子どもは社会を映す鏡であります。子どもが危険にさらされているということは、私たちの地域や社会が危険にさらされていると言っても過言ではないと思います。ぜひ子どもの目線からの安全対策を重ねて強く要望し、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"山路委員","kind":"提案","question":"第１に、私どもはこれまで本会議等で環境対策について、平成元年には自治体レベルでの地球環境保全問題、平成２年にはごみ問題や資源リサイクルの促進、低公害車の導入、みどりの創造、保全、生け垣助成、屋上緑化の助成等を初めとしてさまざまな提案を含め、質問をしてまいりました。そこで質問の第１点目は、この新規事業の内容について、具体的にご説明をいただきたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"環境情報活動センターの内容ですけれども、これは以前から私どもが進めておりました推進会議という区民を含めた環境活動を実施している会議がございまして、この中から中心になっている方々を中心にＮＰＯをつくってもっと活動しようというような声が上がってきましたので。","id":"exchange-044"},{"speaker":"山路委員","kind":"質問","question":"今回のこのセンターは第２庁舎の３階に設置されると先ほど説明がありましたが、同じ庁舎にある防災センターは利用が少ないということと、施設の安全確保の視点から土日は現在閉館されておりますが、この環境情報活動センターの開館にあわせて利用者の利便に供するため、土日を開館すべきだと考えますけれども、それについてはどのようにお考えでしょうか、お伺いいたします。","respondent":"岩崎環境清掃事業部長","answer":"ただいま申し上げましたように、区民が活動するということで仕事をお持ちの方が活動するわけですので、土日が主な活動時間になるというふうに想定もできます。そういう意味で、土日を極力あけておけるような体制をつくっておきたいというふうに考えております。","id":"exchange-045"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひその方向でお願いをいたします。あわせて、現在は防災意識も非常に高まってきておりますので、以前は利用者が少ないということで閉鎖されておりますけれども、防災センターの土日の開館もご検討していただきたいと思っているんですが、この辺については今後どのようになるのか、お聞かせをいただきたいと思います。","respondent":"山田区民生活事業部長","answer":"防災センターの土日のオープンにしてはですけれども、これは一時期大変来館者が多いということであえて土日をあけてということで実施をしてまいりましたが、一定の時期から大変人数が落ちてまいりまして。","id":"exchange-046"},{"speaker":"山路委員","kind":"質問","question":"ぜひよろしくお願いいたします。２つ目は環境情報の収集、発信についてであります。この環境情報活動センターで収集した情報を発信するとなっておりますけれども、この情報はどのように収集されて、どのような形で発信されるのか、お伺いをいたします。","respondent":"岩崎環境清掃事業部長","answer":"そういうものをさらにまとめて発信するというようなこともやっていきたいというようなことです。それから最後に、他のＮＰＯや財団などがいろいろと環境活動をしておりますが、そういう取り組みなどの紹介なども発信していきたいというふうに考えているところです。","id":"exchange-047"},{"speaker":"山路委員","kind":"質問・要望","question":"品川区グリーン化支援事業の概要を読ませていただきますと、環境・省エネの出前サービス募集となっているところがあるんですが、今環境清掃事業部長が説明されたような内容で行かれると思うんですけれども、この募集というのはうちに来ていただきたいとか、それとも特定のそういうものを選んでいかれるとか、どのようにお考えでいらっしゃるのか、お聞かせいただきたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"そういうことをやれる人をまず脇にそろえておいて、こういうことができますよと発信しますと、じゃあ来てくださいというふうに応募してくるというようなイメージで考えているものです。","id":"exchange-048"},{"speaker":"山路委員","kind":"質問・要望","question":"３つ目は、環境学習講座、環境啓発事業の開催について、具体的にはどのような取り組みを考えていらっしゃるのか、お伺いしたいと思います。例えば小中学校の児童・生徒が学校の環境教育の中でインターネット等を利用して活用できるように学習講座と結ぶことなどが可能なようにすべきと思いますけれども、その辺も含めてどのような展開をされるのかお聞かせをいただきたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"具体的に教室を進めていく中で、こういう情報発信についても考えていきたいと考えております。","id":"exchange-049"},{"speaker":"山路委員","kind":"質問・要望","question":"４つ目は人材の育成についてお伺いいたします。私どもは、これまで環境カレッジを開設し、さまざまなカリキュラムを検討して環境対策に取り組む人づくりに力を入れてもらいたいことを要望してまいりました。このセンターを大いに活用して人材を育成していただきたいと思いますが、人づくりについてどのように取り組んでいくのか、お考えをお聞かせいただきたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"そういう意味で、インキュベーターというような孵化器という役割を推進会議が果たしていただければ、どんどん人は活動センターを中心に集まってくるかなと、こういうふうに願っているものです。","id":"exchange-050"},{"speaker":"山路委員","kind":"質問","question":"５つ目は中小企業グリーン化支援についてでありますが、大企業が省エネ化に取り組んでいる中、区内中小零細事業者の環境負荷軽減や省エネの取り組み支援、また環境ビジネスの振興を図るとしていますが、具体的にはどういうメリットや効果を挙げられる手段があるのか、お伺いいたします。","respondent":"岩崎環境清掃事業部長","answer":"たまたま、私どもがそういうふうに考えていたところに、同じようなことができないだろうかという提案が今委員ご指摘のＮＰＯのまだ準備会ですけれども、のほうからお話がありまして、今着々とまずは供給側の企業をリストアップするという作業を既に開始しております。","id":"exchange-051"},{"speaker":"山路委員","kind":"質問","question":"２つ目の質問にまいります。しかし、環境機器や設備はまだ値段が高いようです。そこに品川区が環境行動を起こし現実を改善していくならば、またそうすることによってＣＯ２削減が着実に進み、京都議定書の意義が生かされていくと考えるものでありますが、そこで、品川区として環境対策事業展開における初期投資、ランニングコストとの関係について、今後どのような判断をされていくのか、お伺いをいたします。","respondent":"岩崎環境清掃事業部長","answer":"そういう文脈で考えますと、若干高めの新しい省エネ型の電気機器を家庭に導入できるように普及すれば、大分ＣＯ２問題は改善するのではないかというふうに思っております。","id":"exchange-052"},{"speaker":"山路委員","kind":"提案","question":"今ご説明がありましたことを前提として２つ目の質問はクリーンエネルギーの切り札としての燃料電池の導入についてであります。それで、品川区において、区有施設、学校施設、いろいろありますけれども、この新しく開発されました燃料電池を早期導入されることを提案するものですが、環境清掃事業部としてどのようにお考えでしょうか、ご所見をお伺いいたします。","respondent":"岩崎環境清掃事業部長","answer":"そういうふうなことでかなり有望なＣＯ２の家庭での削減が図れるような内容なんだろうというふうに推測しているわけですが、これを実際に学校とか区の施設とかということで導入するかどうかというのは。","id":"exchange-053"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひ研究していただきたいと思いますが、小泉総理も３月、新しい首相公邸に設置したということが新聞で報道されておりました。それですので、もう全国の自治体でも現に入れているところもあるですので、品川区でも早期に研究、調査をして入れていただきたいと思いますが、この点につきまして、もう一度ご答弁をお願いいたします。","respondent":"岩崎環境清掃事業部長","answer":"今言われているのが１０年間のリース料が１００万円ですので、それ以外にガス料金が若干割り引かれるようですが、引かれるですので、やはり数年は普及するのにはかかるかなというふうに思っているところですので、その値段がどのぐらい安くなるか。","id":"exchange-054"},{"speaker":"山路委員","kind":"提案","question":"先ほど申しました初期投資とランニングコストの関係をもう一度考えてご検討いただきたいと思います。３点目の質問は幾つか提案も含めてお伺いいたします。１つ目は、以前にも同僚議員が提案をいたしましたマスコットキャラクターの作成です。それぞれ区民の方のご意見もありますけれども、新しい事業の中でこういうアイデアを生かした取り組みをしていただきたいと思いますが、どのようにお考えでしょうか。","respondent":"岩崎環境清掃事業部長","answer":"過去のを調べるとそういうことだったわけですが、キッコロ、モリゾーとまでは行かなくても、何かそういうものを持ちたいなという気持ちはあります。今後検討してまいりたいと考えています。","id":"exchange-055"},{"speaker":"大西委員","kind":"質問・要望","question":"私のほうから品川区民連合を代表いたしまして総括質疑を行わせていただきます。しかしながら、残念ながら昨年、年末１１月でしたでしょうか、起こりました品川の女子中学生２名が逮捕されるという事件が暴力のことでございました。およそ４年生ぐらいからですから、１０歳から１５歳、１０年後には間違いなく２０歳から２５歳ぐらいになるわけですけれども、まさしく日本の若者を代表する子どもたち。","respondent":"古川教育次長","answer":"小学校の３年生で実施したい、こういうことです。","id":"exchange-056"},{"speaker":"大西委員","kind":"質問・要望","question":"続きまして、学校の安全についてお尋ね申し上げます。その考えを後でお尋ねしたいのと、それともう１点が、私は今こそ学校の治安ということに関しては、学校と地域が結びつくことが大変重要じゃないかなと。だから、ここで学校の職員とそして親御さんが一体となって地域に働きかけていく、ぜひ地域の皆さんで子どもたちを守ってくれないですかというお願いをする。厳しいほどにチェックしていく。","respondent":"古川教育次長","answer":"参考のために申し上げますと、４つの学校では教室にさすまたを置いているようであります。なお、教室における不審者対策としては、いすを使った防御ということを現在でも進めておりまして、必ずしもさすまたによらない対応があるだろうというふうに考えてあります。","id":"exchange-057"},{"speaker":"大西委員","kind":"質問・要望","question":"今、答弁の中で４校の学校が教室の中にさすまたを配備している。なぜか。しかし、それをよその品川区の小学校は知らないという点で、私は共通の価値観というんですか、そういうものが少し足りないのかな、教育力に対する欲求が足りないんじゃないかな、私はそういう部分で教育委員会が積極的に前に出ていって、こういう取り組みが紹介された、これがいい悪いは、その学校での判断だと思います。","respondent":"若月教育長","answer":"そういったところにもきちんと目を向けて、地域全体の安心、安全をつくるためにどうしたらいいかということを考えていかなければ、そのとき、そのときの対応で終わってしまうんではないだろうか、こんなふうに考えているところであります。","id":"exchange-058"},{"speaker":"大西委員","kind":"質問","question":"続きまして、品川歴史館のことについてですが、この品川歴史館、私は、この品川区で生まれ育った子どもたち、そして今住まわれている方々の８５％から９０％の方たちがこのままもっと品川区に住んでいたい、このように言われている品川区ですが、この品川歴史館が今小学生、中学生から５０円ずつぐらいでしょうか、料金を取っているということになっていると思うんですけれども。","respondent":"古川教育次長","answer":"条例ですので、議会の議決を経ながら、今そういう形で実施しているわけですけれども、この使用料をどう考えるかということだと思ってありますけれども、私どもはこの中で、観覧料の減免の規定がもう一つございまして、これをかたく解釈いたしますと。","id":"exchange-059"},{"speaker":"大西委員","kind":"質問","question":"ただいまの解釈をいただきましてありがとうあります。そのような解釈をしていただけることは、子どもたちにとっては大きな財産に先々なってまいるものと思います。続きまして、不登校児についてのことですが、現在、品川区で小中学生における不登校児を何名ぐらいと把握されておりますでしょうか。","respondent":"古川教育次長","answer":"不登校児の現状ですけれども、これは平成１５年度でとらえている中ですが、小学校３７名、中学校１３７名というふうにとらえてあります。","id":"exchange-060"},{"speaker":"大西委員","kind":"質問","question":"この辺に関しては、いかがなものでしょうか。","respondent":"古川教育次長","answer":"先ほど申し上げました不登校という形で、ご説明申し上げましたが、その内容はさまざまです。","id":"exchange-061"},{"speaker":"大西委員","kind":"意見","question":"私は、ぜひ虐待予防電話の設置、気軽に区民が警察ではない、品川区のほうにいつもどなり声が聞こえるんだ、子どもの泣き声が真夜中でも聞こえるんだ、最近どうもあそこの子どもの様子がおかしい、姿を見かけない、こういう子どもたちがいたときに、気軽に電話できて、そしてそれに速やかに対応できる行政があってもよいんじゃないかなと思うんですが、この点に関しての見解を聞かせてください。","respondent":"新美福祉高齢事業部長","answer":"現在、品川区におきましては、高齢者の虐待の問題につきましては、既に虐待の疑いを含めて発見された方は、地域に配備しております在宅介護支援センターにご連絡いただければ、第１次対応をいたします。","id":"exchange-062"},{"speaker":"大西委員","kind":"質問・要望","question":"とれないようなやつ。もしそれでその人が自転車を動かそうとするなら、係員なり、今ありますね、今度花子と太郎ですか、何か猫が２匹ぐらいいるような公園のところに返還された駐輪場がありますけれども、そういうところにその取り締まられた人が来て、そしてそれをあけてもらうという形ででも対処するというのも１つの手じゃないかなというふうに考えますが、見解のほうはいかがでしょうか。","respondent":"中谷まちづくり事業部長","answer":"そして行政が言うだけではなくて、地域ぐるみでのそういう放置、放輪をさせない、そういうような運動にしていこうということで取り組み始めたところで、来年度、そういう意味では武蔵小山でも予定しています。","id":"exchange-063"},{"speaker":"大西委員","kind":"質問","question":"まちづくり事業部長のこの駐輪場にかける意気込み、そして成果を高く評価いたしまして、また感謝申し上げます。そして、続きまして高齢者介護ですけれども、学校給食の配食、小学校の配食は現在２食ですが、先般アンケート等を実施したと思いますが、このアンケートの結果についてちょっとご報告をお願いします。","respondent":"山田区民生活事業部長","answer":"地域総合支援活動の一環でありますこの地域食事サービスのアンケート、昨年の１２月に実施をいたしました。ボランティアの方、受給をされているすべての方に郵送で実施をいたしまして、６３０名中回答が４７８名ということで、７５％の回答をいただいたところです。","id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"ちょっと私の質問の仕方が悪くて。このアンケートの結果で、受給、これはボランティアの方と、それと受給されている方、２つのアンケートだったと思うんですけれども、受給されている方からの回答率ですね、これが何名あったかというのをちょっと教えてください。","respondent":"山田区民生活事業部長","answer":"お尋ねの受給をされている方は２８３名おりまして、そのうち１７８名の方、６３％の方のご回答をいただいているところです。","id":"exchange-065"},{"speaker":"大西委員","kind":"質問","question":"受給者がどういう気持ちでいるかがわからない。その方が食事を受け取る。これは受給者が回答していないのはなぜかと考えると、今の回答がなかったのはありがたいとか、おいしいとかいう回答がありましたけれども、私はこの１００名の方々がなかなか回答する能力、いろんな面、要するに郵便局に行くだとかいろんな形でのものがないんじゃないかなと。これに対する対応というのは何かされているんでしょうか。","respondent":"山田区民生活事業部長","answer":"ですから、本来であれば郵送だけではなくて、もし回答がなければ、ボランティアの方に大変恐縮ではありますけれども、あわせて回答をいただくという手もあったかなというふうには思ってありますが、特段の２次対策としては、とってはいないという状況ですので。","id":"exchange-066"},{"speaker":"大西委員","kind":"質問","question":"この中で、私がスウェーデンでもできるだけ高齢者に自分たちができることは自分たちでやってもらって能力を高めていこうということがありましたけれども、私はその一環として筋力維持、それと栄養補給という観点から、私は小学校、中学校において、通うことのできる高齢者には学校の中で給食を配食する、そして、それを子どもたちが配膳するという、子どもと高齢者とのふれあいの場ということと。","respondent":"山田区民生活事業部長","answer":"いわゆる通所型の食事サービスかというふうに考えるわけですけれども、品川区では、いわゆる通所型については保育園でふれあい給食ということで園児との交流をしていくということを週１回から２回、現在１２園で実施をしております。","id":"exchange-067"},{"speaker":"大西委員","kind":"質問・要望","question":"先般少し申し上げたんですけれども、西五反田のさくらハイツでしょうか、あちらのほうでお元気なお年寄り、このお年寄りたちには１週間２１食の提供の用意があるということと、今高齢者で、先ほど言う構成要件が非常に厳しい、自分で調理ができない、買い物に行けないという人に対しては２食であるという私は整合性がどうもつかない。そのさくらハイツでは７０％以上が食事をとっているということですね。","respondent":"山田区民生活事業部長","answer":"品川区と大崎のホテル旅館組合と災害協定を結んでおりまして、こういった方々を優先的にいわゆるそちらのほうに移っていただくことなども検討しています。","id":"exchange-068"},{"speaker":"大西委員","kind":"質問・要望","question":"総体数で私はどうも不安に思うのが、おそらくかなりの人数がいて、そして受け皿的にちょっと少ないんじゃないかなという点を危惧しておりますので、ぜひその点に配慮いただける施策を願えればと思います。そして、最後になると思いますが、この庁舎の上に日の丸がかかっておりますが、この日の丸を掲げている意味というのをちょっとお聞かせいただきたいと思います。","respondent":"本間総務部長","answer":"掲揚しております国旗についてのお尋ねですが、国旗は国の象徴として末永い平和と繁栄の願いを込めまして、敬意を持って扱われているもので、慣習的にこの庁舎の屋上、区旗と都旗とともに掲出しておりましたが、ご案内のとおり。","id":"exchange-069"},{"speaker":"大西委員","kind":"提案","question":"ブルーのリボンとともに日の丸をつけてほしい。これは何かというと、これは拉致被害者の考え方です。私の考え方も同じですが、日本の国家の主権が侵されている。その点に関して私は拉致被害者が全部戻るまで、この横田さんが住んでいた品川区が自治体として懸垂幕を北朝鮮に対して日本の拉致被害者の早期返還を願うという懸垂幕を掲げることを提案するんですが、いかがでしょうか。","respondent":"本間総務部長","answer":"現在、区では全国知事会、これは全国市長会が中心となって進めております拉致被害者・家族義援金委員会というところがパンフレットを発行してございまして、これを庁舎内のカウンターに置くなどして協力できる分については協力しておりますので。","id":"exchange-070"},{"speaker":"大西委員","kind":"質問","question":"先ほど部長の答弁の中で末永い平和を願うということでしたが、日本国民の平和、これが今脅かされているというのが実情ですので、ぜひそういう拉致されている方が今まだここに存在しているということを品川区も行政として考えていただければと思います。私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"そこで質問ですが、品川区の学校給食が民間委託でこそ担っていけると判断したその理由、根拠は何でしょうか、ご説明ください。質問の２つ目は、一度に大量の学校給食をつくるわけですから、何よりも安全であることが最優先です。なぜ学校給食がとりわけ安全衛生管理に注意をしなければならないのか、特にここは大事な問題となりますので、詳しく説明していただければと思います。","respondent":"古川教育次長","answer":"そもそも品川区における給食業務というのは、保育園と学校でそれぞれ実施しております。現在も実施しているわけですが、５年前に保育園において業務代行を導入いたしました。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"戸越台中学校にしても３００食つくるわけですけれども直接その子どもたちが口に入れるものですから、特に抵抗力の弱い児童に対しての安全面のことが大事であると同時に給食を通じて正しい食生活をつけていく、こうした教育の一環であることも忘れてはなりません。このことは款別審査でも伺いましたが、明確な答弁がありませんでしたので改めて伺いたいと思います。","respondent":"本間総務部長","answer":"事故をいろいろ起こしているというご指摘がございましたが、全国展開している給食の業務でございまして、それで、いろいろとこういう事故が起きた場合に、当然、会社として保健行政、その他でペナルティーを課せられ、このペナルティーを受け、きちんとした業務改善を行って。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"そもそも私が先ほど伺いたかったのは、この業者が頻繁に食中毒を起こしていることを知っていて仮契約を結んだのか、それとも何ら調査もせずに仮契約を結んだのか、こちらのどちらなのかを伺いたかったんです。なぜかというと、今年の４月で３校、今後７年間かけて区内の５８校すべての小中学校でこの委託を進めると伺っています。この業者のことを、今回の食中毒のことを品川区が知ったのはいつですか。","respondent":"本間総務部長","answer":"こういう意味では、公平性という意味から従前従来やっている、こういう都内の事故情報の把握ということをやっているです。それから、この事実を知ったのはいつかですが、本年の３月３日、品川区のほうに連絡がございました。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"先ほど３月３日に知ったと話しましたけれども、この事件は２月１２日から１６日にかけて発生しているわけですよね。私は、食中毒を繰り返し起こしているこの業者を、どうして営業停止まで、１週間の営業停止を食らっているわけですよ。これがなぜそう成熟した業者と言えるのかどうか。そこで伺いたいのは、保護者に対して業者の選定をどのように進めていると説明したのかどうか、伺います。","respondent":"古川教育次長","answer":"給食調理の衛生基準の確保、安定した業務が円滑に行われるよう学校と教育委員会および受注業者や給食関係者との連携を図る仕組みを検討してまいりますということでありまして。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"でも実態は、今回の業者の件はどうですか。先ほども保育園給食の成果のことを学校給食の拡大の理由にされましたけれども、保育園給食でほんとうに安全、衛生面が向上してきたかということを伺いたいと思います。これは一体どういう事故だったのか。これが教育委員会自身が保育園給食のこの何をもって安全だと、民間のほうがより向上するんだと判断したのか、教えてください。","respondent":"青山品川区保健所長","answer":"中延保育園で平成１２年１１月２日から８日まで起こりましたＳＲＳＶ、これは今はノロウイルスというふうに呼称が変わっておりますが、イコールとお考えください。ＳＲＳＶによる感染性胃腸炎の集団発生についてご報告申し上げます。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"中延保育園の説明がありましたけれども、私が先ほど説明した教育委員会の答弁がないので、それついてきちんと答えていただきたいと思います。教育委員会は、何をもって保育園給食を安全だと判断されたのかきちんと答弁してください。","respondent":"古川教育次長","answer":"中延保育園における先ほど来の質疑の内容をとらえましても、保健所の判断といたしましても、これは給食からの感染がない、こういうことでありますから、保育園における問題があるとすれば、私はそういったことについて、この５年間大きな問題点はないという中で。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"そこがおくれてしまった。私はあまりにもこの安全管理が他人ごと任せ、子どもの安全が二の次に回されているんじゃないかと思い、４月からの委託は中止すべきではないかと考えています。今回の業者は辞退となりましたが、それでは、次はどこと契約を今結ぼうとしているんですか。それも選定理由はどういう基準とどういう調査をして、よしここならいけるぞと判断されたのか、あわせて教えてください。","respondent":"小沼児童保健事業部長、本間総務部長","answer":"今、中塚委員のほうから報告云々というお話がございましたけれども、これは私どものほうは平成１２年１１月２７日、厚生委員会のほうへきちっと報告させていただいてあります。それと、今回事態を受けまして、入札をやり直しています。入札を再度実施をいたしまして、別の業者に内定しています。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、区民には報告したんですか。具体的には区報には載せたんですか。そこの１点だけ答えてください。これはちょっと古いですけれども、２０００年７月３１日の「日本食糧新聞」という記事です。私は、しっかりと検討会を設けてさまざまな意見をやるべきだと思いますけれども、品川区ではいつだれがどのように契約の方法、中身の方法、さまざまなメニューの方法を検討してきたのか説明ください。","respondent":"小沼児童保健事業部長、本間総務部長","answer":"国への報告云々というのはちょっと私は理解できませんので、その点につきましては差し控えさせていただければと思います。辞退いたしました業者の後に再度入札をして内定している業者ですが、２３区だけを見ましても１５区の小中学校でこの給食調理の業務代行をやっている実績がございまして。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問","question":"中延保育園は厚生委員会に報告したのはわかりました。具体的に広報に載せたのかどうか。載せないのであれば、なぜ載せなかったのか、教えてください。伺いたいのは、２３区の中で学校給食を委託する前、その決定を下す前ですね、２３区の中で一体幾つの区が検討委員会を設置したのか教えてください。さらに２３区の中で学校給食が委託された学校、栄養士の配置基準を説明してください。","respondent":"青山品川区保健所長、古川教育次長","answer":"今回の場合、中延保育園の場合には、感染性胃腸炎というふうに判断いたしましたので、感染性胃腸炎ということになりますと、その保育園の食事そのものが直接の原因ではなかったということになりますので、そうだとすると。２３区のことを取り上げるつもりはあまりないわけなんですが、ほとんどの区では、多分検討委員会を設置したというふうに伺っています。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"先ほど答弁がなかったんですけれども、私のほうで調べたところ、民間委託を決定するまでに検討会を設置した区の数は全部で１９区あります。さらに、民間委託を決定する前に、区民に対して情報提供を行ったところは１８区ありました。これには相当な技術が要る。そもそも教育次長は学校給食の状況をきちんとご存じなんでしょうか。熟練するには何カ月ぐらい必要だと思っていますか、教えてください。","respondent":"古川教育次長","answer":"どちらが民間の力を借りた業務代行にふさわしいか。考えるまでもないわけでして、学校における短時間に労働力を投入するこの業務こそ民間への業務代行にふさわしい、私はそう思っております。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問","question":"学校では、例えばある小学校では、１年間で３２０種類の料理をつくるそうです。それを支えているのが栄養士です。なぜ品川区は栄養士を配置しないんですか。隣の目黒区に話を伺ったところ、委託が決定した１年前には栄養士を張りつけて、それで行っていると言いました。私は改めて学校給食の検討委員会の設置、そして栄養士の配置がどうしても必要ではないかと思いますけれども、ご答弁をお願いします。","respondent":"古川教育次長","answer":"保育園における実績、それを踏まえての学校への導入でありますので、改めて検討委員会等を設ける必要は私はないと思っていますし、この間、２月８日の戸越台中学校における学校だよりのお知らせ以降、３つの学校でそれぞれ保護者会、ＰＴＡ。","id":"exchange-082"},{"speaker":"中塚委員","kind":"意見","question":"最後に私は、子どものこの体をつくる学校給食、他の区は１９区が検討委員会を設置し、そしてすべての小学校、中学校で栄養士を配置している。事前の検討会も行わない、事前の説明会も行わない。戸越台中学校に至っては、２月に発表して４月に実施。なぜ子どもたちがおいしいと評判の学校の給食を変えなければならないのか、私は今までどおり直営を存続すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"南委員","kind":"質問","question":"中塚委員に引き続いて、私が総括質疑を行います。私が質問したいことは少子化社会克服に区がやらなければいけない施策は何か。とりわけ子育て支援ということで、保育園の充実、そして負担軽減、働き続ける女性の支援、これについて質問したいと思います。そこでまず、品川区が保育行政を進めておりますけれども、保育園の役割というのは何と考えていらっしゃるのか、伺いたいと思います。","respondent":"小沼児童保健事業部長","answer":"保育園の役割ですけれども、保育園はいろいろありますが、今児童福祉法を例にとりますと、日々保育にかけるお子さん、子どもを預かり、健全育成に努める。これが保育園の通例の一番の骨格です。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"ベッドの上で寝ているだけの赤ちゃんでもベッドの上から耳と目を集中させて音の聞こえるほうに振り向いたり、目の前を通るものを追っていく、そこから人とのかかわりを求めるスタートが始まっていくわけです。それと同時に、標準的な保育園で、職種ごとにどれだけの人数が減ってきているのか、そして区はそういう事態に対してどういう認識を持っていらっしゃるのか伺います。","respondent":"小沼児童保健事業部長","answer":"これはすべて正規の数でお考えいただければと思います。それから、昭和７９年度、つまり平成１６年度ですが、これにつきましては正規の職員が１９名というような状況ですので、その差が約９名ほど適正化している、こういうふうになってあります。","id":"exchange-085"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますと、トータルでは何人になるか、ちょっとそこまで答えていただきたかったので教えていただきたいと思います。調理師が４人とおっしゃったのかしら。ですから同じかな。保育士がマイナス３ですよね。栄養士も用務もそれぞれ１ということで、５マイナスということですよね。特例、長時間保育をやっているわけですから。そういうところをフォローするのに、どういう体制をとっているんでしょうか。","respondent":"小沼児童保健事業部長","answer":"当然ですけれども、１日のあるいは時間帯によって動線というのは変わってあります。当然変わるわけですけれども、保育動線というのが変わります。それにつきましては園長のほうで状況を判断して、与えられている人員の中で適正に配置して取り組むというのが実態です。","id":"exchange-086"},{"speaker":"南委員","kind":"質問","question":"スキルが違うというふうにおっしゃいました。確かにスキルは上がっているのかもしれません。さまざまな研修を受けて、それが当然のことだというふうに思います。しかし、現実的に子どもの育ち、発達していく過程は昔も今も変わらないんです。そこは忘れてほしくないというふうに思うんですね。その点については、いかがですか。","respondent":"小沼児童保健事業部長","answer":"見方によりますと、既存の日本の幼稚園あるいは保育園に対する体制への挑戦ですけれども、従来のような処遇のやり方あるいは育成の仕方と現実の保育園での子どもの処遇なり親への対応ではにっちもさっちもいかないというようなことで、この４月から始まるわけですが。","id":"exchange-087"},{"speaker":"南委員","kind":"質問","question":"私は全く質問していることに対して答えていただけていないというふうに思います。しかし、品川区は先ほど明らかにしたように、１時間当たりの職員の配置は昔に比べればすごく薄くなっています。この非常勤職員は今度７時間から３時間に全部切り替えていくというふうになっていますけれども、１日の保育時間の中で、どういう配置をしていくというふうに考えているんでしょうか。","respondent":"小沼児童保健事業部長","answer":"〔「配置について答えてない」と呼ぶ者あり〕 ３時間のあるいは配置というのは各園の園長のほうがその現場の状況を見て配慮するわけですから、今ここで個々具体的なところでどうのこうのというのは決して適するものではないと思います。そういうことです。","id":"exchange-088"},{"speaker":"南委員","kind":"質問・要望","question":"聞いてもいないことを長々と答弁していただきましたけれども、児童保健事業部長のほうは、いいですよね、時間のカウントはないんですから。私は３時間の非常勤職員の配置について伺ったのは、１日の保育時間の中でどういう時間帯に配置さているのかということで聞いたんですけれども、そのことをちゃんと答えないと次の質問に行きませんのでお願いします。","respondent":"小沼児童保健事業部長","answer":"そういうことです。ですから、ペーパーの問題で配置するのではなくて、その動線、状況に応じて、その３時間非常勤をどう配置していく、この配置の仕方につきましては、現場の園長のほうの裁量に任されている、こういうことです。","id":"exchange-089"},{"speaker":"南委員","kind":"質問","question":"そういう子どもの気持ちをどういうふうに保育者としては受けとめて、そして子どもの発達を保障するとしている品川区はそこをどういうふうに見たらいいんでしょうか。私は子どものこういう気持ち、そういうふうなことを失望感を与えさせないのが保育園の保育者の役割だというふうに思うんですけれども、その点については、どういうふうに考えるのか、伺います。","respondent":"小沼児童保健事業部長","answer":"もしそういう点でるる問題があるということであれば、それはそれなりに改善していけばよろしいことでありまして、少なくとも私のところには、今委員がおっしゃられたような話というのは寄せられてございません。","id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"児童保健事業部長はそこまでリサーチしていないんじゃないでしょうか。そういう点から、非常勤の職員配置では子どもの発達は保障できないということを強く申し上げておき、強く改善を求めたいと思います。２年を勤めれば３年目は休まなきゃいけないとか、あるいは社会保険がつくんだろうかとか、そういう点で非常に心配を持っていらっしゃいますから、その点について答弁をお願いします。","respondent":"本間総務部長","answer":"３時間の非常勤の社会保険の関係ですが、これは当然ながら、社会保険は勤務時間に応じて法律で定められておりますので、当然ながらそれにしたがいまして、それで３時間の非常勤ですと、これまで同様、社会保険の適用にはならないということになってあります。","id":"exchange-091"},{"speaker":"南委員","kind":"質問","question":"保育料についてなんですが、私はやはり子育てをするということは、経済的な負担が一番大きいというふうに思っておりますけれども、そういう点で保育料については、品川区は３年間で２７％、これは撤回をするべきじゃないかなというふうに思いますので、改めてこの点についての答弁をお願いします。","respondent":"小沼児童保健事業部長","answer":"保育料の問題ですけれども、撤回については考えてございません。","id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"一緒に聞けばよかったんですけれども、定率減税が縮小廃止されることによって増税にならざるを得ない。これについては当然保育料は上がるわけですけれども、ここについてはどういうふうに考えていますか。","respondent":"小沼児童保健事業部長","answer":"ですから、その税制の転用をやめる、あるいはとらないということであれば別ですけれども、私どもは一番これがオーソドックスな公平性を担保する考え方だというふうに検討の結果としては出てありますので、これについては変える考えはございません。","id":"exchange-093"},{"speaker":"南委員","kind":"質問・要望","question":"児童保健事業部長は国の動きを調査していらっしゃらないんでしょうか。定率減税の縮小廃止に関してですけれども。さらに、品川区は１園また増設させるわけですから、こういう部分への負担軽減もするべきだというふうに思っておりますが、いかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"認証保育所の料金のほうの問題ですけれども、これについても先般来のご答弁申し上げてありますが、今の時点で別途保育料を補助するとか、それを別途私どものほうが負担するというふうなことは考えてございません。","id":"exchange-094"},{"speaker":"南委員","kind":"質問・要望","question":"これはほんとうに英断だというふうに思うんです。そういう点で、経済的負担をほんとうに区民の方々が軽減を求めていらっしゃる、ここにこたえているものだというふうに１つは思うわけで、こういう角度からの英断をこの保険料の問題でも品川区長としてぜひ検討していただきたいというふうに思っております。これは要望、強い要望にとどめておきたいというふうに思います。","respondent":"本間総務部長","answer":"女性の就労に対する意欲ですが、先般私どものほうで人権にかかわる意識調査を実施いたしました。","id":"exchange-095"},{"speaker":"南委員","kind":"質問","question":"品川区だって、この区役所内の女性の登用を４割目指していらっしゃるわけですから、そういう少なくとも４割になるように、区民を挙げてそういう体制をとるというのはほんとうに必要なんじゃないでしょうか。それで、あわせてで伺うわけですけれども、そういう点で保育園の充実というのは欠かせないというふうに思いますけれども、今後の保育需要、そして待機児解消策を伺いたいと思います。","respondent":"小沼児童保健事業部長","answer":"例えば施設を転用していくという話も、いわゆる学童関係ですけれども、そのようなところを転用していく、あるいは先ほどもちょっと出ましたけれども、いろいろと住宅ができるところにつきましては、保育所が必要であれば。","id":"exchange-096"},{"speaker":"南委員","kind":"質問","question":"保育需要がどんどん拡大されていくということで、地域的に幾つか挙げていられましたけれども、やっぱり地域だけではなくて、女性として先ほどもご紹介したように、品川区の調査では、人権啓発意識調査では２割５分が働き続けたいという、そういうデータを紹介してくださいましたが、しかし、２割５分というと女性のうちの４分の１ですよね。ですから、そういう子どもをいっぱい増やしてください。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"平成１７年度の予算を見ますと、平成１６年の借款債を除くと７.１％の強気の予算になっております。幼保一元化を含めまして、その前に先ほども言いました児童福祉費が大幅増というところにおいては、今高齢化社会における中で、この児童に対する社会資源の配分についてどういうふうに考えていくのか、なぜこのように強気の予算化をされているのか、その辺をお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"ただ、マクロ的に見ますと、そういうことは一面言えるということは事実ですけれども、これを単位費用当たり、１人当たりの子どもの費用、それから老人の費用というようなことで比べますと、こと品川区におきまして、私のほうの試算では、それほど大きな変化は来てございません。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"そういう中にありまして、次に幼保一元化に向けた就学前教育という視点でお聞きしたいと思いますが、先ほどもいろいろ質問が出ておりましたが、保育の質というのはどういうことを見ていけばいいのか、職員数で保育の質が語られるのだろうかということが非常に疑問を持ちます。一体品川区で考えている保育の質、それから幼児教育という考え方についてご答弁をお願いしたいと思います。","respondent":"小沼児童保健事業部長","answer":"保育の質の考え方ですけれども、保育の質につきましては、これは残念ながらというんでしょうか、当たり前と言えば当たり前なのかもしれませんけれども。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"他区になく、かなり進んでいる、そのために他区からの転居者が増えているというふうな現状でもありますけれども、この保育サービス、夜間保育、延長保育、いろいろありますが、それに対して、それをすることで、先ほど言われました保育の質というのはどういうふうになっていくのか、変わらないというふうに、今後の保育の中でもそう考えていいのか、やはりいろいろな面で削減、行革が進む中で。","respondent":"小沼児童保健事業部長","answer":"というのは、幼児教育のあり方、あるいは今後をめぐりまして、これは話をしてよろしいと思うんですが、実は明日、文部科学省のほうで私どものほうの学務課長と保育課長が全国の講師になって、品川区の取り組み方をるる話す予定になってあります。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"品川区が行われている保育事業、これは保育サービスの拡大を推進していきながら、保育の質も担保しているということのあらわれだと今ご答弁いただきましたが、それにあわせて今後幼保一元化という考え方が出てきました。品川区で目指す幼保一元化というものはどういうものなのか、子ども像、品川区の子どもたちがどうあるべきなのかという視点についてはいかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"子ども像云々という話ですが、実はこれは大変難しい問題がございまして、どういうふうにとらえるのかということになりますと、今確実にこうだということは言えませんけれども、少なくとも私がイメージしていますのは、抽象的な言葉であれば。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"少し具体的なことをお聞きしたいと思いますが、来年度、総合施設が大崎保育園、台場幼稚園で行われるということなのですが、なぜ幼稚園から、それから保育園からなのか、どのように具体的に進めていくのか、就学前教育という観点から、今の保育園と幼稚園の違いをどういうふうに統合して総合施設という考え方に持っていこうとするのか、その辺ご答弁をお願いいたします。","respondent":"高橋区長、小沼児童保健事業部長","answer":"それを品川区が勇気を持って実施をしていこう、こういう思いで大崎保育園と、それから台場の幼稚園にそれぞれモデルをつくって平成１７年に実施をしてみて、その結果によって、これを全幼稚園に広げていきたい。幼保一体化あるいは一元化というような関係のものですけれども、この間例えばいいことだと思うんですが、幼稚園と保育園のほうで１つの認識が一致できたのは、実は幼稚園の先生というのは、教諭というのは、なかなか２歳児の状況。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"それに合わせまして、保育の中でもいろいろサービスが行われているわけですけれども、特に夜間保育、この夜間保育に対してですが、もう６年目をしていると思いますが、子どもたち、それから保護者の状況がどうなっているのか、前からも非常に危惧するというふうに私のほうで質問をしているところではありましたが、その検証、それはいかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"実は今まだ中間の報告を受けた段階でございまして、最終的な報告というのはもうちょっとお時間がかかるかなと思いますが、私どものほうが夜間保育実施園の園長あるいは職員を通じて調査を２カ月ぐらいになりましょうか、３カ月ぐらいになるのかな。","id":"exchange-103"},{"speaker":"西本委員","kind":"確認","question":"その品川区の中で１０園もやるほどの必要性、要は拡大すれば拡大するほど、それは利用する、子どもたちにとっては非常にいい保育環境をということで努力はされているのはわかりますが、果たして子どもたちにとってどうなんだろうかという視点に立ったときに、今後の品川区としての夜間保育、延長保育の考え方はいかがになりますでしょうか。","respondent":"小沼児童保健事業部長","answer":"あくまでもこれは二重保育あるいは三重保育、そういうような子どもにとっていいように、大変な成長阻害といいますか、成長阻害というのはよくないんですが、成長にとって必ずしも好ましくないようなことを回避する、あるいは切り抜けるということに。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろんすぐなれて、なれれば非常に子どもたちも多いですから楽しく遊べる環境ではありますが、今、ゼロ歳児から２歳児が利用者が多いというところでは、そういう点におけると、このオアシスルームという考え方も考えていかなければならないんではないかなというふうに非常に思うわけですが、その辺の利用の方法について、子どもたちについての視点。","respondent":"小沼児童保健事業部長","answer":"それで、そこに預けられたというか、来ている子どもと遊んだり、遊ぶというか、話をしたり、あるいはじゃれ合ったりすることもありますけれども、私が知る限り、見る限り、あまり１０人中パニック、あるいはなかなか親御さんから離れないというような例はそうございません。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば保育園のほうではファミリー・サタディ子育て体験等々をしているわけですから、そこでまず保育園になれていただいて、そこを踏まえて預かりをする。それで、次に病時保育の件でご質問いたしますけれども、今も病児保育、１つの病院のほうでやっていただいておりますけれども、この病時保育を今後どういうふうに品川区で進められようとするのか、その辺はいかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"病時保育ですが、この２月から本格的に実施をしたわけですけれども、これも非常にやむにやまれる状況の中での開設ですので、今後、拡大していく、あるいはもっと延ばしていくというようなことは考えてございません。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう休みがとれる、そういう社会になっていただきたい。むしろ、それを推進するということをぜひ品川区としても進めていただきたいと思います。次に保育園ＰＴＡの促進になりますが、コミュニケーションがとりにくくなっているという今の親たちの現状ではありますけれども、今後、保育園ＰＴＡの流れをどういうふうに考えられているのか、それについてお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"保育園ＰＴＡですけれども、平成１７年度で一応設置完了というような見込みですので、これを受けまして、４月以降今まで積み上げてきたもの、その中で新しい保育園の事業展開を含めて、今後はＰＴＡ、そういうものと私どものほうとでいろいろと物事を協調して乗り切っていきたい。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今回保育園ＰＴＡが全園で行われるということが非常に期待を持っておりまして、それを軸に子育ての輪が広がればいいかなというふうに非常に望んでいます。この運営方法ですけれども、これは要望ですが、できれば、保護者の自主的な活動でお願いしていきたい、させていただきたいというふうに思っておりますが、この運営方法については、どのようにお考えになりますでしょうか。","respondent":"小沼児童保健事業部長","answer":"運営方法につきましても、それぞれの基本は大きなところでは同じなんですが、やはり現在スクールカラーというか、その園のカラーがそれぞれ大きな島、グループで幾つかに分かれるような状況も出てありますので、しかるべき時になりまして。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"いろいろな形ができるかと思いますので、ぜひ親のつながり、自主的な行動がとれるようにお願いしたいと思います。次に、児童相談所が品川区におりてくるわけですけれども、保育園の役割というのも非常に大切な役割を持っているんではないかなというふうに考えます。そういう意味では、保育園として児童相談所の機能をどういうふうに今後考えていくのか、その辺のお考えをお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"ちょっとわかりやすい言葉で申し上げますと、発達相談あるいはメンタルテスト、知能テスト、ＩＱのテストであるとか、あるいは発育にかかる問題であるとか、そういうふうなところですが、今後私どものほうで取り組む、あるいは取り入れるというようなことですし。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"次に特別支援教育についてご質問したいと思います。特別支援教育という言葉、それから制度、これがまず、なぜ今特別支援教育を必要とされるのか、その経緯も含めてご答弁をお願いしたいと思います。","respondent":"古川教育次長","answer":"特に現在、特別支援教育を必要とする大きな背景ですけれども、小中学校におきます通常の学級に在籍するＬＤあるいはＡＤＨＤさらには高機能自閉症の児童・生徒への対応、こういったところから、現在心身障害教育をめぐる状況が大きく変化してきておりまして。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"具体的なところでお聞きいたしますが、この特別支援教育が今後行われようとしているのですが、これまでは心身障害教育というのは、固定学級、それから通級指導学級で行われておりました。この特別支援教育を導入されますと、今後、心身障害学級はどのようになっていくのか、これらの関係についていかがでしょうか。","respondent":"古川教育次長","answer":"これはすべての学校の中で、そういう児童、お子さんに対して特別支援教室をつくりながら対応していく。こういうＡ、Ｂ、Ｃの３つの類型の中で、今後特別支援教室を中心とした教育が展開されている。このように考えてあります。","id":"exchange-111"},{"speaker":"西本委員","kind":"確認","question":"これからはＡタイプ、Ｂタイプ、Ｃタイプということで展開されるということになるわけですけれども、そうしますと、もう一度確認をしますが、そのＡＢＣのタイプが相互に発展していくというふうに考えていくべきなのか、それとも融合していってしまうという方向にあるのか、その辺の関係性はいかがでしょうか。","respondent":"古川教育次長","answer":"基本的な考え方といたしましては、先ほど来特別な支援の必要なお子さんに対する１つの教育的ニーズにこたえるというのがこの特別支援教育のそもそもの考え方でありますけれども、従来の心身障害学級のあり方そのものが大きく変わるというふうには考えてございません。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"今改築されている学校の図面を見ますと、特別支援教室というのが配置されているわけですけれども、これは改築以外の学校でも今後整備されていくのではないかなというふうに考えるわけですが、この特別支援教室の利用の方法というのはどのように考えていかれるのでしょうか。","respondent":"古川教育次長","answer":"特別支援教室の中での事業の形態ということになろうかと思いますが、いわゆる学習に障害のある児童に対しまして、その困難な能力をどのような形で補っていくのか、さまざまな教材を使った指導でありますとか、あるいは同一の課題を繰り返して行うことで。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"そうすると、その特別支援教室というあり方は、固定的に考えるのではなくて、子どもたちの状況に合わせて、またクラスの状況に合わせて利用してくるんだという、そういう考え方でよろしいのでしょうか。","respondent":"古川教育次長","answer":"そういうお子さんがいなければ、特別支援教室というものはその学校の中にあえて設置される状況にはないと思いますが、少なくとも通常学級の中で、そういうお子さんがいて、そのための先ほど申し上げました教育的なシステムが必要であれば。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、その中で非常に重要になってきますのは、この特別支援教室で指導する専門的な方ですね。普通の教員も含めまして、この専門性に対してどういうふうに確保していくのか、その考え方はいかがでしょうか。","respondent":"古川教育次長","answer":"実は本年度、特別支援教育のための検討委員会を設けながら計４回にわたってさまざまな角度から検討いたしました。その検討の結果を踏まえて、平成１７年度に特別支援教育検討委員会のもとに巡回相談チームというものを編成しようと思ってあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"意見","question":"区民の理解と協力を得るというのはこの子どもたちや発達障害等を含めた子どもたちの支援には非常に必要なことだというふうに考えるわけですが、啓発活動については、どのように今後展開していこうとされるのか、その点についてご答弁をお願いいたします。","respondent":"古川教育次長","answer":"今後、学校関係者あるいは保護者への理解を求める努力を私どもはしていく必要があると思ってありますし、「教育のひろば」でありますとか、あるいは保護者会等でこういった特別支援教育の実態、そして今後の進め方、こういったことについては十分に学校のほうからご説明をし。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問","question":"次に品川区の教育改革についてご質問したいと思います。品川区の教育改革プラン２１が始まりまして５年ぐらいでしょうか、たったと思います。そもそも、なぜ品川区において、教育改革プラン２１を推進しようと考えたのか、その目的を改めて今の時期だからこそちょっとお聞きしたいというふうに思いますが、いかがでしょうか。","respondent":"若月教育長","answer":"こう考えたわけであります。そんな意味から、プラン２１と称しまして、教育改革の緒についたのが５年前、こういうことです。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"教師の意識を改革するというところで、このプラン２１が始まったということですが、では５年たった中で、まず学校選択から教育改革が始まった。それと、５年改革をした中で、その効果はどうだったのか、教師の意識は変わったんだろうかというその点についていかがでしょうか。","respondent":"若月教育長","answer":"これは大変大きな成果だと思います。そうした意識の変化から、各学校が子どもたちのより確実な学力定着のためにさまざまな努力や教材開発をするようになった。これも成果の１つだと認識をしております。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"その中でも教員たちの意識が変わってきつつあるというところでは、これからさらに改革を進めていただきたいなというふうに考えるわけですが、その中で、平成１８年度より大阪地区で小中一貫校が開校されます。さらに全区的に一貫教育というのが展開されるわけですけれども、なぜ教育改革で一貫教育なのか、その考え方はどういうふうに考えればよろしいんでしょうか。","respondent":"若月教育長","answer":"したがって、そこを認識し、先生方に小と中の壁や垣根を取り払ってこそ、ほんとうの子どもたちの９年間の全人的な成長が実現できる、そんな先生方の意識の改革、変化、こういったものをねらったもの、そして子どもたちの健全な成長と確かな学力を身につけさせたい。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"この品川区の教育改革プラン２１のゴールは何なのかなというところになりますが、一貫教育がゴールではないというふうに私は考えるんですが、教育委員会として、この先にある品川区の教育の目指すものは何なのか、その辺の将来にわたる展望について、ビジョンについてお聞きしたいと思います。","respondent":"若月教育長","answer":"ただ、そういってもそのためには当然トレーニングが必要であります。まさに今やっている改革は、そのトレーニングの一環である、こういうふうに考えております。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"トレーニング、これからどんどん改革していくんだ、最後にもう一度お聞きしたいと思います。今、教育改革プラン２１、確かに手法、手法というのはわかります。一貫教育にしても、習熟度別にしても細かい話はいろいろありますけれども、それはすべて手法であると。ただ、子どもたちにとって、どういう品川区の教育であるべきかというところの考え方、展望、それをお聞きしたいと思います。","respondent":"若月教育長","answer":"一言で申し上げます。区民から信頼される学校にしたい、それだけです。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に区長のほうからもご答弁いただきたいと思いますが、では、子どもたちの教育をどういうふうに考えていくのか、品川区の教育に関して一言お願いしたいと思います。","respondent":"若月教育長","answer":"よく言われることでありますけれども、自分、自己といったようなものをしっかりと確立した人間であるとともに、社会を構成する一員としての自覚をきちんと持ったバランスのとれた、個と公共とのバランスのとれた子どもたちを教育していきたいな、育てていきたいなと。","id":"exchange-122"},{"speaker":"西本委員","kind":"意見","question":"ぜひその意気込みで今後も品川区の改革をお願いしたいと思います。これで総括質疑を終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"三村委員","kind":"質問・要望","question":"お疲れのところだと思いますけれども、おつき合いいただきたいと思います。人口のピークは従来２００６年とされておりました。私たちは今まさに急な坂を落ちようとするジェットコースターのような状態ではないでしょうか。品川区として、今後５年間に照準を定め、待ったなしの少子化対策が求められると考えますが、品川区における少子化対策に対する今までの取り組みと今後の方針についてお聞かせください。","respondent":"中尾根企画部長","answer":"それと３つ目は社会が対応協力する環境づくりということで、地域における子育て環境への総合的な支援、これをしていかなくちゃならない、こういうのが当面の方針です。","id":"exchange-124"},{"speaker":"三村委員","kind":"意見","question":"しかし、年々子育てにかかる費用の負担感は増しております。しかし、一昔前の優雅な専業主婦像は今や圧倒的な少数派となっていることは、一生涯専業主婦を養えるだけの収入がある男性は全体の１割しかないという調査結果からも明らかです。こういった考え方も含め、企業による仕事と家庭に配慮した働き方の推進に対する品川区のお考えをお聞かせください。","respondent":"中尾根企画部長","answer":"区といたしましても、直接的に労働問題のところについては行政の守備範囲ではございませんけれども、できる限り区としてできる行為の側面はしていきたい、このように考えてあります。","id":"exchange-125"},{"speaker":"三村委員","kind":"意見","question":"ぜひよろしくお願いいたします。企業が仕事と子育ての両立に配慮をしたとしても、実際に子どもを預ける段階で預け先がなければ、仕事と子育ての両立は不可能となります。正社員からパート労働への変更は、生涯賃金において１億８,０００万円もの損失を生むとの厚生労働省の試算もあります。品川区における待機児ゼロ実現のための取り組みについてお答えください。","respondent":"小沼児童保健事業部長","answer":"平成１７年度につきまして、大崎だけで、大崎を中心に４０名。その他弾力化だとか、あるいは認証保育所の開設というようなことで１０７名の確保をしていくというようなことを考えてあります。","id":"exchange-126"},{"speaker":"三村委員","kind":"質問・要望","question":"待機児解消に向けて区として全力で取り組まれているということは十分理解をいたしました。入園基準を広く公表し、時代の変化に柔軟に対応していくよう求めますが、品川区のお考えをお聞きします。今後、品川区として、認可外保育園利用者への支援をしていくべきだと考えますが、お考えをお聞きいたします。","respondent":"小沼児童保健事業部長","answer":"それと、重要事項の説明というのが今後大きなものになってまいりますので、その辺のところも含めまして、見直しについては今後取り組んでまいりたいというふうに思っているところです。","id":"exchange-127"},{"speaker":"三村委員","kind":"質問","question":"２００２年の破産事件の実態として３０代の自己破産が最も多くなっております。その理由の６割が生活苦、低所得が原因となっております。２００２年からの調査から２年しかたっていないにもかかわらず１０％のアップとなっております。ここの一番支援の必要な層に対する品川区の支援としては、今後どのようなことを考えているのか、お聞きをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"三村委員","kind":"質問・要望","question":"質問の内容を明確にします。先ほども言いましたとおり、認可外保育園の利用者への支援というのはしないというお答えでしたけれども、ぜひ利用する立場に、利用者の立場に立って支援が必要だと考えておりますので、今後支援を検討していただきたいと思いますけれども、お答えのほうをよろしくお願いいたします。","respondent":"小沼児童保健事業部長","answer":"それで、開設されたり、いわゆる廃業されたり、転業されたり、非常に実態がつかみにくいというような点もございましてさまざまな形態があるというようなところで、１つには品川区としての補助には適さないというふうに考えてありますし、それから過去、私の体験例ですと。","id":"exchange-129"},{"speaker":"三村委員","kind":"質問・要望","question":"認可外というところでは信用がない、なかなか過去痛い思いをしたということなんですけれども、それでは、認証保育所のほうだけでも可能ではないかと、そちらでは東京都の支援を得てやっている事業でありますから、認証保育所利用者への支援というのもぜひご検討いただきたいと思います。要望として申し述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"}]},{"id":"topic-02","title":"質疑を終了いたします。 以上で平成１７年度品川区各会計予算についての質疑はすべて終了いたしました。 着席のまま、しばらくお待ちください。 次に、第５号議案","agenda":"質疑を終了いたします。 以上で平成１７年度品川区各会計予算についての質疑はすべて終了いたしました。 着席のまま、しばらくお待ちください。 次に、第５号議案","exchanges":[{"speaker":"宮崎委員","kind":"提案","question":"子育て世代の経済的支援の願いにこたえ、区として可能な支援策の１つとして提案いたしました。予算額の根拠ですが、今回の提案は、出生１人につき５万円の祝い金を支給するものです。ここ数年の区内の年間出生数は２,３００人から２,４００人という状況ですから、予算の策定に当たって２,５００人を想定いたしました。仮に必要となったとしても政務調査費の充当を考えるべきです。修正案から説明します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"石田委員","kind":"質問・要望","question":"休憩していただいて、理事会を開いていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの三村委員の発言の中で、我々議員が議決した条例に基づいて実施されております議会運営また費用弁償等の対応に対しまして、一般常識から外れている等の不適切な発言がございましたので、最後の議事録全般にわたり、このような質疑が行われたということから、三村委員の発言のうち、議会改革に関する議事録のすべてを削除することを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"三村委員","kind":"質問","question":"今回の予算に対して、区長のご意見をお伺いしたいということで、今回この問題を取り上げさせていただきました。なので、予算に対しての質疑ということでさせていただきましたので、削除の件についてはお受けできないというふうに表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"原委員","kind":"提案","question":"今後の各施策推進に当たっては健全財政を維持しつつ、自由民主党品川区議団との連携をなお一層深めていただくことを要望し、平成１７年度品川区一般会計予算を初め、各予算案に賛成し、共産党単独提案平成１７年度品川区一般会計予算修正案には反対し、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-135"},{"speaker":"中島委員","kind":"提案","question":"最後に、これまで予算特別委員会での款別審査におきまして、我が党の各委員より提案いたしました幾つかの要望およびふれあい掲示板など区が保有しているものの使用基準に関しましては、これまで区民の皆様からいただきました声を反映させたものですので、今後、区民に誤解を与えないよう厳格な対応を求めるとともに、区民にとって必要な政策提案に対しましては前向きに取り組まれることを重ねて要望し。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"},{"speaker":"高星委員","kind":"質問・要望","question":"私ども品川区民連合は、平成１７年度の一般会計、国民健康保険事業会計、老人保健医療特別会計、介護保険特別会計および用地特別会計の各予算につきまして、幾つかの意見、要望を申し上げ、これに賛成いたします。課題である財政自主権確立を求めつつ、２１世紀のあるべき品川区像およびその具現化を求める第三次長期基本計画、総合実施計画を着実に進展させる重要な予算であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"沢田委員","kind":"質問・要望","question":"それは第２のバブル崩壊の再現であり、その際、区長や開発推進の理事者は責任をとるのでしょうか。トンネル内の排ガスを２４時間フィルターなしに換気塔から放出、品川線の交通量は現状の２.２倍にもなるのにどうして環境は改善されるのでしょうか。借家人は区民ではないのでしょうか。改憲が俎上に上っているときにどうするべきなのか、国民的討議こそ今求められているのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"藤原委員","kind":"提案","question":"以下、その理由と幾つかの意見、要望を申し上げます。同時に、時間は少なくなっていますが、平成１２年改革の真価を実現し、品川区の新たな自治権確立と正常な都区制度関係確立のため、断固たる施設を貫くことを強く要望します。最後に我が会派委員が提案、要望した各項目につきまして積極的に受けとめていただき、区政運営に生かしていただきますことをお願いしまして意見表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"井上委員","kind":"提案","question":"２００５年度一般会計、国民健康保険事業会計、老人保健医療特別会計、介護保険特別会計、用地特別会計の各会計予算に意見と要望を以下に述べて原案どおり可決することに賛成いたします。学校給食の調理委託の実施では、関係者への説明を丁寧に行い、十分な理解を得るよう要望します。以上、生活者ネットワークの提案が今後の区政に反映されるよう要望し、意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-140"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270732?Template=document&Id=852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":129078,"voices":314}}]);
